 function seed_default_enquiry_masters_once(){
  if(get_option('bsoerp_default_enquiry_masters_seeded',false))return;
  global $wpdb;
  $now=current_time('mysql');
  $groups=[
   'customer-category'=>['BNI','Retail Shop','Dealer','Agency','Office'],
   'lead-source'=>['WhatsApp','Facebook','Instagram','Referral','Existing Customer'],
  ];
  foreach($groups as$type=>$names){
   foreach($names as$name){
    $existing=$wpdb->get_var($wpdb->prepare("SELECT id FROM {$this->t('records')} WHERE module='master' AND record_type=%s AND LOWER(TRIM(title))=LOWER(TRIM(%s)) LIMIT 1",$type,$name));
    if($existing)continue;
    $wpdb->insert($this->t('records'),[
     'module'=>'master',
     'record_type'=>$type,
     'reference_no'=>$this->next_master_ref($type),
     'title'=>$name,
     'status'=>'Active',
     'meta'=>wp_json_encode([]),
     'created_by'=>(int)get_current_user_id(),
     'created_at'=>$now,
     'updated_at'=>$now,
    ]);
   }
  }
  update_option('bsoerp_default_enquiry_masters_seeded',1,false);
 }
 function maybe_upgrade(){
  global $wpdb;
  $stored=get_option('bsoerp_version','0');
  $this->ensure_daily_activity_cron();
  if(version_compare($stored,self::VERSION,'>='))return;
  $this->activate();
  $this->ensure_lead_schema();
  $this->ensure_recce_schema();
  $this->ensure_design_schema();
  $this->repair_master_visibility();
  $currency_settings=get_option('bsoerp_settings',[]); if(is_array($currency_settings)&&(($currency_settings['currency']??'')==='₹')){$currency_settings['currency']='';update_option('bsoerp_settings',$currency_settings,false);}
  $wpdb->query("UPDATE {$this->t('records')} SET status='Pending Approval' WHERE module='quotations' AND status IN ('Draft','Pending Checking','Pending Sending')");
  $legacy=[
   'job-types'=>['work-order-types','Work Order Types'],
   'add-job'=>['add-work-order','Add Work Order'],
   'jobs-in-progress'=>['work-orders-in-progress','Pending Work Orders'],
   'jobs-master'=>['work-orders-master','Work Orders Master'],
   'job-items-master'=>['work-order-items-master','Work Order Items Master'],
   'completed-jobs'=>['completed-work-orders','Completed Work Orders'],
   'canceled-jobs'=>['canceled-work-orders','Canceled Work Orders']
  ];
  $pages=get_option(self::PAGES,[]);
  foreach($legacy as$old=>$new){
   [$new_slug,$title]=$new;
   $page=get_page_by_path('bizskill-erp-'.$old);
   if(!$page&&!empty($pages[$old]))$page=get_post((int)$pages[$old]);
   if($page){
    wp_update_post(['ID'=>$page->ID,'post_title'=>$title,'post_name'=>'bizskill-erp-'.$new_slug,'post_content'=>'[bizskill_operations_erp view="'.$new_slug.'"]']);
    $pages[$new_slug]=$page->ID; unset($pages[$old]);
   }
  }
  if(!empty($pages['partly-completed-recce'])){wp_trash_post((int)$pages['partly-completed-recce']);unset($pages['partly-completed-recce']);}
  else{$old_recce_page=get_page_by_path('bizskill-erp-partly-completed-recce');if($old_recce_page)wp_trash_post((int)$old_recce_page->ID);}
  update_option(self::PAGES,$pages,false);
  $this->create_pages(true);
  // Migrate all saved WhatsApp templates to the approved final formats.
  $wa_templates=get_option('bsoerp_whatsapp_templates',[]);if(!is_array($wa_templates))$wa_templates=[];
  $wa_defaults=$this->whatsapp_template_defaults();
  foreach(['task_add','task_update','lead_add','lead_update','recce_add','design_add','daily_activity_pdf'] as$wa_key){if(!isset($wa_templates[$wa_key])||!is_array($wa_templates[$wa_key]))$wa_templates[$wa_key]=[];$wa_templates[$wa_key]['body']=$wa_defaults[$wa_key]['body'];$wa_templates[$wa_key]['code']=$wa_defaults[$wa_key]['code'];}
  update_option('bsoerp_whatsapp_templates',$wa_templates,false);
  // Backfill Orders for quotations that were approved before automatic Order creation was introduced.
  // Normalize legacy quotation workflow records into the simplified client-approval workflow.
  $wpdb->query("UPDATE {$this->t('records')} SET status='Pending Approval' WHERE module='quotations' AND record_type='quotation' AND status IN ('Pending Checking','Pending Sending')");
  $approved_quotes=$wpdb->get_results("SELECT id,meta FROM {$this->t('records')} WHERE module='quotations' AND record_type='quotation' AND status='Approved' ORDER BY id");
  foreach($approved_quotes as$aq){
   $order_id=$this->ensure_order_from_quotation((int)$aq->id);
   if(!is_wp_error($order_id)&&$order_id){$qm=json_decode((string)$aq->meta,true);if(!is_array($qm))$qm=[];if(absint($qm['generated_order_id']??0)!==$order_id){$qm['generated_order_id']=$order_id;$qm['order_created_at']=$qm['order_created_at']??current_time('mysql');$wpdb->update($this->t('records'),['meta'=>wp_json_encode($qm),'updated_at'=>current_time('mysql')],['id'=>(int)$aq->id]);}}
  }
  update_option('bsoerp_version',self::VERSION,false);
 }
 function ensure_task_schema(){global$wpdb;$records=$this->t('records');$updates=$this->t('task_updates');$column=$wpdb->get_var("SHOW COLUMNS FROM $records LIKE 'task_owner'");if(!$column)$wpdb->query("ALTER TABLE $records ADD task_owner BIGINT UNSIGNED DEFAULT 0 AFTER assigned_to");$exists=$wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$updates));if(!$exists){$charset=$wpdb->get_charset_collate();$wpdb->query("CREATE TABLE $updates (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, task_id BIGINT UNSIGNED NOT NULL, update_text LONGTEXT NOT NULL, status VARCHAR(50) DEFAULT 'In Progress', created_by BIGINT UNSIGNED DEFAULT 0, created_at DATETIME NOT NULL, PRIMARY KEY(id), KEY task_id(task_id), KEY created_at(created_at)) $charset");return;}$update_status=$wpdb->get_var("SHOW COLUMNS FROM $updates LIKE 'status'");if(!$update_status)$wpdb->query("ALTER TABLE $updates ADD status VARCHAR(50) DEFAULT 'In Progress' AFTER update_text");}
