 function handle_erp_login(){
  if(!isset($_POST['bsoerp_login_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['bsoerp_login_nonce'])),'bsoerp_login'))wp_die('Invalid login request.');
  $identifier=trim(sanitize_text_field(wp_unslash($_POST['identifier']??'')));$password=(string)wp_unslash($_POST['password']??'');$remember=!empty($_POST['remember']);$redirect=esc_url_raw(wp_unslash($_POST['redirect_to']??$this->url('dashboard')));
  $fail=function()use($redirect){$login_url=$redirect;$login_url=add_query_arg(['login_error'=>'Invalid username/email or password.','redirect_to'=>$redirect],$login_url);wp_safe_redirect($login_url);exit;};
  if($identifier===''||$password==='')$fail();
  global$wpdb;$rows=$wpdb->get_results("SELECT * FROM {$this->t('records')} WHERE module='master' AND record_type='user' AND status='Active' ORDER BY id ASC");$match=null;$meta=[];
  foreach($rows as$r){$m=json_decode((string)$r->meta,true)?:[];$email=trim((string)($m['email']??''));if(strcasecmp(trim((string)$r->title),$identifier)===0||($email!==''&&strcasecmp($email,$identifier)===0)){$match=$r;$meta=$m;break;}}
  if(!$match||empty($meta['password_hash'])||!wp_check_password($password,(string)$meta['password_hash']))$fail();
  $email=sanitize_email($meta['email']??'');$display=sanitize_text_field($match->title);$wp_user=$email?get_user_by('email',$email):false;
  if(!$wp_user){$base=sanitize_user($email?strstr($email,'@',true):$display,true);if($base==='')$base='erpuser'.(int)$match->id;$login=$base;$n=1;while(username_exists($login))$login=$base.$n++;$created=wp_create_user($login,wp_generate_password(32,true,true),$email);if(is_wp_error($created))$fail();$wp_user=get_user_by('id',(int)$created);$wp_user->set_role('bsoerp_user');wp_update_user(['ID'=>$wp_user->ID,'display_name'=>$display,'first_name'=>$display]);}
  if(!$wp_user)$fail();$wp_user->add_cap('bsoerp_access');$wp_user->add_cap('bsoerp_print');update_user_meta($wp_user->ID,'bsoerp_master_user_id',(int)$match->id);wp_set_current_user($wp_user->ID);wp_set_auth_cookie($wp_user->ID,$remember,is_ssl());do_action('wp_login',$wp_user->user_login,$wp_user);wp_safe_redirect($redirect?:$this->url('dashboard'));exit;
 }
