 function theme_defaults(){return ['theme_style'=>'theme_color','theme_color'=>'#12b8a6','font_color'=>'#0b1220','secondary_font_color'=>'#374151','font_weight'=>500,'font_size'=>12,'border_color'=>'#12b8a6','table_header_bg'=>'#f2f4f7','card_bg'=>'#ffffff','button_text_color'=>'#ffffff'];}
 function theme_settings(){
  $s=get_option('bsoerp_settings',[]);$d=$this->theme_defaults();$t=is_array($s['theme']??null)?$s['theme']:[];$out=array_merge($d,$t);
  $theme_style_value=$out['theme_style']??'theme_color';
  $style=in_array($theme_style_value,['theme_color','black_white'],true)?$theme_style_value:'theme_color';$out['theme_style']=$style;
  $chosen=sanitize_hex_color($out['theme_color']??'')?:'#12b8a6';$out['theme_color']=$chosen;
  if($style==='black_white'){$out['theme_color']='#111111';$out['font_color']='#111111';$out['secondary_font_color']='#444444';$out['border_color']='#222222';$out['table_header_bg']='#f2f2f2';$out['card_bg']='#ffffff';$out['button_text_color']='#ffffff';}
  else{$out['border_color']=$chosen;$out['font_color']='#0b1220';$out['secondary_font_color']='#374151';$out['table_header_bg']='#f2f4f7';$out['card_bg']='#ffffff';$out['button_text_color']='#ffffff';}
  return$out;
 }
