 function flat(){ $f=[]; foreach($this->menu() as $k=>$s){if(!$s[1])$f[$k]=$s[0];foreach($s[1] as $x=>$l)$f[$x]=$l;}return$f; }
 function permission_views(){
  $views=[];
  foreach($this->menu() as $section=>$spec){
   if(in_array($section,['deliveries','admin'],true))continue;
   if(!$spec[1]){$views[$section]=$spec[0];continue;}
   foreach($spec[1] as$slug=>$label)$views[$slug]=$spec[0].' → '.$label;
  }
  return$views;
 }
 function master_user_permissions($master_user_id=0){
  global$wpdb;$master_user_id=$master_user_id?:$this->current_master_user_id();if(!$master_user_id)return null;
  $row=$wpdb->get_row($wpdb->prepare("SELECT meta FROM {$this->t('records')} WHERE id=%d AND module='master' AND record_type IN ('user','users')",$master_user_id));
  if(!$row)return null;$meta=json_decode((string)$row->meta,true);if(!is_array($meta))$meta=[];
  if(!array_key_exists('allowed_views',$meta))return null;
  return array_values(array_unique(array_map('sanitize_key',(array)$meta['allowed_views'])));
 }
function can_view_slug($view){
  $view=sanitize_key($view);if(current_user_can('bsoerp_manage')||current_user_can('manage_options'))return true;
  $master_id=$this->current_master_user_id();
  if($master_id){$allowed=$this->master_user_permissions($master_id);if($allowed===null)return true;if($view==='grn-master'&&in_array('grn-items',$allowed,true))return true;if($view==='daily-activity'&&in_array('dashboard',$allowed,true))return true;if($view==='designs-pending-approval'&&in_array('designs-in-progress',$allowed,true))return true;return in_array($view,$allowed,true);}
  $module=$this->module($view);$settings=get_option('bsoerp_settings',[]);return $module==='master'||in_array($module,(array)($settings['user_modules']??[]),true);
 }
