  }
  </style>';
  echo'<div class="user-view-permissions"><div class="user-view-permissions-head"><h3>View Permissions</h3></div><div class="table-wrap"><table class="data permission-table"><thead><tr><th colspan="4"><div class="permission-top-head"><span>Views</span><label><input type="checkbox" id="bsoerp-permission-select-all" '.checked(count(array_intersect(array_keys($views),$allowed)),count($views),false).'> Select All</label></div></th></tr></thead><tbody>';
  foreach($groups as$group_key=>$group){
   $slugs=array_keys($group['items']);$selected_count=count(array_intersect($slugs,$allowed));
   echo'<tr class="permission-group-row"><td colspan="4"><div class="permission-group-head"><span>'.esc_html($group['label']).'</span><label><input type="checkbox" class="bsoerp-permission-group" data-group="'.esc_attr($group_key).'" '.checked($selected_count,count($slugs),false).'> Select Group</label></div></td></tr>';
   $cells=[];foreach($group['items'] as$slug=>$label){
    $cells[]='<td><label class="permission-cell"><span>'.esc_html($label).'</span><input class="bsoerp-view-permission" data-group="'.esc_attr($group_key).'" type="checkbox" name="allowed_views[]" value="'.esc_attr($slug).'" '.checked(in_array($slug,$allowed,true),true,false).'></label></td>';
   }
   while(count($cells)%4!==0)$cells[]='<td class="permission-empty"></td>';
   foreach(array_chunk($cells,4) as$row)echo'<tr class="permission-four-row" data-permission-group="'.esc_attr($group_key).'">'.implode('',$row).'</tr>';
  }
  echo'</tbody></table></div></div><script>(function(){var all=document.getElementById("bsoerp-permission-select-all");if(!all)return;var boxes=[].slice.call(document.querySelectorAll(".bsoerp-view-permission"));var groups=[].slice.call(document.querySelectorAll(".bsoerp-permission-group"));function syncAll(){all.checked=boxes.length>0&&boxes.every(function(x){return x.checked;});}function syncGroup(key){var g=document.querySelector(".bsoerp-permission-group[data-group=\""+key+"\"]");if(!g)return;var gb=boxes.filter(function(b){return b.dataset.group===key;});g.checked=gb.length>0&&gb.every(function(x){return x.checked;});}all.addEventListener("change",function(){boxes.forEach(function(b){b.checked=all.checked;});groups.forEach(function(g){g.checked=all.checked;});});groups.forEach(function(g){g.addEventListener("change",function(){var key=g.dataset.group;boxes.filter(function(b){return b.dataset.group===key;}).forEach(function(b){b.checked=g.checked;});syncAll();});});boxes.forEach(function(b){b.addEventListener("change",function(){syncGroup(b.dataset.group);syncAll();});});})();</script>';
 }


 function whatsapp_value($value,$fallback='-'){
  if(is_array($value)){
   $value=array_values(array_filter(array_map(function($v){return trim((string)$v);},$value),function($v){return $v!=='';}));
   $value=implode(', ',$value);
  }
  $value=trim((string)$value);
  return $value!==''?$value:$fallback;
 }


 function whatsapp_replace_vars($body,$vars=[]){
  // Global WhatsApp rule: every blank or missing template value must render as '-'.
  foreach((array)$vars as$k=>$v)$body=str_replace('{{'.$k.'}}',$this->whatsapp_value($v),$body);
  $body=preg_replace('/\{\{\s*[A-Za-z0-9_]+\s*\}\}/','-',$body);
  return $body;
 }


 function whatsapp_user_contact($erp_user_id){
  global$wpdb;$erp_user_id=absint($erp_user_id);if(!$erp_user_id)return['name'=>'-','mobile'=>''];
  $r=$wpdb->get_row($wpdb->prepare("SELECT id,title,meta FROM {$this->t('records')} WHERE id=%d AND module='master' AND record_type='user'",$erp_user_id));
  if(!$r)return['name'=>$this->task_user_display_name($erp_user_id)?:'-','mobile'=>''];
  $m=json_decode((string)$r->meta,true);if(!is_array($m))$m=[];
  return['name'=>$r->title?:'-','mobile'=>trim((string)($m['mobile']??''))];
 }

 function whatsapp_normalize_mobile($mobile){
  $o=get_option('bsoerp_whatsapp_meta',[]);if(!is_array($o))$o=[];
  $cc=preg_replace('/\D+/','',(string)($o['country_code']??'91'));if($cc==='')$cc='91';
  $n=preg_replace('/\D+/','',(string)$mobile);
  $n=ltrim($n,'0');
  if(strlen($n)===10)$n=$cc.$n;
  return $n;
 }

 function whatsapp_template_config($key){
  $defaults=$this->whatsapp_template_defaults();$t=$defaults[$key]??null;if(!$t)return null;
  $saved=get_option('bsoerp_whatsapp_templates',[]);
  if(is_array($saved)&&isset($saved[$key])&&is_array($saved[$key]))$t=array_merge($t,$saved[$key]);
  // Template code/body are controlled by the approved Meta templates. Do not let
  // older saved settings re-introduce obsolete placeholder names.
  $t['code']=$defaults[$key]['code'];
  $t['body']=$defaults[$key]['body'];
  return $t;
 }

 function whatsapp_log_result($event,$to,$ok,$message,$response_code=0,$message_id='',$error_code='',$error_subcode='',$fbtrace_id='',$raw=''){
  $row=['time'=>gmdate('Y-m-d H:i:s'),'event'=>$event,'to'=>$to,'status'=>$ok?'Sent':'Failed','message'=>$message,'response_code'=>(int)$response_code,'message_id'=>$message_id,'error_code'=>(string)$error_code,'error_subcode'=>(string)$error_subcode,'fbtrace_id'=>(string)$fbtrace_id,'raw'=>(string)$raw];
  update_option('bsoerp_whatsapp_last_result',$row,false);
  $log=get_option('bsoerp_whatsapp_log',[]);if(!is_array($log))$log=[];array_unshift($log,$row);$log=array_slice($log,0,100);update_option('bsoerp_whatsapp_log',$log,false);
 }

 function whatsapp_send_template($event_key,$mobile,$vars=[]){
  $o=get_option('bsoerp_whatsapp_meta',[]);if(!is_array($o))$o=[];
  if(empty($o['enabled']))return false;
  $phone_id=trim((string)($o['phone_number_id']??''));$token=trim((string)($o['access_token']??''));
  if($phone_id===''||$token===''){$this->whatsapp_log_result($event_key,$mobile,false,'Phone Number ID or Access Token is missing.');return false;}
  $t=$this->whatsapp_template_config($event_key);
  if(!$t||empty($t['active']))return false;
  $template_code=trim((string)($t['code']??''));if($template_code===''){$this->whatsapp_log_result($event_key,$mobile,false,'WhatsApp Template Code is blank.');return false;}
  $to=$this->whatsapp_normalize_mobile($mobile);
  if(strlen($to)<11){$this->whatsapp_log_result($event_key,$to,false,'Recipient mobile number is missing or invalid.');return false;}

  $body=(string)($t['body']??'');$names=[];
  if(preg_match_all('/\{\{\s*([A-Za-z0-9_]+)\s*\}\}/',$body,$mm)){
   foreach($mm[1] as$n)if(!in_array($n,$names,true))$names[]=$n;
  }
  $parameters=[];
  foreach($names as$n){$raw=$vars[$n]??'';$text=$this->whatsapp_value($raw);$parameters[]=['type'=>'text','parameter_name'=>$n,'text'=>$text];}

  $payload=[
   'messaging_product'=>'whatsapp',
   'to'=>$to,
   'type'=>'template',
   'template'=>[
    'name'=>$template_code,
    'language'=>['code'=>'en'],
    'components'=>[['type'=>'body','parameters'=>$parameters]]
   ]
  ];
  $api_version=trim((string)($o['api_version']??'v23.0'));if(!preg_match('/^v\d+\.\d+$/',$api_version))$api_version='v23.0';
  $endpoint='https://graph.facebook.com/'.$api_version.'/'.rawurlencode($phone_id).'/messages';
  $res=wp_remote_post($endpoint,['timeout'=>30,'redirection'=>3,'httpversion'=>'1.1','headers'=>['Authorization'=>'Bearer '.trim($token),'Content-Type'=>'application/json','Accept'=>'application/json'],'body'=>wp_json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'data_format'=>'body']);
  if(is_wp_error($res)){$this->whatsapp_log_result($event_key,$to,false,$res->get_error_message());return false;}
  $code=(int)wp_remote_retrieve_response_code($res);$raw=(string)wp_remote_retrieve_body($res);$json=json_decode($raw,true);if(!is_array($json))$json=[];
  $message_id=(string)($json['messages'][0]['id']??'');
  if($code>=200&&$code<300&&$message_id!==''){$this->whatsapp_log_result($event_key,$to,true,'Message accepted by Meta.',$code,$message_id,'','','',$raw);return true;}
  $error=$json['error']??[];$err=(string)($error['message']??($raw?:'Meta rejected the message.'));$details=(string)($error['error_data']['details']??'');if($details!=='')$err.=' | '.$details;$error_code=(string)($error['code']??'');$error_subcode=(string)($error['error_subcode']??'');$fbtrace_id=(string)($error['fbtrace_id']??'');
  $this->whatsapp_log_result($event_key,$to,false,$err,$code,$message_id,$error_code,$error_subcode,$fbtrace_id,$raw);return false;
 }


 function whatsapp_test_token(){
  $o=get_option('bsoerp_whatsapp_meta',[]);if(!is_array($o))$o=[];
  $token=(string)($o['access_token']??'');$token=trim($token);
  $api_version=trim((string)($o['api_version']??'v23.0'));if(!preg_match('/^v\d+\.\d+$/',$api_version))$api_version='v23.0';
  $phone_id=trim((string)($o['phone_number_id']??''));

  $len=strlen($token);
  $preview=$len>=12?substr($token,0,6).'...'.substr($token,-6):($len?'(short token)':'(empty)');
  $diag=['time'=>current_time('mysql'),'token_length'=>$len,'token_preview'=>$preview,'phone_number_id'=>$phone_id,'api_version'=>$api_version,'status'=>'Failed','message'=>''];

  if($token===''){
   $diag['message']='Access Token is blank.';
   update_option('bsoerp_whatsapp_token_test',$diag,false);return false;
  }
  if($phone_id===''){
   $diag['message']='Phone Number ID is blank.';
   update_option('bsoerp_whatsapp_token_test',$diag,false);return false;
  }

  $url='https://graph.facebook.com/'.$api_version.'/'.rawurlencode($phone_id).'?fields=id,display_phone_number,verified_name';
  $res=wp_remote_get($url,[
   'timeout'=>30,
   'redirection'=>3,
   'httpversion'=>'1.1',
   'headers'=>[
    'Authorization'=>'Bearer '.$token,
    'Accept'=>'application/json'
   ]
  ]);
  if(is_wp_error($res)){
   $diag['message']=$res->get_error_message();
   update_option('bsoerp_whatsapp_token_test',$diag,false);return false;
  }

  $code=(int)wp_remote_retrieve_response_code($res);
  $raw=(string)wp_remote_retrieve_body($res);
  $json=json_decode($raw,true);if(!is_array($json))$json=[];
  $diag['http_status']=$code;
  $diag['raw']=$raw;

  if($code>=200&&$code<300&&!empty($json['id'])){
   $diag['status']='Success';
   $diag['message']='Token authenticated successfully with Meta.';
   $diag['meta_phone_id']=(string)($json['id']??'');
   $diag['display_phone_number']=(string)($json['display_phone_number']??'');
   $diag['verified_name']=(string)($json['verified_name']??'');
   update_option('bsoerp_whatsapp_token_test',$diag,false);return true;
  }

  $error=$json['error']??[];
  $diag['message']=(string)($error['message']??($raw?:'Meta rejected the token test.'));
  $diag['error_code']=(string)($error['code']??'');
  $diag['error_subcode']=(string)($error['error_subcode']??'');
  $diag['fbtrace_id']=(string)($error['fbtrace_id']??'');
  update_option('bsoerp_whatsapp_token_test',$diag,false);return false;
 }

 function whatsapp_send_test_message(){
  $o=get_option('bsoerp_whatsapp_meta',[]);if(!is_array($o))$o=[];
  $mobile=trim((string)($o['test_mobile']??''));
  if($mobile===''){$this->whatsapp_log_result('test','',false,'Test Mobile Number is blank.');return false;}
  return $this->whatsapp_send_template('task_add',$mobile,['assignee_name'=>'Test User','task_name'=>'WhatsApp API Test','description'=>'This is a test task description.','due_date'=>wp_date('d/m/Y',null,new DateTimeZone('Asia/Kolkata')),'time'=>wp_date('h:i A',null,new DateTimeZone('Asia/Kolkata')),'owner_name'=>'BizSkill ERP']);
 }

 function whatsapp_send_record_event($event_key,$record,$extra=[]){
  if(!$record)return false;$m=json_decode((string)($record->meta??''),true);if(!is_array($m))$m=[];
  $recipient_id=0;$vars=[];$mobile='';
  if($event_key==='task_add'){
   $recipient_id=(int)$record->assigned_to;$c=$this->whatsapp_user_contact($recipient_id);$mobile=$c['mobile'];
   $owner=$this->whatsapp_user_contact((int)$record->task_owner);
   $time=trim((string)($m['task_time']??''));$time=$time?date_i18n('h:i A',strtotime($time)):'';
   $vars=['assignee_name'=>$c['name'],'task_name'=>$record->title,'description'=>$record->notes,'due_date'=>$record->due_date?date_i18n('d/m/Y',strtotime($record->due_date)):'','time'=>$time,'owner_name'=>$owner['name']];
  }elseif($event_key==='task_update'){
   $recipient_id=(int)$record->task_owner;$c=$this->whatsapp_user_contact($recipient_id);$mobile=$c['mobile'];
   $updated_by=$this->whatsapp_user_contact((int)($extra['updated_by_user']??0));
   if($updated_by['name']==='-'){$wp=wp_get_current_user();$updated_by['name']=$wp&&$wp->exists()?$wp->display_name:'-';}
   $vars=['owner_name'=>$c['name'],'task_name'=>$record->title,'updated_by'=>$updated_by['name'],'task_status'=>$extra['status']??$record->status,'update_remarks'=>$extra['remarks']??'','update_date'=>$extra['date']??wp_date('d/m/Y h:i A',null,new DateTimeZone('Asia/Kolkata'))];
  }elseif($event_key==='lead_add'){
   $recipient_id=(int)$record->assigned_to;$c=$this->whatsapp_user_contact($recipient_id);$mobile=$c['mobile'];
   $owner=$this->whatsapp_user_contact((int)$record->lead_owner);
   $vars=['description'=>$record->title,'customer_name'=>$this->master_name_by_id((int)$record->customer_id),'contact_person'=>$m['contact_person']??'','mobile'=>$m['mobile']??'','assigned_by'=>$owner['name'],'remarks'=>$record->notes];
  }elseif($event_key==='lead_update'){
   $recipient_id=(int)$record->lead_owner;$c=$this->whatsapp_user_contact($recipient_id);$mobile=$c['mobile'];
   $updated_by=$this->whatsapp_user_contact((int)($extra['updated_by_user']??0));
   if($updated_by['name']==='-'){$wp=wp_get_current_user();$updated_by['name']=$wp&&$wp->exists()?$wp->display_name:'-';}
   $vars=['description'=>$record->title,'customer_name'=>$this->master_name_by_id((int)$record->customer_id),'status'=>$extra['status']??$record->status,'updated_by'=>$updated_by['name'],'remarks'=>$extra['remarks']??''];
  }elseif($event_key==='recce_add'){
   $recipient_id=(int)$record->assigned_to;$c=$this->whatsapp_user_contact($recipient_id);$mobile=$c['mobile'];
   $vars=['assigned_to_name'=>$c['name'],'customer_name'=>$this->master_name_by_id((int)$record->customer_id),'recce_no'=>$record->reference_no,'recce_date'=>$record->due_date?date_i18n('d/m/Y',strtotime($record->due_date)):'','no_of_recce'=>$m['no_of_recce']??'','remarks'=>$record->notes];
  }elseif($event_key==='design_add'){
   $recipient_id=(int)$record->assigned_to;$c=$this->whatsapp_user_contact($recipient_id);$mobile=$c['mobile'];
   $vars=['assigned_to_name'=>$c['name'],'customer_name'=>$this->master_name_by_id((int)$record->customer_id),'reference_no'=>$record->reference_no,'target_date'=>$record->due_date?date_i18n('d/m/Y',strtotime($record->due_date)):'','no_of_design'=>$m['design_assigned']??'','remarks'=>$record->notes];
  }else return false;
  return $this->whatsapp_send_template($event_key,$mobile,$vars);
 }

