 function module($v){
  $v=sanitize_key($v);$base=preg_replace('/^add-/','',$v);
  // Delivery workflow views are displayed under their own Delivery menu group,
  // but they remain part of the Orders workflow/data model.
  if(in_array($v,['add-delivery','delivered-orders','delivery-items'],true))return'orders';
  // Master routes must be resolved before operational keywords. Names such as
  // user-designations and work-order-types contain words that
  // also belong to operational modules and must never be classified by a
  // substring match.
  $master_views=['customers','customer-categories','industries','items','item-categories','work-order-types','job-types','users','user-roles','user-designations','user-document-types','machines','machine-types','departments','job-items','suppliers','vendors','transporters-courier','vehicles','lead-sources','lead-categories','customer','customer-category','industry','item','item-category','job-type','work-order-type','user','user-role','user-designation','user-document-type','machine','machine-type','department','job-item','supplier','vendor','transporter-courier','vehicle','lead-source','lead-category','uom'];
  if(in_array($base,$master_views,true))return'master';
  foreach($this->menu() as$section=>$spec){
   if($v===$section||isset($spec[1][$v])){
    return in_array($section,['tasks','timesheet','leads','recce','designs','quotations','orders','installation','production','deliveries','purchase-orders','grn'],true)?$section:'master';
   }
  }
  return'master';
 }
