 function repair_master_visibility(){global$wpdb;$rows=$wpdb->get_results("SELECT id,module,record_type,status FROM {$this->t('records')}");foreach($rows as$r){$canonical=$this->master_record_type($r->record_type);$module_alias=$this->master_record_type($r->module);$is_master=$this->is_master_record_type($canonical)||$this->is_master_record_type($module_alias);if(!$is_master)continue;if(!$this->is_master_record_type($canonical)&&$this->is_master_record_type($module_alias))$canonical=$module_alias;$update=[];if($r->module!=='master')$update['module']='master';if($r->record_type!==$canonical)$update['record_type']=$canonical;if(trim((string)$r->status)==='')$update['status']='Active';if($update)$wpdb->update($this->t('records'),$update,['id'=>(int)$r->id]);}}
