 function task_update_form($task_id){global$wpdb;$this->ensure_task_schema();$task=$task_id?$wpdb->get_row($wpdb->prepare("SELECT id,title FROM {$this->t('records')} WHERE id=%d AND module='tasks'",$task_id)):null;if(!$task){echo'<div class="notice">Task not found.</div>';return;}$return_view=sanitize_key($_GET['return_view']??'tasks-in-progress');if(!in_array($return_view,['tasks-in-progress','tasks-master'],true))$return_view='tasks-in-progress';$ist_tz=new DateTimeZone('Asia/Kolkata');$update_date=wp_date('Y-m-d',null,$ist_tz);$update_time=wp_date('H:i',null,$ist_tz);echo'<div class="panel form-panel"><form class="erp-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="bsoerp_save_task_update"><input type="hidden" name="task_id" value="'.(int)$task->id.'"><input type="hidden" name="return_view" value="'.esc_attr($return_view).'">';wp_nonce_field(self::NONCE,'nonce');echo'<div class="form-grid"><label><span>Task</span><input value="'.esc_attr($task->title).'" readonly></label><label><span>Status</span><input type="text" value="Complete" readonly class="erp-readonly"><input type="hidden" name="status" value="Completed"></label><label><span>Update Date</span><input type="date" value="'.esc_attr($update_date).'" readonly class="erp-readonly"><input type="hidden" name="update_date" value="'.esc_attr($update_date).'"></label><label><span>Update Time</span><input type="time" value="'.esc_attr($update_time).'" readonly class="erp-readonly"><input type="hidden" name="update_time" value="'.esc_attr($update_time).'"></label><label class="wide"><span>Task Remarks *</span><textarea name="update_text" rows="5" required placeholder="Write the latest progress or note"></textarea></label></div><div class="form-actions"><button class="btn primary" type="submit">Save Update</button><a class="btn mobile-excel" href="'.esc_url($this->url($return_view)).'">Cancel</a></div></form></div>';}
 function task_update_log(){
  global$wpdb;$this->ensure_task_schema();$task_id=absint($_GET['task_id']??0);
  if(isset($_GET['add_update'])){$tasks=$wpdb->get_results("SELECT id,title FROM {$this->t('records')} WHERE module='tasks' AND status NOT IN ('Completed','Canceled') ORDER BY updated_at DESC");echo'<div class="panel form-panel"><form class="erp-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field(self::NONCE,'nonce');echo'<input type="hidden" name="action" value="bsoerp_save_task_update"><div class="form-grid"><label><span>Task *</span><select class="erp-searchable" data-alpha="1" name="task_id" required><option value="0">Select Task</option>';foreach($tasks as$task)echo'<option value="'.$task->id.'" '.selected($task_id,$task->id,false).'>'.esc_html($task->title).'</option>';echo'</select></label><label class="wide"><span>Task Update *</span><textarea name="update_text" rows="5" required placeholder="Write the latest progress or note"></textarea></label></div><div class="form-actions"><button class="btn primary" type="submit">Save Update</button><a class="btn mobile-excel" href="'.esc_url($this->url('task-update-log')).'">Cancel</a></div></form></div>';return;}
  $search=sanitize_text_field(wp_unslash($_GET['s']??''));$task_owner=absint($_GET['task_owner']??0);$assigned_to=absint($_GET['assigned_to']??0);
  $status=sanitize_text_field(wp_unslash($_GET['status']??''));$updated_by=absint($_GET['updated_by']??0);$date_from=sanitize_text_field(wp_unslash($_GET['date_from']??''));$date_to=sanitize_text_field(wp_unslash($_GET['date_to']??''));
  $where=["r.module='tasks'"];$args=[];
  if(!current_user_can('bsoerp_manage')){$ids=$this->current_task_user_ids();$ph=implode(',',array_fill(0,count($ids),'%d'));$where[]="(r.task_owner IN ($ph) OR r.assigned_to IN ($ph))";$args=array_merge($args,$ids,$ids);}
  if($search){$like='%'.$wpdb->esc_like($search).'%';$where[]='(r.title LIKE %s OR u.update_text LIKE %s OR w.display_name LIKE %s)';$args=array_merge($args,[$like,$like,$like]);}
  if($customer){$where[]='r.customer_id=%d';$args[]=$customer;}if($task_owner){$where[]='r.task_owner=%d';$args[]=$task_owner;}if($assigned_to){$where[]='r.assigned_to=%d';$args[]=$assigned_to;}
  if(in_array($status,['In Progress','Completed','Canceled'],true)){$where[]='u.status=%s';$args[]=$status;}if($updated_by){$where[]='u.created_by=%d';$args[]=$updated_by;}
  if($date_from&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$date_from)){$where[]='DATE(u.created_at)>=%s';$args[]=$date_from;}if($date_to&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$date_to)){$where[]='DATE(u.created_at)<=%s';$args[]=$date_to;}
  $sql="SELECT u.*,r.title task_title,r.customer_id,r.task_owner,r.assigned_to,COALESCE(w.display_name,'Unknown user') user_name FROM {$this->t('task_updates')} u JOIN {$this->t('records')} r ON r.id=u.task_id LEFT JOIN {$wpdb->users} w ON w.ID=u.created_by WHERE ".implode(' AND ',$where)." ORDER BY u.created_at DESC,u.id DESC LIMIT 500";
  $rows=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql);
  $filter_args=array_filter(['s'=>$search,'customer'=>$customer,'task_owner'=>$task_owner,'assigned_to'=>$assigned_to,'status'=>$status,'updated_by'=>$updated_by,'date_from'=>$date_from,'date_to'=>$date_to],function($x){return$x!==''&&$x!==0;});
  $export=wp_nonce_url(add_query_arg(array_merge(['action'=>'bsoerp_export','view'=>'task-update-log'],$filter_args),admin_url('admin-post.php')),'bsoerp_export');$pdf=wp_nonce_url(add_query_arg(array_merge(['action'=>'bsoerp_task_pdf','view'=>'task-update-log'],$filter_args),admin_url('admin-post.php')),'bsoerp_task_pdf');
  echo'<div class="panel listing-panel"><div class="panel-head"><div><h2>Task Update Log</h2></div><div class="head-actions"><a class="btn mobile-excel" href="'.esc_url($export).'">⇩ Excel</a><a class="btn task-pdf" target="_blank" href="'.esc_url($pdf).'">⇩ PDF</a></div></div>';
  echo'<form class="toolbar master-toolbar task-update-server-toolbar" method="get"><input type="search" name="s" value="'.esc_attr($search).'" placeholder="Search" data-auto-search="1">';
  echo'<input type="date" name="date_from" value="'.esc_attr($date_from).'" title="Date From" aria-label="Date From" onchange="this.form.submit()"><input type="date" name="date_to" value="'.esc_attr($date_to).'" title="Date To" aria-label="Date To" onchange="this.form.submit()">';
  echo'<select name="task_owner" onchange="this.form.submit()"><option value="0">All Owners</option>';foreach($this->master_options('users')as$o)echo'<option value="'.$o->id.'" '.selected($task_owner,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select>';
  echo'<select name="assigned_to" onchange="this.form.submit()"><option value="0">All Assignees</option>';foreach($this->master_options('users')as$o)echo'<option value="'.$o->id.'" '.selected($assigned_to,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select>';
  echo'<select name="status" onchange="this.form.submit()"><option value="">All Status</option><option '.selected($status,'In Progress',false).'>In Progress</option><option '.selected($status,'Completed',false).'>Completed</option><option '.selected($status,'Canceled',false).'>Canceled</option></select>';
  echo'<select name="updated_by" onchange="this.form.submit()"><option value="0">All Updated By</option>';foreach(get_users(['orderby'=>'display_name'])as$u)echo'<option value="'.$u->ID.'" '.selected($updated_by,$u->ID,false).'>'.esc_html($u->display_name).'</option>';echo'</select><a class="btn filter-clear" href="'.esc_url($this->url('task-update-log')).'">Clear</a></form>';
  if(!$rows)echo'<div class="empty"><strong>No task updates found</strong><span>No records match the current filters.</span></div>';else{echo'<div class="table-wrap"><table class="data"><thead><tr><th>Task</th><th>Customer</th><th>Assigned By</th><th>Assigned To</th><th>Update</th><th>Status</th><th>Updated By</th><th>Date & Time</th></tr></thead><tbody>';foreach($rows as$row)echo'<tr><td><strong>'.esc_html($row->task_title).'</strong></td><td>'.esc_html($this->master_name_by_id($row->customer_id)?:'—').'</td><td>'.esc_html($this->task_user_display_name($row->task_owner)?:'—').'</td><td>'.esc_html($this->task_user_display_name($row->assigned_to)?:'—').'</td><td>'.nl2br(esc_html($row->update_text)).'</td><td><span class="status '.sanitize_html_class(strtolower(str_replace(' ','-',$row->status))).'">'.esc_html($row->status).'</span></td><td>'.esc_html($row->user_name).'</td><td data-date="'.esc_attr($this->format_utc_to_ist($row->created_at,'Y-m-d')).'">'.esc_html($this->format_utc_to_ist($row->created_at,'d M Y, h:i A')).'</td></tr>';echo'</tbody></table></div>';}echo'</div>';
 }
