 function render_field($k,$f,$v){[$label,$type,$req]=$f;$required=$req?' required':'';$wide=$type==='textarea'?' wide':'';$label_class=$type==='checkbox'?' checkbox-field':'';if($type==='installation-user')$label_class.=' installation-assigned-field';if($type==='installation-vendor')$label_class.=' installation-vendor-field';$display_label=$label;$display_required=$req;if($this->current_type==='user'&&$k==='password'&&$this->current_record_id){$display_label='Change Password (Optional)';$display_required=0;}echo'<label class="'.$wide.$label_class.'"><span>'.esc_html($display_label).($display_required?' *':'').'</span>';if($type==='readonlyuser'){echo'<input type="text" value="'.esc_attr($this->user_display_name(absint($v))?:'Current User').'" readonly class="erp-readonly">';}elseif($type==='readonly-number'){echo'<input type="number" step="0.01" name="'.esc_attr($k).'" value="'.esc_attr($v!==''&&((float)$v)!=0?$v:'').'" readonly class="erp-readonly">';}elseif($type==='checkbox'){echo'<span class="checkbox-inline"><input type="checkbox" name="'.esc_attr($k).'" value="1" '.checked((string)$v,'1',false).'><em>Yes</em></span>';}elseif($type==='document-upload'){ $aid=absint($v);echo'<div class="erp-document-upload">';if($aid){$url=wp_get_attachment_url($aid);$name=get_the_title($aid)?:basename((string)$url);if($url)echo'<a class="btn mobile-excel" target="_blank" rel="noopener" href="'.esc_url($url).'">View '.esc_html($name).'</a>'; }echo'<input type="file" name="'.esc_attr($k).'" accept="image/*,.pdf,.xls,.xlsx,.csv,.doc,.docx,.ppt,.pptx,.txt,.zip">';if($aid)echo'<small>Choose a file only to replace the existing document.</small>';echo'</div>'; }elseif($type==='image-upload'){ $aid=absint($v); echo'<div class="erp-image-upload">'; if($aid){$url=wp_get_attachment_image_url($aid,'medium');if($url)echo'<div class="erp-image-preview"><img src="'.esc_url($url).'" alt="'.esc_attr($label).'"></div>'; } echo'<input type="file" name="'.esc_attr($k).'" accept="image/*"><small>'.($k==='photo'?($aid?'Choose a new photo to replace the existing photo.':'Upload user photo.') : ($aid?'Choose a new image to update the signature.':'Upload signature image.')).'</small></div>'; }elseif($type==='multiuser'){
