  foreach($this->master_options('users')as$u)echo'<label class="erp-multiuser-option"><input type="checkbox" name="'.esc_attr($k).'[]" value="'.$u->id.'" '.checked(in_array((int)$u->id,$selected,true),true,false).'> <span>'.esc_html($u->title).'</span></label>';
  echo'</div></div>';
 }elseif($type==='grn-po'){
  global$wpdb;$records_table=$this->t('records');$line_table=$this->t('line_items');$selected_po=absint($v);$sql="SELECT po.id,po.reference_no,sup.title supplier_name FROM {$records_table} po LEFT JOIN {$records_table} sup ON sup.id=po.party_id WHERE po.module='purchase-orders' AND po.record_type='purchase-order' AND (po.status IS NULL OR po.status NOT IN ('Completed','Canceled','Rejected')) AND (po.id=".$selected_po." OR EXISTS (SELECT 1 FROM {$line_table} src WHERE src.record_id=po.id AND src.qty > COALESCE((SELECT SUM(grnli.received_qty) FROM {$line_table} grnli JOIN {$records_table} grnr ON grnr.id=grnli.record_id WHERE grnli.source_line_id=src.id AND grnr.module='grn' AND grnr.status<>'Canceled'),0)+0.0001)) ORDER BY po.id DESC LIMIT 500";$pos=$wpdb->get_results($sql);echo'<select class="erp-searchable" name="'.esc_attr($k).'"'.($req?' data-required="1"':'').'><option value="0">Select Purchase Order</option>';foreach($pos as$po){$text=trim((string)$po->reference_no).($po->supplier_name?' - '.$po->supplier_name:'');echo'<option value="'.$po->id.'" '.selected($v,$po->id,false).'>'.esc_html($text).'</option>';}echo'</select>';
