  $due_from=sanitize_text_field(wp_unslash($_GET['due_from']??''));$due_to=sanitize_text_field(wp_unslash($_GET['due_to']??''));$daily_created=!empty($_GET['daily_created']);if($daily_created){$today=current_time('Y-m-d');$where[]='DATE(created_at)=%s';$args[]=$today;}
  if($search){$where[]='title LIKE %s';$args[]='%'.$wpdb->esc_like($search).'%';}
  if($task_owner){$where[]='task_owner=%d';$args[]=$task_owner;}
  if($assigned_to){$where[]='assigned_to=%d';$args[]=$assigned_to;}
  if($due_from&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$due_from)){$where[]='due_date >= %s';$args[]=$due_from;}
  if($due_to&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$due_to)){$where[]='due_date <= %s';$args[]=$due_to;}
  $page=max(1,absint($_GET['pg']??1));$per=$this->pagination_size();$offset=($page-1)*$per;
  $base="FROM {$this->t('records')} WHERE ".implode(' AND ',$where);$countSql="SELECT COUNT(*) $base";$rowSql="SELECT * $base ORDER BY updated_at DESC LIMIT $per OFFSET $offset";
  $total=(int)$wpdb->get_var($args?$wpdb->prepare($countSql,$args):$countSql);$rows=$wpdb->get_results($args?$wpdb->prepare($rowSql,$args):$rowSql);
  $filter_args=array_filter(['s'=>$search,'task_owner'=>$task_owner,'assigned_to'=>$assigned_to,'due_from'=>$due_from,'due_to'=>$due_to],function($x){return$x!==''&&$x!==0;});
  $export=wp_nonce_url(add_query_arg(array_merge(['action'=>'bsoerp_export','view'=>$v],$filter_args),admin_url('admin-post.php')),'bsoerp_export');
  $pdf=wp_nonce_url(add_query_arg(array_merge(['action'=>'bsoerp_task_pdf','view'=>$v],$filter_args),admin_url('admin-post.php')),'bsoerp_task_pdf');
  echo'<div class="panel listing-panel"><div class="panel-head"><div><h2>'.esc_html($this->flat()[$v]).'</h2></div><div class="head-actions"><a class="btn mobile-excel" href="'.esc_url($export).'">⇩ Excel</a><a class="btn task-pdf" target="_blank" href="'.esc_url($pdf).'">⇩ PDF</a></div></div>';
  echo'<form class="toolbar master-toolbar task-server-toolbar" data-task-filters="1" method="get">';
  echo'<input type="search" name="s" value="'.esc_attr($search).'" placeholder="Search tasks" data-auto-search="1">';
  echo'<input type="date" name="due_from" value="'.esc_attr($due_from).'" title="Due Date From" aria-label="Due Date From" onchange="this.form.submit()">';
  echo'<input type="date" name="due_to" value="'.esc_attr($due_to).'" title="Due Date To" aria-label="Due Date To" onchange="this.form.submit()">';
  echo'<select name="task_owner" onchange="this.form.submit()"><option value="0">All Owners</option>';foreach($this->master_options('users')as$o)echo'<option value="'.$o->id.'" '.selected($task_owner,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select>';
  echo'<select name="assigned_to" onchange="this.form.submit()"><option value="0">All Assignees</option>';foreach($this->master_options('users')as$o)echo'<option value="'.$o->id.'" '.selected($assigned_to,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select>';
  echo'<a class="btn task-filter-clear filter-clear" href="'.esc_url($this->url($v)).'">Clear</a></form>';
  $this->table($rows,false,'',$v);$this->pagination_controls($total,$page,$per,add_query_arg($filter_args,$this->url($v)));echo'</div>';
 }

 function lead_meta_value($r,$key,$default=''){if(!$r)return$default;$m=json_decode($r->meta?:'{}',true);return is_array($m)&&array_key_exists($key,$m)?$m[$key]:$default;}
 function lead_filter_state($v){
  return [
   's'=>sanitize_text_field(wp_unslash($_GET['s']??'')),
   'customer'=>absint($_GET['customer']??0),
   'lead_source'=>absint($_GET['lead_source']??0),
   'lead_owner'=>absint($_GET['lead_owner']??0),
   'assigned_to'=>absint($_GET['assigned_to']??0),
   'status'=>sanitize_text_field(wp_unslash($_GET['status']??'')),
   'date_from'=>sanitize_text_field(wp_unslash($_GET['date_from']??'')),
   'date_to'=>sanitize_text_field(wp_unslash($_GET['date_to']??'')),
  ];
 }
 function lead_query_parts($v,$f){
  global$wpdb;$where=["module='leads'"];$args=[];if(!empty($_GET['daily_created'])){$where[]='DATE(created_at)=%s';$args[]=current_time('Y-m-d');}
  $fixed=['leads-in-progress'=>'In Progress','completed-leads'=>'Completed','canceled-leads'=>'Canceled'][$v]??'';
  if($fixed){$where[]='status=%s';$args[]=$fixed;}elseif(in_array($f['status'],['In Progress','Completed','Canceled'],true)){$where[]='status=%s';$args[]=$f['status'];}
  if($f['s']){$like='%'.$wpdb->esc_like($f['s']).'%';$where[]='(title LIKE %s OR notes LIKE %s)';array_push($args,$like,$like);}
  if($f['customer']){$where[]='customer_id=%d';$args[]=$f['customer'];}
  if($f['lead_source']){$where[]='lead_source_id=%d';$args[]=$f['lead_source'];}
  if($f['lead_owner']){$where[]='lead_owner=%d';$args[]=$f['lead_owner'];}
  if($f['assigned_to']){$where[]='assigned_to=%d';$args[]=$f['assigned_to'];}
  $date_field=in_array($v,['completed-leads','canceled-leads'],true)?'DATE(updated_at)':'due_date';
  if($f['date_from']&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$f['date_from'])){$where[]="$date_field >= %s";$args[]=$f['date_from'];}
  if($f['date_to']&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$f['date_to'])){$where[]="$date_field <= %s";$args[]=$f['date_to'];}
  return[$where,$args];
 }
 function lead_filter_toolbar($v,$f){
