  echo'<input type="search" name="s" value="'.esc_attr($f['s']).'" placeholder="Search leads" data-auto-search="1">';
  echo'<select name="customer" onchange="this.form.submit()"><option value="0">All Customers</option>';foreach($this->master_options('customers')as$o)echo'<option value="'.$o->id.'" '.selected($f['customer'],$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select>';
  echo'<select name="lead_source" onchange="this.form.submit()"><option value="0">All Sources</option>';foreach($this->master_options('lead-sources')as$o)echo'<option value="'.$o->id.'" '.selected($f['lead_source'],$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select>';
  echo'<select name="lead_owner" onchange="this.form.submit()"><option value="0">All Assigned By</option>';foreach($this->master_options('users')as$o)echo'<option value="'.$o->id.'" '.selected($f['lead_owner'],$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select>';
  if($v!=='pending-assignee'){echo'<select name="assigned_to" onchange="this.form.submit()"><option value="0">All Assignees</option>';foreach($this->master_options('users')as$o)echo'<option value="'.$o->id.'" '.selected($f['assigned_to'],$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select>';}
  $from_label=in_array($v,['completed-leads','canceled-leads'],true)?'Date From':'Follow-up From';$to_label=in_array($v,['completed-leads','canceled-leads'],true)?'Date To':'Follow-up To';
  echo'<label><span>'.esc_html($from_label).'</span><input type="date" name="date_from" value="'.esc_attr($f['date_from']).'" onchange="this.form.submit()"></label>';
  echo'<label><span>'.esc_html($to_label).'</span><input type="date" name="date_to" value="'.esc_attr($f['date_to']).'" onchange="this.form.submit()"></label>';
  if(in_array($v,['leads-master','pending-assignee','pending-estimate'],true)){$status_choices=$v==='leads-master'?['In Progress','Completed','Canceled']:['In Progress','Completed'];echo'<select name="status" onchange="this.form.submit()"><option value="">All Status</option>';foreach($status_choices as$st)echo'<option value="'.esc_attr($st).'" '.selected($f['status'],$st,false).'>'.esc_html($st).'</option>';echo'</select>';}
  echo'<a class="btn filter-clear" href="'.esc_url($this->url($v)).'">Clear</a></form>';
 }
 function lead_status_display($status){return $status==='Completed'?'Success':($status==='Canceled'?'Enquiry Lost':$status);}
