  else $where[]="COALESCE(CAST(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(IF(JSON_VALID(meta),meta,'{}'),'$.expected_value')),'') AS DECIMAL(18,2)),0)<=0";
  $page=max(1,absint($_GET['pg']??1));$per=$this->pagination_size();$off=($page-1)*$per;$base="FROM {$this->t('records')} WHERE ".implode(' AND ',$where);
  $total=(int)$wpdb->get_var($args?$wpdb->prepare("SELECT COUNT(*) $base",$args):"SELECT COUNT(*) $base");
  $rows=$wpdb->get_results($args?$wpdb->prepare("SELECT * $base ORDER BY updated_at DESC LIMIT $per OFFSET $off",$args):"SELECT * $base ORDER BY updated_at DESC LIMIT $per OFFSET $off");
  $fa=array_filter($f,function($x){return$x!==''&&$x!==0;});
