   echo'<div class="table-wrap"><table class="data lead-table"><thead><tr><th>Sl.</th><th>Description</th><th>Customer</th><th>Source</th><th>Assigned By</th><th>Assigned To</th><th>Next Follow-up</th><th>Status</th><th>Action</th></tr></thead><tbody>';
   foreach($rows as$i=>$r){echo'<tr><td>'.(($page-1)*$per+$i+1).'</td><td><strong>'.esc_html($r->title).'</strong></td><td>'.esc_html($this->master_name_by_id($r->customer_id)).'</td><td>'.esc_html($this->master_name_by_id($r->lead_source_id)).'</td><td>'.esc_html($this->master_name_by_id((int)($this->lead_meta_value($r,'lead_category_id',0)))).'</td><td>'.esc_html($this->task_user_display_name($r->lead_owner)?:'—').'</td><td>'.esc_html($this->task_user_display_name($r->assigned_to)?:'—').'</td><td>'.($r->due_date?esc_html(date_i18n('d/m/Y',strtotime($r->due_date))):'—').'</td><td><span class="status '.sanitize_html_class(strtolower(str_replace(' ','-',$r->status))).'">'.esc_html($r->status==='Pending Approval'?'Pending Client Approval':$r->status).'</span></td><td class="actions">';
    if($v==='pending-assignee')echo'<button type="button" class="btn primary compact-action update-icon-action lead-queue-open" title="Update Assigned To" aria-label="Update Assigned To" data-queue="assignee" data-lead-id="'.(int)$r->id.'" data-lead-title="'.esc_attr($r->title).'">✓</button>';
    else echo'<button type="button" class="btn primary compact-action update-icon-action lead-queue-open" title="Update Estimate" aria-label="Update Estimate" data-queue="estimate" data-lead-id="'.(int)$r->id.'" data-lead-title="'.esc_attr($r->title).'">✓</button>';
    echo'<a title="Edit" href="'.esc_url(add_query_arg('edit',$r->id,$this->url($v))).'">✎</a></td></tr>';
   }echo'</tbody></table></div>';
  }
  $this->pagination_controls($total,$page,$per,add_query_arg($fa,$this->url($v)));
  $nonce=wp_nonce_field(self::NONCE,'nonce',true,false);
  echo'<div class="lead-update-modal lead-queue-modal" id="lead-queue-modal" aria-hidden="true"><div class="lead-update-modal-backdrop" data-lead-queue-close></div><div class="lead-update-modal-card" role="dialog" aria-modal="true" aria-labelledby="lead-queue-modal-title"><button type="button" class="lead-update-modal-close" data-lead-queue-close aria-label="Close">×</button><div class="panel-head"><div><h2 id="lead-queue-modal-title">Update Enquiry</h2><small class="lead-queue-modal-lead"></small></div></div><form class="erp-form lead-queue-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'" novalidate>'.$nonce.'<input type="hidden" name="action" value="bsoerp_lead_queue_update"><input type="hidden" name="lead_id" value=""><input type="hidden" name="queue_type" value=""><input type="hidden" name="return_view" value="'.esc_attr($v).'"><div class="form-grid"><label class="lead-queue-assignee-field"><span>Assigned To *</span><select class="no-search-select lead-queue-user-select" name="assigned_to" data-required="1" required><option value="0">Select User</option>';
  foreach($this->master_options('users')as$u)echo'<option value="'.$u->id.'">'.esc_html($u->title).'</option>';
  echo'</select><small class="field-error" hidden></small></label><label class="lead-queue-estimate-field"><span>Estimate / Expected Value *</span><input type="number" name="expected_value" min="0.01" step="0.01"><small class="field-error" hidden></small></label></div><div class="form-actions"><button class="btn primary" type="submit">Save</button><button class="btn" type="button" data-lead-queue-close>Cancel</button></div></form></div></div>';
  echo'</div>';
 }
 function save_lead_queue_update(){
  if(!is_user_logged_in()||!current_user_can('bsoerp_access')||!wp_verify_nonce($_POST['nonce']??'',self::NONCE))wp_die('Invalid request');
  global$wpdb;$post=wp_unslash($_POST);$id=absint($post['lead_id']??0);$queue=sanitize_key($post['queue_type']??'');$return=in_array(($post['return_view']??''),['pending-assignee','pending-estimate'],true)?sanitize_key($post['return_view']):'pending-assignee';
  $r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='leads'",$id));if(!$r||$r->status==='Canceled')wp_die('Enquiry is not available for this update.');
  if($queue==='assignee'){$uid=absint($post['assigned_to']??0);if(!$uid||!$this->task_user_display_name($uid))wp_die('Assigned To is required.');$ok=$wpdb->update($this->t('records'),['assigned_to'=>$uid,'updated_at'=>current_time('mysql')],['id'=>$id]);if($ok===false)wp_die('Unable to update Assigned To.');$this->activity($id,'leads','Assigned To Updated',$this->task_user_display_name($uid));}
  elseif($queue==='estimate'){$value=(float)($post['expected_value']??0);if($value<=0)wp_die('Estimate / Expected Value is required.');$meta=json_decode($r->meta?:'{}',true);if(!is_array($meta))$meta=[];$meta['expected_value']=number_format($value,2,'.','');$ok=$wpdb->update($this->t('records'),['meta'=>wp_json_encode($meta),'updated_at'=>current_time('mysql')],['id'=>$id]);if($ok===false)wp_die('Unable to update Estimate.');$this->activity($id,'leads','Estimate Updated',(string)$value);}
  else wp_die('Invalid enquiry update type.');
  wp_safe_redirect(add_query_arg('notice','saved',$this->url($return)));exit;
 }
 function lead_update_form($lead_id){
  global$wpdb;$this->ensure_lead_schema();$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='leads'",$lead_id));if(!$r){echo'<div class="notice">Enquiry not found.</div>';return;}
  echo'<div class="lead-update-standalone-wrap"><div class="panel form-panel lead-update-standalone"><div class="panel-head"><div><h2>Update Enquiry</h2><small>'.esc_html($r->title).'</small></div></div>';
  echo'<form class="erp-form lead-update-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field(self::NONCE,'nonce');echo'<input type="hidden" name="action" value="bsoerp_save_lead_update"><input type="hidden" name="lead_id" value="'.$r->id.'"><div class="form-grid">';
  echo'<label><span>Status *</span><select name="status" class="lead-status-select no-search-select" required><option value="In Progress">In Progress</option><option value="Completed">Success</option><option value="Canceled">Enquiry Lost</option></select></label>';
  echo'<label class="lead-next-follow-up-field"><span>Next Follow-up *</span><input type="date" name="next_follow_up" value="'.esc_attr($r->due_date).'" min="'.esc_attr(current_time('Y-m-d')).'" required></label>';
  echo'<label><span>Updated By *</span><select name="updated_by_user" required><option value="0">Select User</option>';foreach($this->master_options('users')as$u)echo'<option value="'.$u->id.'">'.esc_html($u->title).'</option>';echo'</select></label>';
