 }
 function save_lead_update(){
  if(!is_user_logged_in()||!current_user_can('bsoerp_access')||!wp_verify_nonce($_POST['nonce']??'',self::NONCE))wp_die('Invalid request');
  global$wpdb;$this->ensure_lead_schema();$post=wp_unslash($_POST);$id=absint($post['lead_id']??0);$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='leads'",$id));if(!$r)wp_die('Enquiry not found.');
  $update=sanitize_textarea_field($post['update_text']??'');$status=sanitize_text_field($post['status']??'');
  if($update==='')wp_die('Remarks are required.');if(!in_array($status,['In Progress','Completed','Canceled'],true))wp_die('Status is required.');
  $updated_by_user=absint($post['updated_by_user']??0);if(!$updated_by_user||!$this->task_user_display_name($updated_by_user))wp_die('Updated By is required.');
  $due=sanitize_text_field($post['next_follow_up']??'');if($status==='In Progress'){if(!$due||!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$due))wp_die('Next Follow-up is required when Status is In Progress.');if($due<current_time('Y-m-d'))wp_die('Due Date cannot be earlier than today.');}else{$due='';}
  $owner=absint($r->lead_owner);$assigned=absint($r->assigned_to);$expected=max(0,(float)$this->lead_meta_value($r,'expected_value',0));
  $wpdb->query('START TRANSACTION');try{$ok=$wpdb->insert($this->t('lead_updates'),['lead_id'=>$id,'update_text'=>$update,'status'=>$status,'next_follow_up'=>$due?:null,'lead_owner'=>$owner,'assigned_to'=>$assigned,'expected_value'=>$expected,'cancel_reason'=>'','updated_by_user'=>$updated_by_user,'created_by'=>get_current_user_id(),'created_at'=>current_time('mysql')]);if(!$ok)throw new Exception($wpdb->last_error?:'Unable to save enquiry update.');$ok=$wpdb->update($this->t('records'),['status'=>$status,'due_date'=>$due?:null,'updated_at'=>current_time('mysql')],['id'=>$id]);if($ok===false)throw new Exception($wpdb->last_error?:'Unable to update enquiry.');$this->activity($id,'leads','Enquiry Update',$update);$wpdb->query('COMMIT');$r->status=$status;$r->due_date=$due;$this->whatsapp_send_record_event('lead_update',$r,['status'=>$this->lead_status_display($status),'remarks'=>$update,'next_follow_up'=>$due,'updated_by_user'=>$updated_by_user]);}catch(Throwable$e){$wpdb->query('ROLLBACK');wp_die('Save failed: '.esc_html($e->getMessage()));}
  $dest=$status==='In Progress'?'leads-in-progress':'leads-master';wp_safe_redirect(add_query_arg('notice','saved',$this->url($dest)));exit;
 }
 function lead_update_log(){
  global$wpdb;$this->ensure_lead_schema();$s=sanitize_text_field(wp_unslash($_GET['s']??''));$customer=absint($_GET['customer']??0);$source=absint($_GET['lead_source']??0);$owner=absint($_GET['lead_owner']??0);$assigned=absint($_GET['assigned_to']??0);$status=sanitize_text_field(wp_unslash($_GET['status']??''));$updated_by=absint($_GET['updated_by']??0);$from=sanitize_text_field($_GET['date_from']??'');$to=sanitize_text_field($_GET['date_to']??'');$lead_id=absint($_GET['lead_id']??0);
  $where=['1=1'];$args=[];if($lead_id){$where[]='u.lead_id=%d';$args[]=$lead_id;}if($s){$like='%'.$wpdb->esc_like($s).'%';$where[]='(r.title LIKE %s OR u.update_text LIKE %s)';array_push($args,$like,$like);}if($customer){$where[]='r.customer_id=%d';$args[]=$customer;}if($source){$where[]='r.lead_source_id=%d';$args[]=$source;}if($owner){$where[]='u.lead_owner=%d';$args[]=$owner;}if($assigned){$where[]='u.assigned_to=%d';$args[]=$assigned;}if(in_array($status,['In Progress','Completed','Canceled'],true)){$where[]='u.status=%s';$args[]=$status;}if($updated_by){$where[]='u.updated_by_user=%d';$args[]=$updated_by;}if($from){$where[]='DATE(u.created_at)>=%s';$args[]=$from;}if($to){$where[]='DATE(u.created_at)<=%s';$args[]=$to;}
  $sql="SELECT u.*,r.title,r.customer_id,r.lead_source_id FROM {$this->t('lead_updates')} u JOIN {$this->t('records')} r ON r.id=u.lead_id WHERE ".implode(' AND ',$where).' ORDER BY u.created_at DESC,u.id DESC';$rows=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql);
  $filter_args=array_filter(['s'=>$s,'customer'=>$customer,'lead_source'=>$source,'lead_owner'=>$owner,'assigned_to'=>$assigned,'status'=>$status,'updated_by'=>$updated_by,'date_from'=>$from,'date_to'=>$to,'lead_id'=>$lead_id],function($x){return$x!==''&&$x!==0;});
  $export=wp_nonce_url(add_query_arg(array_merge(['action'=>'bsoerp_export','view'=>'lead-update-log'],$filter_args),admin_url('admin-post.php')),'bsoerp_export');$pdf=wp_nonce_url(add_query_arg(array_merge(['action'=>'bsoerp_task_pdf','view'=>'lead-update-log'],$filter_args),admin_url('admin-post.php')),'bsoerp_task_pdf');
  echo'<div class="panel listing-panel"><div class="panel-head"><div><h2>Enquiry Update Log</h2></div><div class="head-actions"><a class="btn mobile-excel" href="'.esc_url($export).'">⇩ Excel</a><a class="btn task-pdf" target="_blank" href="'.esc_url($pdf).'">⇩ PDF</a></div></div><form class="toolbar master-toolbar lead-server-toolbar" method="get">';
  if($lead_id)echo'<input type="hidden" name="lead_id" value="'.$lead_id.'">';
  echo'<input type="search" name="s" value="'.esc_attr($s).'" placeholder="Search updates" data-auto-search="1"><select name="customer" onchange="this.form.submit()"><option value="0">All Customers</option>';foreach($this->master_options('customers')as$o)echo'<option value="'.$o->id.'" '.selected($customer,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select><select name="lead_source" onchange="this.form.submit()"><option value="0">All Sources</option>';foreach($this->master_options('lead-sources')as$o)echo'<option value="'.$o->id.'" '.selected($source,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select><select name="lead_owner" onchange="this.form.submit()"><option value="0">All Assigned By</option>';foreach($this->master_options('users')as$o)echo'<option value="'.$o->id.'" '.selected($owner,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select><select name="assigned_to" onchange="this.form.submit()"><option value="0">All Assignees</option>';foreach($this->master_options('users')as$o)echo'<option value="'.$o->id.'" '.selected($assigned,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select><select name="status" onchange="this.form.submit()"><option value="">All Status</option>';foreach(['In Progress','Completed','Canceled']as$st){$st_label=$this->lead_status_display($st);echo'<option value="'.esc_attr($st).'" '.selected($status,$st,false).'>'.esc_html($st_label).'</option>';};echo'</select><select name="updated_by" onchange="this.form.submit()"><option value="0">All Updated By</option>';foreach($this->master_options('users')as$u)echo'<option value="'.$u->id.'" '.selected($updated_by,$u->id,false).'>'.esc_html($u->title).'</option>';echo'</select><label><span>Date From</span><input type="date" name="date_from" value="'.esc_attr($from).'" onchange="this.form.submit()"></label><label><span>Date To</span><input type="date" name="date_to" value="'.esc_attr($to).'" onchange="this.form.submit()"></label><a class="btn filter-clear" href="'.esc_url($this->url('lead-update-log')).'">Clear</a></form>';
  if(!$rows)echo'<div class="empty"><strong>No updates found</strong><span>No enquiry updates match the current filters.</span></div>';else{echo'<div class="table-wrap"><table class="data"><thead><tr><th>Description</th><th>Customer</th><th>Source</th><th>Assigned By</th><th>Assigned To</th><th>Update</th><th>Status</th><th>Next Follow-up</th><th>Updated By</th><th>Date & Time</th></tr></thead><tbody>';foreach($rows as$r)echo'<tr><td><strong>'.esc_html($r->title).'</strong></td><td>'.esc_html($this->master_name_by_id($r->customer_id)).'</td><td>'.esc_html($this->master_name_by_id($r->lead_source_id)).'</td><td>'.esc_html($this->task_user_display_name($r->lead_owner)?:'—').'</td><td>'.esc_html($this->task_user_display_name($r->assigned_to)?:'—').'</td><td>'.nl2br(esc_html($r->update_text)).'</td><td><span class="status '.sanitize_html_class(strtolower(str_replace(' ','-',$r->status))).'">'.esc_html($this->lead_status_display($r->status)).'</span></td><td>'.($r->next_follow_up?esc_html(date_i18n('d/m/Y',strtotime($r->next_follow_up))):'—').'</td><td>'.esc_html($r->updated_by_user?$this->task_user_display_name($r->updated_by_user):$this->user_display_name($r->created_by)).'</td><td>'.esc_html($this->format_utc_to_ist($r->created_at,'d/m/Y h:i A')).'</td></tr>';echo'</tbody></table></div>';}echo'</div>';
 }

 function master_filter_config($type){$map=[
 'customer'=>[['category_id','Category','customer-categories']],
 'item'=>[['category_id','Category','item-categories']],
 'user'=>[['role_id','Role','user-roles'],['designation_id','Designation','user-designations'],['department_id','Department','departments']],
