 ];return$map[$type]??[];}
 function master_summary($type,$filtered=0,$is_filtered=false){global$wpdb;$aliases=$this->master_aliases($type);$ph=implode(',',array_fill(0,count($aliases),'%s'));$base="FROM {$this->t('records')} WHERE module='master' AND record_type IN ($ph)";$total=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) $base",$aliases));$active_args=array_merge($aliases,['Active']);$inactive_args=array_merge($aliases,['Inactive']);$active=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) $base AND status=%s",$active_args));$inactive=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) $base AND status=%s",$inactive_args));echo'<div class="cards master-summary"><div class="card"><span>Total</span><strong>'.$total.'</strong><small>All records</small></div><div class="card"><span>Active</span><strong>'.$active.'</strong><small>Currently active</small></div><div class="card"><span>Inactive</span><strong>'.$inactive.'</strong><small>Currently inactive</small></div>';if($is_filtered)echo'<div class="card"><span>Filtered</span><strong>'.absint($filtered).'</strong><small>Matching current filters</small></div>';echo'</div>';}
