  echo'<div class="ud-head"><div><h2 style="margin:0">User Details</h2></div><div class="ud-actions"><a class="btn" href="'.esc_url($back).'">← Back</a><a class="btn primary" href="'.esc_url($edit).'">✎ Edit User</a></div></div>';
  echo'<div class="ud-panel"><h3>User Information</h3><div class="ud-grid">';
  $info=[['User Name',$r->title],['Email',$m['email']??''],['Mobile',$m['mobile']??''],['User Role',$role],['Designation',$designation],['Department',$department],['Status','<span class="ud-status">'.esc_html($r->status?:'Active').'</span>','html'],['Signature',$attachment('signature','Signature'),'html']];
  foreach($info as$it){$html=($it[2]??'')==='html';echo'<div class="ud-item"><span class="ud-label">'.esc_html($it[0]).'</span><div class="ud-value">'.($html?$it[1]:esc_html($show($it[1]))).'</div></div>';}
