  echo'<div class="ud-panel"><h3>Documents & Personal Details</h3><div class="ud-grid">';
  $docs=[['PAN No.',$m['pan_no']??''],['PAN Copy',$attachment('pan_copy','PAN Copy'),'html'],['Driving Licence No.',$m['driving_licence_no']??''],['Driving Licence',$attachment('driving_licence','Driving Licence'),'html'],['Aadhaar No.',$m['aadhaar_no']??''],['Aadhaar Copy',$attachment('aadhaar_copy','Aadhaar Copy'),'html'],['Parent/Guardian Name',$m['parent_guardian_name']??''],['Parent/Guardian Mobile No.',$m['parent_guardian_mobile']??''],['Address',$m['address']??'','wide'],['Bank Name',$m['bank_name']??''],['IFSC',$m['ifsc']??''],['A/C No.',$m['account_no']??''],['UPI ID',$m['upi_id']??''],['G.Pay No.',$m['gpay_no']??''],['Photo',$attachment('photo','Photo'),'html']];
  foreach($docs as$it){$flag=$it[2]??'';$html=$flag==='html';$wide=$flag==='wide';echo'<div class="ud-item'.($wide?' wide':'').'"><span class="ud-label">'.esc_html($it[0]).'</span><div class="ud-value">'.($html?$it[1]:esc_html($show($it[1]))).'</div></div>';}
  echo'</div></div>';
 }
 function master_cell($r,$key){$m=$this->master_meta($r);if($key==='name')return$r->title;if($key==='status')return$r->status;if($key==='signature'){ $aid=absint($m['signature']??0); return $aid?(wp_get_attachment_image_url($aid,'thumbnail')?:'—'):'—'; }if(strpos($key,'rel:')===0){$mk=substr($key,4);return$this->master_name_by_id(absint($m[$mk]??0));}$v=$m[$key]??'';return($v===''||$v===null)?'—':$v;}
 function pagination_size(){
  $settings=get_option('bsoerp_settings',['records'=>20]);
  $default=max(10,min(100,absint($settings['records']??20)));
  $requested=absint($_GET['per_page']??$default);
  return in_array($requested,[10,25,50,100],true)?$requested:$default;
 }
 function pagination_controls($total,$page,$per,$base_url=''){
  $total=max(0,(int)$total);$page=max(1,(int)$page);$per=max(1,(int)$per);$pages=max(1,(int)ceil($total/$per));
  if(!$base_url)$base_url=remove_query_arg(['pg','per_page']);
  if(isset($_GET['s']))$base_url=remove_query_arg(['s','erp_search'],$base_url);
  $from=$total?(($page-1)*$per+1):0;$to=min($total,$page*$per);
  echo'<div class="pagination-bar"><div class="pagination-info">Showing <strong>'.$from.'–'.$to.'</strong> of <strong>'.$total.'</strong></div>';
  echo'<form class="page-size" method="get">';
  foreach($_GET as$k=>$v){if(in_array($k,['pg','per_page'],true)||is_array($v))continue;$safe_key=$k==='s'?'erp_search':$k;echo'<input type="hidden" name="'.esc_attr($safe_key).'" value="'.esc_attr(wp_unslash($v)).'">';}
  echo'<label>Rows <select name="per_page" onchange="this.form.submit()">';foreach([10,25,50,100]as$n)echo'<option value="'.$n.'" '.selected($per,$n,false).'>'.$n.'</option>';echo'</select></label></form>';
  if($pages>1){echo'<nav class="pagination" aria-label="Pagination">';
   $q=$_GET;unset($q['pg']);if(isset($q['s'])){$q['erp_search']=$q['s'];unset($q['s']);}$q['per_page']=$per;
   if($page>1){$q['pg']=$page-1;echo'<a class="page-nav" href="'.esc_url(add_query_arg($q,$base_url)).'">‹</a>';}
   $start=max(1,$page-2);$end=min($pages,$page+2);if($start>1){$q['pg']=1;echo'<a href="'.esc_url(add_query_arg($q,$base_url)).'">1</a>';if($start>2)echo'<span>…</span>';}
   for($i=$start;$i<=$end;$i++){$q['pg']=$i;echo'<a class="'.($i===$page?'active':'').'" href="'.esc_url(add_query_arg($q,$base_url)).'">'.$i.'</a>';}
   if($end<$pages){if($end<$pages-1)echo'<span>…</span>';$q['pg']=$pages;echo'<a href="'.esc_url(add_query_arg($q,$base_url)).'">'.$pages.'</a>';}
   if($page<$pages){$q['pg']=$page+1;echo'<a class="page-nav" href="'.esc_url(add_query_arg($q,$base_url)).'">›</a>';}
   echo'</nav>';}
  echo'</div>';
 }
 function design_meta_value($r,$key,$default=''){if(!$r)return$default;$m=json_decode((string)$r->meta,true);return is_array($m)&&array_key_exists($key,$m)?$m[$key]:$default;}
 function design_totals($design_id,$assigned=0){global$wpdb;$this->ensure_design_schema();$rows=$wpdb->get_results($wpdb->prepare("SELECT completed_qty,canceled_qty,pending_qty,approved_qty FROM {$this->t('design_updates')} WHERE design_id=%d ORDER BY id ASC",$design_id));$completed=0;$approved=0;$cancel=0;$pending=(int)$assigned;foreach($rows as$u){$completed+=(int)$u->completed_qty;$approved+=(int)$u->approved_qty;$cancel+=(int)$u->canceled_qty;$pending=max(0,(int)$assigned-$completed-$cancel);}return['assigned'=>(int)$assigned,'completed'=>$completed,'approved'=>$approved,'cancel'=>$cancel,'pending'=>$pending];}
 function design_update_modal(){echo'<div class="lead-update-modal design-update-modal" id="design-update-modal" aria-hidden="true"><div class="lead-update-modal-backdrop" data-design-update-close></div><div class="lead-update-modal-card" role="dialog" aria-modal="true" aria-labelledby="design-update-modal-title"><button type="button" class="lead-update-modal-close" data-design-update-close aria-label="Close">×</button><div class="panel-head"><div><h2 id="design-update-modal-title">Update Design</h2><small class="design-update-modal-title"></small></div></div><form class="erp-form design-update-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field(self::NONCE,'nonce');echo'<input type="hidden" name="action" value="bsoerp_save_design_update"><input type="hidden" name="design_id" value=""><div class="form-grid"><label><span>No of Design *</span><input type="number" name="assigned_qty" min="1" step="1" required readonly aria-readonly="true" class="recce-readonly-field"></label><label><span>Pending *</span><input type="number" name="pending_qty" min="0" step="1" required readonly aria-readonly="true" class="recce-readonly-field"></label><label><span>Completed</span><input type="number" name="completed_qty" min="0" step="1" value=""></label><label><span>Cancel</span><input type="number" name="canceled_qty" min="0" step="1" value=""></label><label><span>Update By *</span><select name="updated_by_user" class="no-search-select" required><option value="0">Select User</option>';foreach($this->master_options('users')as$u)echo'<option value="'.$u->id.'">'.esc_html($u->title).'</option>';echo'</select></label><label class="wide"><span>Update Document</span><input type="file" name="update_document" accept="image/*,.pdf,.xls,.xlsx,.csv,.doc,.docx,.ppt,.pptx,.txt,.zip"></label><label class="wide"><span>Update Remarks *</span><textarea name="update_remarks" rows="4" required placeholder="Enter design update remarks"></textarea></label></div><div class="form-actions"><button class="btn primary" type="submit">Save Update</button><button class="btn" type="button" data-design-update-close>Cancel</button></div></form></div></div>';}
 function save_design_update(){if(!is_user_logged_in()||!current_user_can('bsoerp_access')||!wp_verify_nonce($_POST['nonce']??'',self::NONCE))wp_die('Invalid request');global$wpdb;$this->ensure_design_schema();$design_id=absint($_POST['design_id']??0);$design=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='designs'",$design_id));if(!$design)wp_die('Design record not found.');$assigned=max(0,(int)$this->design_meta_value($design,'design_assigned',0));$approval_required=(string)$this->design_meta_value($design,'approval_required','')==='1';$current=$this->design_totals($design_id,$assigned);$current_pending=(int)$current['pending'];$completed=absint($_POST['completed_qty']??0);$cancel=absint($_POST['canceled_qty']??0);$updated_by=absint($_POST['updated_by_user']??0);$remarks=sanitize_textarea_field(wp_unslash($_POST['update_remarks']??''));if($assigned<=0)wp_die('No of Design must be greater than 0.');if(!$updated_by||!$this->task_user_display_name($updated_by))wp_die('Update By is required.');if(trim($remarks)==='')wp_die('Update Remarks is required.');if(($completed+$cancel)>$current_pending)wp_die('Completed + Cancel cannot be greater than Pending.');$pending=$current_pending-$completed-$cancel;$document_id=0;if(!empty($_FILES['update_document'])&&!empty($_FILES['update_document']['name'])){require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';$document_id=media_handle_upload('update_document',0);if(is_wp_error($document_id))wp_die('Unable to upload Update Document: '.esc_html($document_id->get_error_message()));}$ok=$wpdb->insert($this->t('design_updates'),['design_id'=>$design_id,'assigned_qty'=>$assigned,'pending_qty'=>$pending,'completed_qty'=>$completed,'canceled_qty'=>$cancel,'action_text'=>$remarks,'document_id'=>(int)$document_id,'updated_by_user'=>$updated_by,'created_by'=>get_current_user_id(),'created_at'=>current_time('mysql')]);if(!$ok)wp_die('Unable to save Design update.');$after=$this->design_totals($design_id,$assigned);$needs_approval=$approval_required&&((int)$after['completed']>(int)$after['approved']);$new_status=$pending>0?'In Progress':($needs_approval?'Pending Approval':'Completed');$wpdb->update($this->t('records'),['status'=>$new_status,'updated_at'=>current_time('mysql')],['id'=>$design_id]);$this->activity($design_id,'designs','Design Updated',$design->title);$dest=$new_status==='In Progress'?'designs-in-progress':'design-master';wp_safe_redirect(add_query_arg('notice','saved',$this->url($dest)));exit;}
 function design_approval_modal(){echo'<div class="lead-update-modal design-approval-modal" id="design-approval-modal" aria-hidden="true"><div class="lead-update-modal-backdrop" data-design-approval-close></div><div class="lead-update-modal-card" role="dialog" aria-modal="true" aria-labelledby="design-approval-modal-title"><button type="button" class="lead-update-modal-close" data-design-approval-close aria-label="Close">×</button><div class="panel-head"><div><h2 id="design-approval-modal-title">Update Client Approval</h2><small class="design-approval-modal-title"></small></div></div><form class="erp-form design-approval-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field(self::NONCE,'nonce');echo'<input type="hidden" name="action" value="bsoerp_save_design_approval"><input type="hidden" name="design_id" value=""><input type="hidden" name="pending_approval_qty" value=""><div class="form-grid"><label><span>Pending Approval *</span><input type="number" name="pending_approval_display" min="0" step="1" readonly aria-readonly="true" class="recce-readonly-field"></label><label><span>Design Approved *</span><input type="number" name="design_approved" min="1" step="1" required></label></div><div class="form-actions"><button class="btn primary" type="submit">Save Client Approval</button><button class="btn" type="button" data-design-approval-close>Cancel</button></div></form></div></div>';}
 function save_design_approval(){if(!is_user_logged_in()||!current_user_can('bsoerp_access')||!wp_verify_nonce($_POST['nonce']??'',self::NONCE))wp_die('Invalid request');global$wpdb;$this->ensure_design_schema();$design_id=absint($_POST['design_id']??0);$design=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='designs'",$design_id));if(!$design)wp_die('Design record not found.');$assigned=max(0,(int)$this->design_meta_value($design,'design_assigned',0));$tot=$this->design_totals($design_id,$assigned);$pending_approval=max(0,(int)$tot['completed']-(int)$tot['approved']);$approve_now=absint($_POST['design_approved']??0);$remarks=sanitize_textarea_field(wp_unslash($_POST['customer_remarks']??''));if($pending_approval<=0)wp_die('No Pending Approval quantity is available.');if($approve_now<=0)wp_die('Design Approved must be greater than 0.');if($approve_now>$pending_approval)wp_die('Design Approved cannot be greater than Pending Approval.');$rows=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$this->t('design_updates')} WHERE design_id=%d AND completed_qty>COALESCE(approved_qty,0) ORDER BY created_at ASC,id ASC",$design_id));$remaining=$approve_now;$now=current_time('mysql');foreach($rows as$u){if($remaining<=0)break;$row_pending=max(0,(int)$u->completed_qty-(int)$u->approved_qty);if($row_pending<=0)continue;$take=min($remaining,$row_pending);$new_approved=(int)$u->approved_qty+$take;$data=['approved_qty'=>$new_approved,'approved_by_user'=>get_current_user_id(),'approved_at'=>$now];if($remarks!=='')$data['customer_remarks']=$remarks;$ok=$wpdb->update($this->t('design_updates'),$data,['id'=>(int)$u->id]);if($ok===false)wp_die('Unable to save Design approval.');$remaining-=$take;}if($remaining>0)wp_die('Unable to allocate the full approval quantity.');$after=$this->design_totals($design_id,$assigned);$still_pending=max(0,(int)$after['completed']-(int)$after['approved']);$new_status=((int)$after['pending']===0&&$still_pending===0)?'Completed':(((int)$after['pending']===0&&$still_pending>0)?'Pending Approval':'In Progress');$wpdb->update($this->t('records'),['status'=>$new_status,'updated_at'=>$now],['id'=>$design_id]);$this->activity($design_id,'designs','Design Approval Updated',$design->title.' | Approved: '.$approve_now.' | Pending Approval: '.$still_pending);wp_safe_redirect(add_query_arg('notice','saved',$this->url('designs-pending-approval')));exit;}
 function design_pending_approval_listing(){
  global$wpdb;$this->ensure_design_schema();
  $s=sanitize_text_field(wp_unslash($_GET['s']??''));$customer=absint($_GET['customer']??0);$designer=absint($_GET['designer']??0);$from=sanitize_text_field($_GET['date_from']??'');$to=sanitize_text_field($_GET['date_to']??'');
  $where=["r.module='designs'","r.status<>'Canceled'","r.meta LIKE '%\"approval_required\":\"1\"%'"];$args=[];
  if($s){$like='%'.$wpdb->esc_like($s).'%';$where[]='(r.reference_no LIKE %s OR r.title LIKE %s OR r.notes LIKE %s OR r.meta LIKE %s)';array_push($args,$like,$like,$like,$like);}
  if($customer){$where[]='r.customer_id=%d';$args[]=$customer;}if($designer){$where[]='r.assigned_to=%d';$args[]=$designer;}
  if($from){$where[]='EXISTS (SELECT 1 FROM '.$this->t('design_updates').' du1 WHERE du1.design_id=r.id AND DATE(du1.created_at)>=%s)';$args[]=$from;}
  if($to){$where[]='EXISTS (SELECT 1 FROM '.$this->t('design_updates').' du2 WHERE du2.design_id=r.id AND DATE(du2.created_at)<=%s)';$args[]=$to;}
  $sql="SELECT r.* FROM {$this->t('records')} r WHERE ".implode(' AND ',$where)." ORDER BY r.updated_at DESC,r.id DESC";$designs=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql);$rows=[];
  foreach($designs as$r){$assigned=max(0,(int)$this->design_meta_value($r,'design_assigned',0));$tot=$this->design_totals((int)$r->id,$assigned);$pending=max(0,(int)$tot['completed']-(int)$tot['approved']);if($pending<=0)continue;$latest=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('design_updates')} WHERE design_id=%d ORDER BY created_at DESC,id DESC LIMIT 1",$r->id));$rows[]=(object)['record'=>$r,'assigned'=>$assigned,'tot'=>$tot,'pending_approval'=>$pending,'latest'=>$latest];}
  echo'<div class="panel listing-panel" data-erp-live="1"><form class="toolbar master-toolbar design-server-toolbar" method="get"><input type="search" name="s" value="'.esc_attr($s).'" placeholder="Search Pending Design Approval" data-auto-search="1"><select name="customer" onchange="this.form.submit()"><option value="0">All Customers</option>';foreach($this->master_options('customers')as$o)echo'<option value="'.$o->id.'" '.selected($customer,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select><select name="designer" onchange="this.form.submit()"><option value="0">All Designers</option>';foreach($this->master_options('users')as$o)echo'<option value="'.$o->id.'" '.selected($designer,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select><label><span>Update Date From</span><input type="date" name="date_from" value="'.esc_attr($from).'" onchange="this.form.submit()"></label><label><span>Update Date To</span><input type="date" name="date_to" value="'.esc_attr($to).'" onchange="this.form.submit()"></label><a class="btn filter-clear" href="'.esc_url($this->url('designs-pending-approval')).'">Clear</a></form>';
  if(!$rows){echo'<div class="empty"><strong>No pending design approvals</strong><span>All completed Design quantities requiring client approval are approved.</span></div></div>';return;}
  echo'<div class="table-wrap"><table class="data"><thead><tr><th>Sl.</th><th>Date & Time</th><th>Design No.</th><th>Customer Name</th><th>Designer</th><th>No of Design</th><th>Design Completed</th><th>Design Pending</th><th>Approved Design</th><th>Pending Approval</th><th>Cancel</th><th>Action</th></tr></thead><tbody>';
  foreach($rows as$i=>$g){$r=$g->record;$t=$g->tot;$dt=($g->latest&&$g->latest->created_at)?$this->format_utc_to_ist($g->latest->created_at,'d/m/Y h:i A'):'—';echo'<tr><td>'.($i+1).'</td><td>'.esc_html($dt).'</td><td><strong>'.esc_html($r->reference_no?:'—').'</strong></td><td>'.esc_html($this->master_name_by_id($r->customer_id)?:'—').'</td><td>'.esc_html($this->task_user_display_name($r->assigned_to)?:'—').'</td><td>'.(int)$g->assigned.'</td><td>'.(int)$t['completed'].'</td><td>'.(int)$t['pending'].'</td><td>'.(int)$t['approved'].'</td><td><strong>'.(int)$g->pending_approval.'</strong></td><td>'.(int)$t['cancel'].'</td><td class="actions"><button type="button" class="btn primary compact-action update-icon-action design-approval-open" title="Update Approval" aria-label="Update Approval" data-design-id="'.(int)$r->id.'" data-design-title="'.esc_attr($this->master_name_by_id($r->customer_id)?:$r->title).'" data-pending-approval="'.(int)$g->pending_approval.'">✓</button></td></tr>';}
  echo'</tbody></table></div></div>';$this->design_approval_modal();
 }
 function design_listing($v){
  global$wpdb;
  $s=sanitize_text_field(wp_unslash($_GET['s']??''));$customer=absint($_GET['customer']??0);$designer=absint($_GET['designer']??0);$from=sanitize_text_field($_GET['date_from']??'');$to=sanitize_text_field($_GET['date_to']??'');
  $where=["module='designs'"];$args=[];$states=['designs-in-progress'=>['In Progress','Pending'],'designs-pending-approval'=>['Pending Approval'],'completed-designs'=>['Completed']][$v]??[];
  if($states){$where[]='status IN ('.implode(',',array_fill(0,count($states),'%s')).')';$args=array_merge($args,$states);}if($s){$like='%'.$wpdb->esc_like($s).'%';$where[]='(title LIKE %s OR notes LIKE %s OR meta LIKE %s)';array_push($args,$like,$like,$like);}if($customer){$where[]='customer_id=%d';$args[]=$customer;}if($designer){$where[]='assigned_to=%d';$args[]=$designer;}if($from){$where[]='due_date>=%s';$args[]=$from;}if($to){$where[]='due_date<=%s';$args[]=$to;}
  $sql="SELECT * FROM {$this->t('records')} WHERE ".implode(' AND ',$where).' ORDER BY updated_at DESC,id DESC';$rows=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql);
  echo'<div class="panel listing-panel"><form class="toolbar master-toolbar design-server-toolbar" method="get"><input type="search" name="s" value="'.esc_attr($s).'" placeholder="Search Designs" data-auto-search="1"><select name="customer" onchange="this.form.submit()"><option value="0">All Customers</option>';foreach($this->master_options('customers')as$o)echo'<option value="'.$o->id.'" '.selected($customer,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select><select name="designer" onchange="this.form.submit()"><option value="0">All Designers</option>';foreach($this->master_options('users')as$o)echo'<option value="'.$o->id.'" '.selected($designer,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select><label><span>Due Date From</span><input type="date" name="date_from" value="'.esc_attr($from).'" onchange="this.form.submit()"></label><label><span>Due Date To</span><input type="date" name="date_to" value="'.esc_attr($to).'" onchange="this.form.submit()"></label><a class="btn filter-clear" href="'.esc_url($this->url($v)).'">Clear</a></form>';
  if(!$rows)echo'<div class="empty"><strong>No records found</strong><span>Add a Design Job to begin.</span></div>';
  else{
   echo'<div class="table-wrap"><table class="data"><thead><tr><th>Sl.</th><th>Design No.</th><th>Date</th><th>Customer Name</th><th>Designer</th><th>Due Date</th><th>No of Design</th><th>Design Completed</th><th>Design Pending</th><th>Approved Design</th><th>Pending Approval</th><th>Cancel</th><th>Remarks</th><th>Document</th><th>Action</th></tr></thead><tbody>';
   foreach($rows as$i=>$r){$assigned_qty=max(0,(int)$this->design_meta_value($r,'design_assigned',0));$approval_required=(string)$this->design_meta_value($r,'approval_required','')==='1';$dt=$this->design_totals($r->id,$assigned_qty);$pending_approval=$approval_required?max(0,(int)$dt['completed']-(int)$dt['approved']):0;$approval_update=null;if($v==='design-master'&&$approval_required&&$pending_approval>0){$approval_update=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('design_updates')} WHERE design_id=%d AND completed_qty>COALESCE(approved_qty,0) ORDER BY created_at ASC,id ASC LIMIT 1",$r->id));}$row_attrs='';if($v==='design-master'){$details_pdf=wp_nonce_url(add_query_arg(['action'=>'bsoerp_design_details_pdf','design_id'=>(int)$r->id],admin_url('admin-post.php')),'bsoerp_design_details_pdf_'.(int)$r->id);$row_attrs=' class="design-details-row" title="Click row for Action Details" data-design-id="'.(int)$r->id.'" data-design-title="'.esc_attr($this->master_name_by_id($r->customer_id)?:$r->title).'" data-design-assigned="'.$assigned_qty.'" data-design-pdf="'.esc_attr($details_pdf).'"';}echo'<tr'.$row_attrs.'><td>'.($i+1).'</td><td><strong>'.esc_html($r->reference_no?:'—').'</strong></td><td>'.($r->record_date?esc_html(date_i18n('d/m/Y',strtotime($r->record_date))).(!empty($r->created_at)?' '.esc_html($this->format_utc_to_ist($r->created_at,'H:i')):''):'—').'</td><td>'.esc_html($this->master_name_by_id($r->customer_id)?:'—').'</td><td>'.esc_html($this->task_user_display_name($r->assigned_to)?:'—').'</td><td>'.($r->due_date?esc_html(date_i18n('d/m/Y',strtotime($r->due_date))):'—').'</td><td>'.esc_html($this->design_meta_value($r,'design_assigned','—')).'</td><td>'.(int)$dt['completed'].'</td><td>'.(int)$dt['pending'].'</td><td>'.(int)$dt['approved'].'</td><td>'.$pending_approval.'</td><td>'.(int)$dt['cancel'].'</td><td>'.nl2br(esc_html($r->notes?:'—')).'</td><td>'.$this->recce_document_link($this->design_meta_value($r,'document',0)).'</td><td class="actions">'.($v==='designs-in-progress'?'<button type="button" class="btn primary compact-action update-icon-action design-update-open" title="Update Design" aria-label="Update Design" data-design-id="'.(int)$r->id.'" data-design-title="'.esc_attr($this->master_name_by_id($r->customer_id)?:$r->title).'" data-assigned="'.$assigned_qty.'" data-pending="'.(int)$dt['pending'].'" data-designer-id="'.(int)$r->assigned_to.'">✓</button>':'').($v==='design-master'?(function() use ($r,$assigned_qty,$approval_update){$details_pdf=wp_nonce_url(add_query_arg(['action'=>'bsoerp_design_details_pdf','design_id'=>(int)$r->id],admin_url('admin-post.php')),'bsoerp_design_details_pdf_'.(int)$r->id);$approval_btn=$approval_update?'<button type="button" class="btn primary compact-action design-approval-open" title="Update Client Approval" aria-label="Update Client Approval" data-design-id="'.(int)$r->id.'" data-design-title="'.esc_attr($this->master_name_by_id($r->customer_id)?:$r->title).'" data-pending-approval="'.max(0,(int)$this->design_totals((int)$r->id,$assigned_qty)['completed']-(int)$this->design_totals((int)$r->id,$assigned_qty)['approved']).'" data-remarks="'.esc_attr($approval_update->customer_remarks).'">✓</button>':'';return $approval_btn;})():'').'<a title="Edit" href="'.esc_url(add_query_arg('edit',$r->id,$this->url($v))).'">✎</a>'.(($v==='design-master'&&current_user_can('bsoerp_manage'))?'<a title="Delete" class="delete" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=bsoerp_delete&id='.$r->id),'bsoerp_del_'.$r->id)).'">⌫</a>':'').'</td></tr>';}
   echo'</tbody></table></div>';
  }
  if($v==='design-master'){
   foreach($rows as$r){$history=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$this->t('design_updates')} WHERE design_id=%d ORDER BY created_at ASC,id ASC",$r->id));echo'<div class="design-details-template" id="design-details-template-'.(int)$r->id.'" hidden>';if(!$history){echo'<div class="empty"><strong>No Design Worked data</strong><span>No updates have been saved for this Design.</span></div>';}else{echo'<div class="table-wrap"><table class="data"><thead><tr><th>Sl.</th><th>Date & Time</th><th>Designer</th><th>No of Design</th><th>Design Completed</th><th>Design Pending</th><th>Approved Design</th><th>Cancel</th><th>Update Remarks</th><th>Update Document</th><th>Customer Remarks</th><th>Update By</th><th>Action</th></tr></thead><tbody>';foreach($history as$hi=>$u){$edit_btn=current_user_can('bsoerp_manage')?'<button type="button" class="btn compact-action design-history-edit" title="Edit Update" aria-label="Edit Update" data-update-id="'.(int)$u->id.'" data-design-id="'.(int)$r->id.'" data-design-title="'.esc_attr($this->master_name_by_id($r->customer_id)?:$r->title).'" data-assigned="'.(int)$u->assigned_qty.'" data-completed="'.(int)$u->completed_qty.'" data-cancel="'.(int)$u->canceled_qty.'" data-approved="'.(int)$u->approved_qty.'" data-updated-by="'.(int)$u->updated_by_user.'" data-remarks="'.esc_attr($u->action_text).'">✎</button>':'—';echo'<tr><td>'.($hi+1).'</td><td>'.esc_html($this->format_utc_to_ist($u->created_at,'d/m/Y h:i A')).'</td><td>'.esc_html($this->task_user_display_name($r->assigned_to)?:'—').'</td><td>'.(int)$u->assigned_qty.'</td><td>'.(int)$u->completed_qty.'</td><td>'.(int)$u->pending_qty.'</td><td>'.(int)$u->approved_qty.'</td><td>'.(int)$u->canceled_qty.'</td><td>'.nl2br(esc_html($u->action_text?:'—')).'</td><td>'.$this->recce_document_link($u->document_id).'</td><td>'.nl2br(esc_html($u->customer_remarks?:'—')).'</td><td>'.esc_html($this->task_user_display_name($u->updated_by_user)?:'—').'</td><td class="actions">'.$edit_btn.'</td></tr>';}echo'</tbody></table></div>';}echo'</div>';}
   $this->design_details_modal();$this->design_history_edit_modal();$this->design_approval_modal();
  }
  echo'</div>';if($v==='designs-in-progress')$this->design_update_modal();
 }
 function design_details_modal(){echo'<div class="lead-update-modal design-details-modal" id="design-details-modal" aria-hidden="true"><div class="lead-update-modal-backdrop" data-design-details-close></div><div class="lead-update-modal-card recce-details-modal-card" role="dialog" aria-modal="true" aria-labelledby="design-details-modal-heading"><button type="button" class="lead-update-modal-close" data-design-details-close aria-label="Close">×</button><div class="panel-head recce-details-head"><div><h2 id="design-details-modal-heading">Design Action Details</h2><small class="design-details-modal-title"></small></div><div class="head-actions"><a class="btn design-details-pdf-link" href="#" target="_blank" rel="noopener">⇩ PDF</a></div></div><div class="design-details-modal-body"></div></div></div>'; }
 function design_history_edit_modal(){echo'<div class="lead-update-modal design-history-edit-modal" id="design-history-edit-modal" aria-hidden="true"><div class="lead-update-modal-backdrop" data-design-history-edit-close></div><div class="lead-update-modal-card" role="dialog" aria-modal="true" aria-labelledby="design-history-edit-title"><button type="button" class="lead-update-modal-close" data-design-history-edit-close aria-label="Close">×</button><div class="panel-head"><div><h2 id="design-history-edit-title">Edit Design Update</h2><small class="design-history-edit-subtitle"></small></div></div><form class="erp-form design-history-edit-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field(self::NONCE,'nonce');echo'<input type="hidden" name="action" value="bsoerp_edit_design_update"><input type="hidden" name="update_id" value=""><input type="hidden" name="design_id" value=""><input type="hidden" name="approved_qty" value="0"><div class="form-grid"><label><span>No of Design *</span><input type="number" name="assigned_qty" readonly aria-readonly="true" class="recce-readonly-field"></label><label><span>Design Completed *</span><input type="number" name="completed_qty" min="0" step="1" required></label><label><span>Cancel *</span><input type="number" name="canceled_qty" min="0" step="1" required></label><label><span>Update By *</span><select name="updated_by_user" class="no-search-select" required><option value="0">Select User</option>';foreach($this->master_options('users')as$u)echo'<option value="'.$u->id.'">'.esc_html($u->title).'</option>';echo'</select></label><label class="wide"><span>Replace Update Document</span><input type="file" name="update_document" accept="image/*,.pdf,.xls,.xlsx,.csv,.doc,.docx,.ppt,.pptx,.txt,.zip"></label><label class="wide"><span>Update Remarks *</span><textarea name="update_remarks" rows="4" required></textarea></label></div><div class="form-actions"><button class="btn primary" type="submit">Save Changes</button><button class="btn" type="button" data-design-history-edit-close>Cancel</button></div></form></div></div>';}
 function edit_design_update(){if(!is_user_logged_in()||!current_user_can('bsoerp_manage')||!wp_verify_nonce($_POST['nonce']??'',self::NONCE))wp_die('Invalid request');global$wpdb;$this->ensure_design_schema();$update_id=absint($_POST['update_id']??0);$design_id=absint($_POST['design_id']??0);$u=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('design_updates')} WHERE id=%d AND design_id=%d",$update_id,$design_id));if(!$u)wp_die('Design update not found.');$design=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='designs'",$design_id));if(!$design)wp_die('Design record not found.');$assigned=max(0,(int)$this->design_meta_value($design,'design_assigned',0));$completed=absint($_POST['completed_qty']??0);$cancel=absint($_POST['canceled_qty']??0);$updated_by=absint($_POST['updated_by_user']??0);$remarks=sanitize_textarea_field(wp_unslash($_POST['update_remarks']??''));if(!$updated_by||!$this->task_user_display_name($updated_by))wp_die('Update By is required.');if(trim($remarks)==='')wp_die('Update Remarks is required.');if($completed<(int)$u->approved_qty)wp_die('Design Completed cannot be less than already Approved Design quantity ('.(int)$u->approved_qty.').');$others=$wpdb->get_row($wpdb->prepare("SELECT COALESCE(SUM(completed_qty),0) completed,COALESCE(SUM(canceled_qty),0) canceled FROM {$this->t('design_updates')} WHERE design_id=%d AND id<>%d",$design_id,$update_id));$used=(int)$others->completed+(int)$others->canceled+$completed+$cancel;if($used>$assigned)wp_die('Total Design Completed + Cancel cannot be greater than No of Design ('.$assigned.').');$data=['assigned_qty'=>$assigned,'completed_qty'=>$completed,'canceled_qty'=>$cancel,'action_text'=>$remarks,'updated_by_user'=>$updated_by];if(!empty($_FILES['update_document'])&&!empty($_FILES['update_document']['name'])){require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';$document_id=media_handle_upload('update_document',0);if(is_wp_error($document_id))wp_die('Unable to upload Update Document: '.esc_html($document_id->get_error_message()));$data['document_id']=(int)$document_id;}$ok=$wpdb->update($this->t('design_updates'),$data,['id'=>$update_id,'design_id'=>$design_id]);if($ok===false)wp_die('Unable to update Design activity.');$history=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$this->t('design_updates')} WHERE design_id=%d ORDER BY created_at ASC,id ASC",$design_id));$remaining=$assigned;foreach($history as$row){$remaining=max(0,$remaining-(int)$row->completed_qty-(int)$row->canceled_qty);$wpdb->update($this->t('design_updates'),['pending_qty'=>$remaining],['id'=>(int)$row->id]);}$tot=$this->design_totals($design_id,$assigned);$approval_required=(string)$this->design_meta_value($design,'approval_required','')==='1';$pending_approval=$approval_required?max(0,(int)$tot['completed']-(int)$tot['approved']):0;$new_status=((int)$tot['pending']>0)?'In Progress':($pending_approval>0?'Pending Approval':'Completed');$wpdb->update($this->t('records'),['status'=>$new_status,'updated_at'=>current_time('mysql')],['id'=>$design_id]);$this->activity($design_id,'designs','Design Update Edited',$design->title.' | Update ID: '.$update_id);wp_safe_redirect(add_query_arg(['notice'=>'saved','open_design_details'=>$design_id],$this->url('design-master')));exit;}
 function design_details_pdf(){if(!current_user_can('bsoerp_access'))wp_die('Access denied');$id=absint($_GET['design_id']??0);if(!$id||!wp_verify_nonce($_GET['_wpnonce']??'','bsoerp_design_details_pdf_'.$id))wp_die('Invalid request');global$wpdb;$this->ensure_design_schema();$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='designs'",$id));if(!$r)wp_die('Design not found.');$updates=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$this->t('design_updates')} WHERE design_id=%d ORDER BY created_at ASC,id ASC",$id));$name=$this->master_name_by_id($r->customer_id)?:$r->title;$assigned=max(0,(int)$this->design_meta_value($r,'design_assigned',0));nocache_headers();header('Content-Type:text/html; charset=utf-8');echo'<!doctype html><html><head><meta charset="utf-8"><title>Design Action Details</title><style>@page{size:A5 landscape;margin:8mm}body{font-family:Arial,sans-serif;color:#111;font-size:11px}h1{font-size:18px;margin:0 0 5px}.meta{margin:0 0 14px;color:#444}.actions{display:flex;justify-content:flex-end;margin-bottom:12px}button{padding:8px 12px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #777;padding:6px;vertical-align:top;text-align:left}th{background:#eee}@media print{.actions{display:none}}</style></head><body><div class="actions"><button onclick="window.print()">Download / Save PDF</button></div><h1>Design Action Details</h1><div class="meta"><strong>'.esc_html($name).'</strong> | No of Design: '.esc_html((string)$assigned).'</div><table><thead><tr><th>Sl.</th><th>Date & Time</th><th>Designer</th><th>No of Design</th><th>Design Completed</th><th>Design Pending</th><th>Approved Design</th><th>Cancel</th><th>Update Remarks</th><th>Customer Remarks</th><th>Update By</th></tr></thead><tbody>';if($updates){foreach($updates as$i=>$u){echo'<tr><td>'.($i+1).'</td><td>'.esc_html($this->format_utc_to_ist($u->created_at,'d/m/Y h:i A')).'</td><td>'.esc_html($this->task_user_display_name($r->assigned_to)?:'—').'</td><td>'.(int)$u->assigned_qty.'</td><td>'.(int)$u->completed_qty.'</td><td>'.(int)$u->pending_qty.'</td><td>'.(int)$u->approved_qty.'</td><td>'.(int)$u->canceled_qty.'</td><td>'.nl2br(esc_html($u->action_text?:'—')).'</td><td>'.nl2br(esc_html($u->customer_remarks?:'—')).'</td><td>'.esc_html($this->task_user_display_name($u->updated_by_user)?:'—').'</td></tr>';}}else echo'<tr><td colspan="11">No Design Worked data</td></tr>';echo'</tbody></table></body></html>';exit;}
 function design_worked_listing(){global$wpdb;$this->ensure_design_schema();$s=sanitize_text_field(wp_unslash($_GET['s']??''));$date_from=sanitize_text_field($_GET['date_from']??'');$date_to=sanitize_text_field($_GET['date_to']??'');$where=['1=1'];$args=[];if($s){$like='%'.$wpdb->esc_like($s).'%';$where[]='(r.title LIKE %s OR r.notes LIKE %s)';array_push($args,$like,$like);}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$date_from)){$where[]='DATE(u.created_at)>=%s';$args[]=$date_from;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$date_to)){$where[]='DATE(u.created_at)<=%s';$args[]=$date_to;}$sql="SELECT u.*,r.customer_id,r.title,r.assigned_to,r.meta,r.reference_no FROM {$this->t('design_updates')} u JOIN {$this->t('records')} r ON r.id=u.design_id WHERE ".implode(' AND ',$where).' ORDER BY u.created_at DESC,u.id DESC';$rows=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql);echo'<div class="panel listing-panel"><form class="toolbar master-toolbar" method="get"><label><span>Search</span><input type="search" name="s" value="'.esc_attr($s).'" placeholder="Search Design Activity" data-auto-search="1"></label><label><span>Date From</span><input type="date" name="date_from" value="'.esc_attr($date_from).'"></label><label><span>Date To</span><input type="date" name="date_to" value="'.esc_attr($date_to).'"></label><button class="btn" type="submit">Filter</button><a class="btn filter-clear" href="'.esc_url($this->url('design-worked')).'">Clear</a></form>';if(!$rows)echo'<div class="empty"><strong>No Design Activity data</strong><span>Design updates will appear here.</span></div>';else{echo'<div class="table-wrap"><table class="data"><thead><tr><th>Sl.</th><th>Date & Time</th><th>Design No.</th><th>Customer Name</th><th>Designer</th><th>No of Design</th><th>Design Completed</th><th>Design Pending</th><th>Approved Design</th><th>Pending Approval</th><th>Cancel</th><th>Update Remarks</th><th>Update Document</th><th>Update By</th></tr></thead><tbody>';foreach($rows as$i=>$r){$approval_required=strpos((string)$r->meta,'\"approval_required\":\"1\"')!==false;$pending_approval=$approval_required?max(0,(int)$r->completed_qty-(int)$r->approved_qty):0;echo'<tr><td>'.($i+1).'</td><td>'.esc_html($this->format_utc_to_ist($r->created_at,'d/m/Y h:i A')).'</td><td>'.esc_html($r->reference_no?:'—').'</td><td>'.esc_html($this->master_name_by_id($r->customer_id)?:'—').'</td><td>'.esc_html($this->task_user_display_name($r->assigned_to)?:'—').'</td><td>'.(int)$r->assigned_qty.'</td><td>'.(int)$r->completed_qty.'</td><td>'.(int)$r->pending_qty.'</td><td>'.(int)$r->approved_qty.'</td><td>'.$pending_approval.'</td><td>'.(int)$r->canceled_qty.'</td><td>'.nl2br(esc_html($r->action_text?:'—')).'</td><td>'.$this->recce_document_link($r->document_id).'</td><td>'.esc_html($this->task_user_display_name($r->updated_by_user)?:'—').'</td></tr>'; }echo'</tbody></table></div>';}echo'</div>';}


 function quotation_workflow_listing($v){
  global$wpdb;$status_map=['pending-checking'=>'Pending Checking','quotations-pending-approval'=>'Pending Approval'];$status=$status_map[$v]??'';
  $search=sanitize_text_field(wp_unslash($_GET['s']??''));$customer=absint($_GET['customer']??0);$from=sanitize_text_field($_GET['date_from']??'');$to=sanitize_text_field($_GET['date_to']??'');$where=["module='quotations'",'status=%s'];$args=[$status];
  if($search){$like='%'.$wpdb->esc_like($search).'%';$where[]='(reference_no LIKE %s OR title LIKE %s)';$args[]=$like;$args[]=$like;}if($customer){$where[]='customer_id=%d';$args[]=$customer;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where[]='record_date>=%s';$args[]=$from;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where[]='record_date<=%s';$args[]=$to;}
  $per=$this->pagination_size();$page=max(1,absint($_GET['pg']??1));$off=($page-1)*$per;$base="FROM {$this->t('records')} WHERE ".implode(' AND ',$where);$total=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) $base",$args));$rows=$wpdb->get_results($wpdb->prepare("SELECT * $base ORDER BY updated_at DESC,id DESC LIMIT $per OFFSET $off",$args));
  $filter_args=array_filter(['s'=>$search,'customer'=>$customer,'date_from'=>$from,'date_to'=>$to],fn($x)=>$x!==''&&$x!==0);$export=wp_nonce_url(add_query_arg(array_merge(['action'=>'bsoerp_export','view'=>$v],$filter_args),admin_url('admin-post.php')),'bsoerp_export');
  echo'<div class="panel listing-panel"><div class="panel-head"><div><h2>'.esc_html($this->flat()[$v]).'</h2></div><div class="head-actions"><a class="btn mobile-excel" href="'.esc_url($export).'">⇩ Excel</a></div></div>';
  echo'<form class="toolbar task-filter-toolbar" method="get"><label><span>Search</span><input type="search" name="s" value="'.esc_attr($search).'" placeholder="Search quotations" data-auto-search="1"></label><label><span>Customer</span><select name="customer" onchange="this.form.submit()"><option value="0">All Customers</option>';foreach($this->master_options('customers')as$o)echo'<option value="'.$o->id.'" '.selected($customer,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select></label><label><span>Date From</span><input type="date" name="date_from" value="'.esc_attr($from).'" onchange="this.form.submit()"></label><label><span>Date To</span><input type="date" name="date_to" value="'.esc_attr($to).'" onchange="this.form.submit()"></label><a class="btn filter-clear" href="'.esc_url($this->url($v)).'">Clear</a></form>';
  if(!$rows){echo'<div class="empty"><strong>No quotations found</strong><span>No records match the current view.</span></div>';}else{echo'<div class="table-wrap"><table class="data"><thead><tr><th>Sl.</th><th>Date</th><th>Customer Name</th><th>Made By</th><th>Amount</th><th>GST</th><th>Total Amount</th><th>Status</th><th>Action</th></tr></thead><tbody>';foreach($rows as$i=>$r){$m=json_decode((string)$r->meta,true);if(!is_array($m))$m=[];echo'<tr class="quotation-parent-row" data-quotation-toggle="'.(int)$r->id.'" tabindex="0"><td>'.(($page-1)*$per+$i+1).'</td><td>'.($r->record_date?esc_html(date_i18n('d/m/Y',strtotime($r->record_date))):'—').'</td><td>'.esc_html($this->master_name_by_id($r->customer_id)).'</td><td>'.esc_html($this->task_user_display_name($r->created_by)?:$this->user_display_name($r->created_by)).'</td><td>'.esc_html(number_format_i18n((float)($m['quotation_subtotal']??0),2)).'</td><td>'.esc_html(number_format_i18n((float)($m['quotation_gst']??0),2)).'</td><td>'.esc_html(number_format_i18n((float)($m['quotation_total']??$r->amount),2)).'</td><td><span class="status '.sanitize_html_class(strtolower(str_replace(' ','-',$r->status))).'">'.esc_html($r->status==='Pending Approval'?'Pending Client Approval':$r->status).'</span></td><td class="actions">';
    if($v==='pending-checking'){echo'<button type="button" class="btn primary compact-action update-icon-action quotation-checking-open" title="Update Checking" aria-label="Update Checking" data-id="'.(int)$r->id.'" data-title="'.esc_attr($this->master_name_by_id($r->customer_id)).'">✓</button><a title="Edit" href="'.esc_url(add_query_arg('edit',$r->id,$this->url($v))).'">✎</a>';}
    else{echo'<button type="button" class="btn primary compact-action update-icon-action quotation-status-open" title="Update Quotation Status" aria-label="Update Quotation Status" data-id="'.(int)$r->id.'" data-title="'.esc_attr($this->master_name_by_id($r->customer_id)).'">✓</button>';}
    echo'</td></tr><tr class="quotation-detail-row" id="quotation-detail-'.(int)$r->id.'" hidden><td colspan="9">'.$this->quotation_items_detail_html($r->id).'</td></tr>';}
    echo'</tbody></table></div>';}
  $this->pagination_controls($total,$page,$per,add_query_arg($filter_args,$this->url($v)));$this->quotation_expand_script();echo'</div>';
  $today=wp_date('Y-m-d');
  if($v==='pending-checking'){echo'<div class="lead-update-modal" id="quotation-checking-modal" aria-hidden="true"><div class="lead-update-modal-backdrop" data-quotation-checking-close></div><div class="lead-update-modal-card quotation-workflow-modal" role="dialog" aria-modal="true"><button type="button" class="lead-update-modal-close" data-quotation-checking-close>×</button><div class="panel-head"><div><h2>Update Checking</h2><small class="quotation-checking-title"></small></div></div><form class="erp-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field(self::NONCE,'nonce');echo'<input type="hidden" name="action" value="bsoerp_quotation_workflow"><input type="hidden" name="workflow_action" value="checking"><input type="hidden" name="quotation_id" value=""><div class="form-grid"><label><span>Check Date *</span><input type="date" name="check_date" value="'.esc_attr($today).'" required></label><label><span>Check By *</span><select name="check_by" class="no-search-select" required><option value="0">Select User</option>';foreach($this->master_options('users')as$u)echo'<option value="'.$u->id.'">'.esc_html($u->title).'</option>';echo'</select></label><label class="wide"><span>Checking Remarks</span><textarea name="checking_remarks" rows="3" placeholder="Enter checking remarks"></textarea></label></div><div class="form-actions"><button class="btn primary" type="submit">Save Checking</button><button class="btn" type="button" data-quotation-checking-close>Cancel</button></div></form></div></div><script>(function(){var m=document.getElementById("quotation-checking-modal");if(!m)return;document.addEventListener("click",function(e){var b=e.target.closest(".quotation-checking-open");if(b){m.querySelector("input[name=quotation_id]").value=b.getAttribute("data-id")||"";var t=m.querySelector(".quotation-checking-title");if(t)t.textContent=b.getAttribute("data-title")||"";m.classList.add("is-open");m.setAttribute("aria-hidden","false");}if(e.target.closest("[data-quotation-checking-close]")){m.classList.remove("is-open");m.setAttribute("aria-hidden","true");}});})();</script>';}
  if($v==='quotations-pending-approval'){echo'<div class="lead-update-modal" id="quotation-status-modal" aria-hidden="true"><div class="lead-update-modal-backdrop" data-quotation-status-close></div><div class="lead-update-modal-card quotation-status-modal-card" role="dialog" aria-modal="true"><button type="button" class="lead-update-modal-close" data-quotation-status-close>×</button><div class="panel-head"><div><h2>Update Quotation Status</h2><small class="quotation-status-title"></small></div></div><form class="erp-form" method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field(self::NONCE,'nonce');echo'<input type="hidden" name="action" value="bsoerp_quotation_workflow"><input type="hidden" name="workflow_action" value="status"><input type="hidden" name="quotation_id" value=""><div class="form-grid single-column"><label><span>Status *</span><select name="quotation_status" class="no-search-select" required><option value="">Select Status</option><option value="Approved">Approved</option><option value="Rejected">Rejected</option></select></label><label><span>Update By *</span><select name="status_update_by" class="no-search-select" required><option value="0">Select User</option>';foreach($this->master_options('users')as$u)echo'<option value="'.$u->id.'">'.esc_html($u->title).'</option>';echo'</select></label><label class="wide quotation-client-remarks-field"><span>Client Remarks</span><textarea name="client_remarks" rows="3" placeholder="Enter client remarks"></textarea><small class="client-remarks-hint">Required when status is Rejected.</small></label></div><div class="form-actions"><button class="btn primary" type="submit">Save Status</button><button class="btn" type="button" data-quotation-status-close>Cancel</button></div></form></div></div><script>(function(){var m=document.getElementById("quotation-status-modal");if(!m)return;var status=m.querySelector("select[name=quotation_status]"),remarks=m.querySelector("textarea[name=client_remarks]");function sync(){if(!status||!remarks)return;remarks.required=status.value==="Rejected";var sp=remarks.closest("label").querySelector("span");if(sp)sp.textContent=status.value==="Rejected"?"Client Remarks *":"Client Remarks";}if(status)status.addEventListener("change",sync);document.addEventListener("click",function(e){var b=e.target.closest(".quotation-status-open");if(b){m.querySelector("input[name=quotation_id]").value=b.getAttribute("data-id")||"";var t=m.querySelector(".quotation-status-title");if(t)t.textContent=b.getAttribute("data-title")||"";if(status)status.value="";if(remarks)remarks.value="";sync();m.classList.add("is-open");m.setAttribute("aria-hidden","false");}if(e.target.closest("[data-quotation-status-close]")){m.classList.remove("is-open");m.setAttribute("aria-hidden","true");}});})();</script>';}
 }
 function quotation_items_detail_html($quotation_id){
  global$wpdb;$lines=$wpdb->get_results($wpdb->prepare("SELECT l.*,i.title item_title FROM {$this->t('line_items')} l LEFT JOIN {$this->t('records')} i ON i.id=l.item_id WHERE l.record_id=%d ORDER BY l.sort_order,l.id",$quotation_id));
  if(!$lines)return'<div class="empty quotation-items-empty"><strong>No item rows found</strong><span>No item rows are saved for this quotation.</span></div>';
  $html='<div class="quotation-inline-items"><div class="table-wrap"><table class="data quotation-items-detail-table"><thead><tr><th>Particulars</th><th>Description</th><th>Qty</th><th>UOM</th><th>Rate</th><th>GST%</th><th>GST</th><th>Amount</th></tr></thead><tbody>';
  foreach($lines as$l){$m=json_decode((string)$l->meta,true);if(!is_array($m))$m=[];$base=(float)$l->qty*(float)$l->rate;$html.='<tr><td>'.esc_html($l->item_title?:'—').'</td><td>'.esc_html($l->description?:'—').'</td><td>'.esc_html($l->qty).'</td><td>'.esc_html($l->uom?:'—').'</td><td>'.esc_html(number_format_i18n((float)$l->rate,2)).'</td><td>'.esc_html(number_format_i18n((float)($m['gst_percent']??0),2)).'</td><td>'.esc_html(number_format_i18n((float)($m['gst_amount']??0),2)).'</td><td>'.esc_html(number_format_i18n($base,2)).'</td></tr>';}
  return$html.'</tbody></table></div></div>';
 }
