 function save_quotation_workflow(){
  if(!is_user_logged_in()||!current_user_can('bsoerp_access')||!wp_verify_nonce($_POST['nonce']??'',self::NONCE))wp_die('Invalid request');
  global$wpdb;
  $id=absint($_POST['quotation_id']??0);
  $q=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='quotations'",$id));
  if(!$q)wp_die('Quotation not found.');
  $action=sanitize_key($_POST['workflow_action']??'');
  if($action!=='status')wp_die('Invalid quotation workflow action.');
  if(!in_array($q->status,['Pending Approval','Approved','Rejected'],true))wp_die('Client approval cannot be updated for this quotation.');
  $next=sanitize_text_field($_POST['quotation_status']??'');
  if(!in_array($next,['Approved','Rejected'],true))wp_die('Please select a valid client approval status.');
  $client_remarks=sanitize_textarea_field(wp_unslash($_POST['client_remarks']??''));
  $approval_date=sanitize_text_field($_POST['approval_date']??current_time('Y-m-d'));
  if(!$approval_date||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$approval_date))$approval_date=current_time('Y-m-d');
  $meta=json_decode((string)$q->meta,true);if(!is_array($meta))$meta=[];
  $meta['status_update_by']=get_current_user_id();
  $meta['status_update_at']=current_time('mysql');
  $meta['client_approval_date']=$approval_date;
  $meta['client_remarks']=$client_remarks;
  $wpdb->query('START TRANSACTION');
  try{
   if($next==='Approved'){
    $order_id=$this->ensure_order_from_quotation($id);
    if(is_wp_error($order_id))throw new Exception($order_id->get_error_message());
    $meta['generated_order_id']=(int)$order_id;
    $meta['order_created_at']=$meta['order_created_at']??current_time('mysql');
   }
   $update=['status'=>$next,'meta'=>wp_json_encode($meta),'approval_remarks'=>$client_remarks,'approved_by'=>get_current_user_id(),'approved_at'=>$approval_date.' '.current_time('H:i:s'),'updated_at'=>current_time('mysql')];
   $ok=$wpdb->update($this->t('records'),$update,['id'=>$id]);
   if($ok===false)throw new Exception($wpdb->last_error?:'Unable to update client approval.');
   $this->activity($id,'quotations','Quotation '.$next,$q->title);
   $wpdb->query('COMMIT');
  }catch(Throwable $e){$wpdb->query('ROLLBACK');wp_die(esc_html($e->getMessage()));}
  wp_safe_redirect(add_query_arg('notice','saved',$this->url('quotation-master')));exit;
 }
 function save_order_delivery(){
  if(!is_user_logged_in()||!current_user_can('bsoerp_access')||!wp_verify_nonce($_POST['nonce']??'',self::NONCE))wp_die('Invalid request');
  global$wpdb;$id=absint($_POST['order_id']??0);$date=sanitize_text_field($_POST['delivery_date']??'');$by=absint($_POST['delivered_by']??0);$transporter_courier_id=absint($_POST['transporter_courier_id']??0);$vehicle_id=absint($_POST['vehicle_id']??0);$round_off=round((float)($_POST['delivery_round_off']??0),2);$remarks=sanitize_textarea_field(wp_unslash($_POST['delivery_remarks']??''));
  $r=$id?$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='orders' AND record_type='order'",$id)):null;
  if(!$r)wp_die('Order not found.');if(!in_array($r->status,['Pending','In Progress'],true))wp_die('Only an order in progress can be updated for delivery.');
  if(!$date||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))wp_die('Delivery Date is required.');if(!$by||!$this->task_user_display_name($by))wp_die('Delivered By is required.');
  $dispatch_raw=$_POST['dispatch_qty']??[];if(!is_array($dispatch_raw))$dispatch_raw=[];
  $lines=$wpdb->get_results($wpdb->prepare("SELECT id,qty,amount,delivered_qty FROM {$this->t('line_items')} WHERE record_id=%d ORDER BY sort_order,id",$id));
  $dispatch=[];$has_dispatch=false;foreach($lines as$l){$lid=(int)$l->id;$qty=(float)$l->qty;$already=(float)$l->delivered_qty;$pending=max(0,$qty-$already);$val=isset($dispatch_raw[$lid])?trim((string)wp_unslash($dispatch_raw[$lid])):'';$dq=$val===''?0:(float)$val;if($dq<0)wp_die('Dispatch Qty cannot be negative.');if($dq>$pending+0.000001)wp_die('Dispatch Qty cannot be greater than pending quantity.');if($dq>0)$has_dispatch=true;$dispatch[$lid]=$dq;}
  if(!$has_dispatch)wp_die('Please enter Dispatch Qty for at least one item.');
  $dispatch_amount=0.0;foreach($lines as$l){$dq=(float)($dispatch[(int)$l->id]??0);if($dq<=0)continue;$dispatch_amount+=(float)$l->qty>0?((float)$l->amount*$dq/(float)$l->qty):0;}$dispatch_total=$dispatch_amount+$round_off;
  $meta=json_decode((string)$r->meta,true);if(!is_array($meta))$meta=[];$meta['delivery_date']=$date;$meta['delivered_by']=$by;$meta['transporter_courier_id']=$transporter_courier_id;$meta['transporter_courier']=$transporter_courier_id?($this->master_name_by_id($transporter_courier_id)?:''):'';$meta['vehicle_id']=$vehicle_id;$meta['vehicle']=$vehicle_id?($this->master_name_by_id($vehicle_id)?:''):'';$meta['delivery_remarks']=$remarks;$meta['delivery_updated_at']=current_time('mysql');
  $history=is_array($meta['delivery_history']??null)?$meta['delivery_history']:[];$dispatch_lines=[];foreach($dispatch as$line_id=>$dispatch_qty){if((float)$dispatch_qty>0)$dispatch_lines[]=['line_id'=>(int)$line_id,'dispatch_qty'=>(float)$dispatch_qty];}$dispatch_no=$this->next_dispatch_ref($date);$history[]=['dispatch_no'=>$dispatch_no,'delivery_date'=>$date,'delivered_by'=>$by,'transporter_courier_id'=>$transporter_courier_id,'transporter_courier'=>$meta['transporter_courier'],'vehicle_id'=>$vehicle_id,'vehicle'=>$meta['vehicle'],'delivery_remarks'=>$remarks,'amount'=>round($dispatch_amount,2),'round_off'=>$round_off,'total_amount'=>round($dispatch_total,2),'updated_at'=>current_time('mysql'),'items'=>$dispatch_lines];$meta['delivery_history']=$history;$meta['last_dispatch_no']=$dispatch_no;
  $wpdb->query('START TRANSACTION');try{
   $all_complete=true;foreach($lines as$l){$lid=(int)$l->id;$qty=(float)$l->qty;$already=(float)$l->delivered_qty;$new_delivered=min($qty,$already+($dispatch[$lid]??0));$line_status=$new_delivered>=$qty-0.000001?'Completed':($new_delivered>0?'In Progress':'Pending');if($line_status!=='Completed')$all_complete=false;$ok=$wpdb->update($this->t('line_items'),['delivered_qty'=>$new_delivered,'status'=>$line_status],['id'=>$lid]);if($ok===false)throw new Exception($wpdb->last_error?:'Unable to update order items.');}
   $order_status=$all_complete?'Delivered':'In Progress';$ok=$wpdb->update($this->t('records'),['status'=>$order_status,'meta'=>wp_json_encode($meta),'updated_at'=>current_time('mysql')],['id'=>$id]);if($ok===false)throw new Exception($wpdb->last_error?:'Unable to update delivery.');
   $this->activity($id,'orders','Delivery Updated',$r->title);$wpdb->query('COMMIT');
  }catch(Throwable $e){$wpdb->query('ROLLBACK');wp_die(esc_html($e->getMessage()));}
  $dest=$all_complete?'delivered-orders':'orders-in-progress';wp_safe_redirect(add_query_arg('notice','saved',$this->url($dest)));exit;
 }

