;if($val>0){$has=true;$new_items[]=['line_id'=>$lid,'dispatch_qty'=>$val];$amount+=(float)$l->qty>0?((float)$l->amount*$val/(float)$l->qty):0;}$new_delivered_by_line[$lid]=$other+$val;}if(!$has)wp_die('Please enter Dispatch Qty for at least one item.');$history[$idx]=array_merge($old,['delivery_date'=>$date,'delivered_by'=>$by,'transporter_courier_id'=>$transporter_courier_id,'transporter_courier'=>$transporter_courier_id?($this->master_name_by_id($transporter_courier_id)?:''):'','vehicle_id'=>$vehicle_id,'vehicle'=>$vehicle_id?($this->master_name_by_id($vehicle_id)?:''):'','delivery_remarks'=>$remarks,'amount'=>round($amount,2),'round_off'=>$round_off,'total_amount'=>round($amount+$round_off,2),'updated_at'=>current_time('mysql'),'items'=>$new_items]);$meta['delivery_history']=$history;$meta['delivery_date']=$date;$meta['delivered_by']=$by;$meta['transporter_courier_id']=$transporter_courier_id;$meta['transporter_courier']=$history[$idx]['transporter_courier'];$meta['vehicle_id']=$vehicle_id;$meta['vehicle']=$history[$idx]['vehicle'];$meta['delivery_remarks']=$remarks;$meta['delivery_updated_at']=current_time('mysql');$wpdb->query('START TRANSACTION');try{$all_complete=true;foreach($lines as$l){$lid=(int)$l->id;$newdel=array_key_exists($lid,$new_delivered_by_line)?$new_delivered_by_line[$lid]:(float)$l->delivered_qty;$status=$newdel>=(float)$l->qty-0.000001?'Completed':($newdel>0?'In Progress':'Pending');if($status!=='Completed')$all_complete=false;$ok=$wpdb->update($this->t('line_items'),['delivered_qty'=>$newdel,'status'=>$status],['id'=>$lid]);if($ok===false)throw new Exception($wpdb->last_error?:'Unable to update delivery items.');}$ok=$wpdb->update($this->t('records'),['status'=>$all_complete?'Delivered':'In Progress','meta'=>wp_json_encode($meta),'updated_at'=>current_time('mysql')],['id'=>$order_id]);if($ok===false)throw new Exception($wpdb->last_error?:'Unable to update delivery.');$this->activity($order_id,'orders','Delivery Edited',$r->title);$wpdb->query