 function format_follow_up_datetime($value){
  $value=trim((string)$value);if($value==='')return'';
  $dt=DateTime::createFromFormat('Y-m-d H:i:s',$value,new DateTimeZone('Asia/Kolkata'));
  if(!$dt)$dt=DateTime::createFromFormat('Y-m-d H:i',$value,new DateTimeZone('Asia/Kolkata'));
  return $dt?$dt->format('d/m/Y H:i'):$value;
 }
