  $ok=$wpdb->update($this->t('records'),['meta'=>wp_json_encode($meta),'updated_at'=>current_time('mysql')],['id'=>$id]);if($ok===false)wp_die('Unable to save Follow Up.');$this->activity($id,$r->module,'Follow Up',$remarks);
