 function order_delivery_items($order_id){
  global $wpdb;$order_id=absint($order_id);if(!$order_id)return[];
  $sql="SELECT l.id,l.description,l.qty,l.delivered_qty,l.uom,l.rate,l.amount,i.title item_title FROM {$this->t('line_items')} l LEFT JOIN {$this->t('records')} i ON i.id=l.item_id WHERE l.record_id=%d ORDER BY l.sort_order,l.id";
  $rows=$wpdb->get_results($wpdb->prepare($sql,$order_id));$out=[];
  foreach($rows as$r){$qty=(float)$r->qty;$del=(float)$r->delivered_qty;$out[]=['id'=>(int)$r->id,'item'=>$r->item_title?:'—','description'=>$r->description?:'—','qty'=>$qty,'delivered_qty'=>$del,'pending_qty'=>max(0,$qty-$del),'uom'=>$r->uom?:'—','rate'=>(float)$r->rate,'unit_amount'=>$qty>0?((float)$r->amount/$qty):(float)$r->rate];}
  return$out;
 }
