d class=\"delivery-readonly-qty\">"+esc(Number(it.pending_qty||0).toLocaleString(undefined,{maximumFractionDigits:3}))+"</td><td>"+esc(it.uom)+"</td><td><input class=\"delivery-qty-input\" type=\"number\" step=\"0.001\" min=\"0\" max=\""+esc(it.pending_qty||0)+"\" name=\"dispatch_qty["+esc(it.id)+"]\" data-unit-amount=\""+esc(it.unit_amount||it.rate||0)+"\" placeholder=\"Enter Qty\"></td></tr>";}).join(""):"<tr><td colspan=\"8\">No pending items found.</td></tr>";syncSelect("transporter_courier_id",opt.dataset.transporter);syncSelect("vehicle_id",opt.dataset.vehicle);calcDeliveryTotals();}form.addEventListener("submit",function(e){clearError();if(!hidden.value){e.preventDefault();showError("Please select an Order.",sel);return;}var has=false;var inputs=form.querySelectorAll(".delivery-qty-input");for(var i=0;i<inputs.length;i++){var input=inputs[i],raw=(input.value||"").trim();if(raw==="")continue;var val=Number(raw),max=Number(input.getAttribute("max")||0);if(!Number.isFinite(val)||val<0){e.preventDefault();showError("Dispatch Qty cannot be negative.",input);return;}if(val>max+0.000001){e.preventDefault();showError("Dispatch Qty cannot be greater than Pending Dispatch Qty ("+max.toLocaleString(undefined,{maximumFractionDigits:3})+").",input);return;}if(val>0)has=true;}if(!has){e.preventDefault();showError("Please enter Dispatch Qty for at least one item.",inputs[0]||null);}});form.addEventListener("input",function(e){if(e.target&&e.target.matches(".delivery-qty-input,[name=delivery_round_off]"))calcDeliveryTotals();});sel.addEventListener("change",load);calcDeliveryTotals();})();</script>';
 }

 function listing($v){
  global $wpdb;
  $module=$this->module($v);$type=$module==='master'?$this->master_type($v):'';$status=$this->filters($v);$where=['1=1'];$args=[];
  $s=sanitize_text_field(wp_unslash($_GET['s']??''));
