  if($module==='master'){
   $where[]="module='master'";$aliases=$this->master_aliases($type);$where[]='record_type IN ('.implode(',',array_fill(0,count($aliases),'%s')).')';$args=array_merge($args,$aliases);
  }else{
   $where[]='module=%s';$args[]=$module;if(!empty($_GET['daily_created'])){$where[]='DATE(created_at)=%s';$args[]=current_time('Y-m-d');}
   if($v==='orders-in-progress')$where[]="status IN ('Pending','In Progress')";elseif($v==='work-orders-in-progress')$where[]="status IN ('Pending','In Progress','Partly Completed')";elseif($v==='po-in-progress'){$where[]="(status IS NULL OR status NOT IN ('Completed','Canceled','Rejected'))";$where[]="EXISTS (SELECT 1 FROM {$this->t('line_items')} pli WHERE pli.record_id={$this->t('records')}.id AND pli.qty > COALESCE((SELECT SUM(gl.received_qty) FROM {$this->t('line_items')} gl JOIN {$this->t('records')} gr ON gr.id=gl.record_id WHERE gr.module='grn' AND gr.record_type='grn' AND gr.parent_id={$this->t('records')}.id AND gl.source_line_id=pli.id AND gr.status<>'Canceled'),0))";}
   elseif($v==='delivered-orders'){$where[]="status<>'Canceled'";$where[]="EXISTS (SELECT 1 FROM {$this->t('line_items')} dl WHERE dl.record_id={$this->t('records')}.id AND dl.delivered_qty>0)";}
