HAR) LIKE %s)))";for($n=0;$n<15;$n++)$args[]=$like;}else{$where[]='(title LIKE %s OR reference_no LIKE %s OR meta LIKE %s OR notes LIKE %s OR DATE_FORMAT(record_date,\'%%d/%%m/%%Y\') LIKE %s OR CAST(amount AS CHAR) LIKE %s)';for($n=0;$n<6;$n++)$args[]=$like;}}
  if($module==='orders'){
   if($customer){$where[]='customer_id=%d';$args[]=$customer;}
   if($date_from && preg_match('/^\d{4}-\d{2}-\d{2}$/',$date_from)){$where[]='record_date>=%s';$args[]=$date_from;}
   if($date_to && preg_match('/^\d{4}-\d{2}-\d{2}$/',$date_to)){$where[]='record_date<=%s';$args[]=$date_to;}
  }elseif($module==='production'){
