  }
  $master_status='';$relation_filters=[];
  $page=max(1,absint($_GET['pg']??1));$per=$this->pagination_size();$off=($page-1)*$per;$base="FROM {$this->t('records')} WHERE ".implode(' AND ',$where);$total=(int)$wpdb->get_var($args?$wpdb->prepare("SELECT COUNT(*) $base",$args):"SELECT COUNT(*) $base");$sql="SELECT * $base ORDER BY updated_at DESC LIMIT $per OFFSET $off";$rows=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql);
  $add=$module==='master'?add_query_arg('add_record',1,$this->url($v)):$this->url(['tasks'=>'add-task','leads'=>'add-lead','recce'=>'add-recce','designs'=>'add-design-job','quotations'=>'add-quotation','orders'=>'add-order','production'=>'add-work-order','deliveries'=>'add-delivery-challan','purchase-orders'=>'add-po','grn'=>'add-grn'][$module]);$add_type=$module==='master'?$type:(['tasks'=>'task','leads'=>'lead','recce'=>'recce','designs'=>'design','quotations'=>'quotation','orders'=>'order','production'=>'job','deliveries'=>'delivery','purchase-orders'=>'purchase-order','grn'=>'grn'][$module]??$this->type($v));$add_label=$this->entity_label($add_type);if(isset($_GET['add_record']))return$this->form('add-'.$type);
  $filter_args=[];foreach(['s','customer','status','date_from','date_to','qtn_no','department','assigned_to','designer','delivery_date_from','delivery_date_to','supplier','vendor','request_by','created_by','expected_from','expected_to'] as$key){if(isset($_GET[$key])&&$_GET[$key]!=='')$filter_args[$key]=sanitize_text_field(wp_unslash($_GET[$key]));}
  $export_url=wp_nonce_url(add_query_arg(array_merge(['action'=>'bsoerp_export','view'=>$v],$filter_args),admin_url('admin-post.php')),'bsoerp_export');
  $order_add_header_views=['orders-in-progress','order-master','canceled-orders'];
  $production_add_header_views=['work-orders-in-progress','work-orders-master','work-order-items-master','completed-work-orders','canceled-work-orders'];
  $show_listing_add=(($module!=='orders') || in_array($v,$order_add_header_views,true)) && !in_array($v,$production_add_header_views,true);
  $listing_head_actions=($module==='master'||in_array($v,$production_add_header_views,true))?'':'<a class="btn mobile-excel" href="'.esc_url($export_url).'">⇩ Excel</a>'.($show_listing_add?'<a class="btn primary" href="'.esc_url($add).'">＋ Add '.esc_html($add_label).'</a>':'');
  echo'<div class="panel listing-panel'.($module==='master'?' master-listing-panel':'').'"><div class="panel-head"><div><h2>'.esc_html($this->flat()[$v]).'</h2></div><div class="head-actions">'.$listing_head_actions.'</div></div>';
  echo'<form class="toolbar master-toolbar" method="get"><label><span>Search</span><input type="search" name="s" value="'.esc_attr($s).'" aria-label="Search" data-auto-search="1"></label>';
