   echo'<label><span>Customer</span><select class="erp-searchable" name="customer"><option value="0">All Customers</option>';foreach($this->master_options('customers')as$o)echo'<option value="'.$o->id.'" '.selected($customer,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select></label>';
   echo'<label><span>Date From</span><input type="date" name="date_from" value="'.esc_attr($date_from).'"></label><label><span>Date To</span><input type="date" name="date_to" value="'.esc_attr($date_to).'"></label>';
  }elseif($module==='production'){
   echo'<label><span>Vendor</span><select class="erp-searchable" name="vendor"><option value="0">All Vendors</option>';foreach($this->master_options('vendors')as$o)echo'<option value="'.$o->id.'" '.selected($vendor,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select></label>';
   echo'<label><span>Date From</span><input type="date" name="date_from" value="'.esc_attr($date_from).'"></label><label><span>Date To</span><input type="date" name="date_to" value="'.esc_attr($date_to).'"></label>';
   if(!in_array($v,['canceled-work-orders','job-worked','job-worked-items'],true))echo'<label><span>Target Date From</span><input type="date" name="delivery_date_from" value="'.esc_attr($delivery_date_from).'"></label><label><span>Target Date To</span><input type="date" name="delivery_date_to" value="'.esc_attr($delivery_date_to).'"></label>';
  }elseif($module==='purchase-orders'){
