  $this->table($rows,$module==='master',$type,$v);if(in_array($v,['orders-in-progress','order-master'],true))$this->order_delivery_modal();if($v==='work-orders-in-progress')$this->job_update_modal();if(in_array($v,['orders-in-progress','work-orders-in-progress'],true))$this->follow_up_modal();$this->pagination_controls($total,$page,$per,add_query_arg($filter_args,$this->url($v)));echo'</div>';
 }
 function table($rows,$master=false,$master_type='',$view=''){
  global $wpdb;
  if(!isset($wpdb) || !is_object($wpdb)){ $wpdb=$GLOBALS['wpdb']??null; }
  if(!$wpdb){ echo '<div class="empty"><strong>Database connection unavailable.</strong></div>'; return; }
  if(!$rows){echo'<div class="empty"><strong>No records found</strong><span>Add a record to begin.</span></div>';return;}
  if($master){
   $cols=$this->master_columns($master_type);echo'<div class="table-wrap"><table class="data master-table"><thead><tr><th>Sl.</th>';foreach($cols as$c)echo'<th>'.esc_html($c[1]).'</th>';echo'<th>Action</th></tr></thead><tbody>';
   foreach($rows as$i=>$r){$rowattrs=$master_type==='user'?' class="user-row-clickable" data-url="'.esc_url(add_query_arg('view_user',(int)$r->id,$this->url('users'))).'" style="cursor:pointer"':'';echo'<tr'.$rowattrs.'><td>'.($i+1).'</td>';foreach($cols as$c){$val=$this->master_cell($r,$c[0]);if($c[0]==='name')echo'<td><strong>'.esc_html($val).'</strong></td>';elseif($c[0]==='status')echo'<td><span class="status '.sanitize_html_class(strtolower(str_replace(' ','-',$val))).'">'.esc_html($val).'</span></td>';elseif($c[0]==='signature'){echo'<td class="signature-cell">';if($val!=='—')echo'<img src="'.esc_url($val).'" alt="Signature" class="signature-thumb">';else echo'—';echo'</td>';}else echo'<td>'.esc_html($val).'</td>';}echo'<td class="actions"><a title="Edit" href="'.esc_url(add_query_arg('edit',$r->id)).'">✎</a>';if(current_user_can('bsoerp_manage'))echo'<a title="Delete" class="delete" href="'.esc_url(wp_nonce_url(admin_url('admin-post.php?action=bsoerp_delete&id='.$r->id),'bsoerp_del_'.$r->id)).'">⌫</a>';echo'</td></tr>';}
   echo'</tbody></table></div>';if($master_type==='user')echo'<script>(function(){document.querySelectorAll("tr.user-row-clickable").forEach(function(r){r.addEventListener("click",function(e){if(e.target.closest("a,button,input,select"))return;var u=r.getAttribute("data-url");if(u)window.location.href=u;});});})();</script>';return;
  }
  $is_task=($rows[0]->module??'')==='tasks';$is_order=($rows[0]->module??'')==='orders';$is_job=($rows[0]->module??'')==='production'&&($rows[0]->record_type??'')==='job';$is_po=($rows[0]->module??'')==='purchase-orders'&&($rows[0]->record_type??'')==='purchase-order';
  $expand_order=in_array($view,['orders-in-progress','order-master','canceled-orders','delivered-orders'],true);
  $show_dispatch=in_array($view,['orders-in-progress','order-master','delivered-orders'],true);
  $show_order_qty=in_array($view,['orders-in-progress','order-master','canceled-orders'],true);
  $order_colspan=$view==='delivered-orders'?8:($show_dispatch?($view==='orders-in-progress'?14:11):($show_order_qty?9:7));
  echo'<div class="table-wrap"><table class="data'.($expand_order?' order-expand-table':'').'"><thead><tr><th>Sl.</th>';
  if($is_task)echo'<th>Date</th><th>Task</th><th>Notes</th><th>Assigned By</th><th>Assigned To</th><th>Due Date</th><th>Time</th><th>Status</th>';
  elseif($is_order){echo'<th>Order No.</th>';if(in_array($view,['orders-in-progress','order-master'],true))echo'<th>Quotation No.</th>';echo'<th>Customer Name</th><th>Date</th>';if($view!=='delivered-orders')echo'<th>Status</th>';if($show_order_qty)echo'<th>Order Qty</th>';if($show_dispatch){echo'<th>Dispatch Qty</th>';if($view!=='delivered-orders')echo'<th>Pending Dispatch</th>';}if($view==='orders-in-progress')echo'<th>Last Follow Up</th><th>Follow Up Remarks</th><th>Next Follow Up Date</th>';echo'<th>Amount</th>';}
  elseif($is_job&&in_array($view,['work-orders-in-progress','work-orders-master','completed-work-orders','canceled-work-orders'],true)){echo'<th>Work Order No.</th><th>Date</th><th>Vendor</th><th>Target Date</th><th>Total Nos.</th><th>Total Amount</th><th>Status</th>';if($view==='work-orders-in-progress')echo'<th>Last Follow Up</th><th>Follow Up Remarks</th><th>Next Follow Up Date</th>';}
  elseif($is_po){echo'<th>PO No.</th><th>Date</th><th>Vendor</th><th>Expected Delivery</th><th>Request By</th><th>Department</th><th>Created By</th>';if($view!=='po-in-progress')echo'<th>Total Qty</th><th>GRN Qty</th>';echo'<th>Total Amount</th>';}
  else echo'<th>Reference</th><th>Name / Title</th><th>Date</th><th>Status</th><th>Approval</th><th>Amount</th>';
