 function work_order_job_items($work_order_id){
  global $wpdb;$rows=$wpdb->get_results($wpdb->prepare("SELECT l.*,i.title item_title FROM {$this->t('line_items')} l LEFT JOIN {$this->t('records')} i ON i.id=l.item_id WHERE l.record_id=%d ORDER BY l.sort_order,l.id",$work_order_id));$out=[];
  foreach($rows as$r){$m=json_decode((string)$r->meta,true);if(!is_array($m))$m=[];$nos=max(0,(float)($m['nos']??0));$completed=(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(completed_qty),0) FROM {$this->t('job_update_items')} WHERE line_item_id=%d",$r->id));$pending=max(0,$nos-$completed);$out[]=['id'=>(int)$r->id,'item'=>$r->item_title?:'—','description'=>$r->description?:'','nos'=>$nos,'completed'=>$completed,'pending'=>$pending];}
  return$out;
 }
 function job_update_modal(){
