function esc(v){return String(v).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;"}[c];});}
function num(v){var n=Number(v||0);return n.toLocaleString(undefined,{maximumFractionDigits:3});}
document.querySelectorAll(".job-update-open").forEach(function(btn){btn.addEventListener("click",function(e){e.preventDefault();e.stopPropagation();var items=[];try{items=JSON.parse(btn.getAttribute("data-items")||"[]");}catch(x){}form.querySelector("[name=work_order_id]").value=btn.getAttribute("data-work-order-id")||"";title.innerHTML="<strong>"+esc(btn.getAttribute("data-work-order-title")||"Work Order")+"</strong>";items=items.filter(function(it){return Number(it.pending||0)>0;});var html="<div class=\"table-wrap\"><table class=\"data job-update-table\"><thead><tr><th>Sl.</th><th>Particular</th><th>Description</th><th>Nos</th><th>Already Completed</th><th>Pending</th><th>Update Completed Job</th></tr></thead><tbody>";items.forEach(function(it,idx){html+="<tr><td>"+(idx+1)+"</td><td>"+esc(it.item||"—")+"</td><td>"+esc(it.description||"—")+"</td><td>"+num(it.nos)+"</td><td>"+num(it.completed)+"</td><td>"+num(it.pending)+"</td><td><input type=\"number\" min=\"0\" max=\""+Number(it.pending||0)+"\" step=\"0.001\" name=\"completed["+Number(it.id)+"]\" value=\"\" placeholder=\"0\"></td></tr>";});html+="</tbody></table></div>";itemsWrap.innerHTML=html;modal.hidden=false;modal.classList.add("is-open");modal.setAttribute("aria-hidden","false");});});
modal.querySelector(".job-update-close").addEventListener("click",close);modal.querySelector(".job-update-cancel").addEventListener("click",close);modal.addEventListener("click",function(e){if(e.target===modal)close();});
})();</script>
JS;
