 function save_job_update(){
  if(!is_user_logged_in()||!current_user_can('bsoerp_access')||!wp_verify_nonce($_POST['nonce']??'',self::NONCE))wp_die('Invalid request');
  global $wpdb;$work_order_id=absint($_POST['work_order_id']??0);$updated_by=absint($_POST['updated_by_user']??0);$remarks=sanitize_textarea_field(wp_unslash($_POST['update_remarks']??''));
  $work=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='production' AND record_type='job'",$work_order_id));
  if(!$work)wp_die('Work Order not found.');if(!$updated_by||!$this->task_user_display_name($updated_by))wp_die('Update By is required.');if(trim($remarks)==='')wp_die('Update Remarks is required.');
  $current=$this->work_order_job_items($work_order_id);$map=[];foreach($current as$it)$map[(int)$it['id']]=$it;$posted=(array)($_POST['completed']??[]);$valid=[];$total=0.0;
  foreach($posted as$line_id=>$raw){$line_id=absint($line_id);$qty=max(0,(float)$raw);if($qty<=0)continue;if(!isset($map[$line_id]))wp_die('Invalid Job row.');$pending=(float)$map[$line_id]['pending'];if($qty>$pending+0.000001)wp_die('Update Completed Job cannot be greater than Pending Job for '.$map[$line_id]['item'].'.');$valid[$line_id]=$qty;$total+=$qty;}
  if(!$valid)wp_die('Enter Update Completed Job for at least one Job row.');$now=current_time('mysql');
  $ok=$wpdb->insert($this->t('job_updates'),['work_order_id'=>$work_order_id,'updated_by_user'=>$updated_by,'remarks'=>$remarks,'completed_total'=>$total,'created_by'=>get_current_user_id(),'created_at'=>$now]);if(!$ok)wp_die('Unable to save Job update.');$update_id=(int)$wpdb->insert_id;
  foreach($valid as$line_id=>$qty){$wpdb->insert($this->t('job_update_items'),['job_update_id'=>$update_id,'work_order_id'=>$work_order_id,'line_item_id'=>$line_id,'completed_qty'=>$qty,'created_at'=>$now]);$after=(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(completed_qty),0) FROM {$this->t('job_update_items')} WHERE line_item_id=%d",$line_id));$nos=(float)$map[$line_id]['nos'];$ls=$after<=0?'Pending':($after+0.000001>=$nos?'Completed':'In Progress');$wpdb->update($this->t('line_items'),['produced_qty'=>$after,'status'=>$ls],['id'=>$line_id]);}
  $all=$this->work_order_job_items($work_order_id);$pending_total=0.0;$completed_total=0.0;foreach($all as$it){$pending_total+=(float)$it['pending'];$completed_total+=(float)$it['completed'];}$status=$pending_total<=0.000001?'Completed':($completed_total>0?'In Progress':'Pending');$wpdb->update($this->t('records'),['status'=>$status,'updated_at'=>$now],['id'=>$work_order_id]);$this->activity($work_order_id,'production','Job Updated',$remarks);$dest=$status==='Completed'?'work-orders-master':'work-orders-in-progress';wp_safe_redirect(add_query_arg('notice','saved',$this->url($dest)));exit;
 }
