 function pending_order_items_listing(){
  global $wpdb;
  $s=sanitize_text_field(wp_unslash($_GET['s']??''));$customer=absint($_GET['customer']??0);$item=absint($_GET['item']??0);$category=absint($_GET['category']??0);$order_no=sanitize_text_field(wp_unslash($_GET['order_no']??''));
  $where=["r.module='orders'","r.record_type='order'","r.status<>'Canceled'"];$args=[];
  if($s){$like='%'.$wpdb->esc_like($s).'%';$where[]='(r.reference_no LIKE %s OR c.title LIKE %s OR i.title LIKE %s OR cat.title LIKE %s OR l.description LIKE %s)';array_push($args,$like,$like,$like,$like,$like);}
  if($order_no){$where[]='r.reference_no LIKE %s';$args[]='%'.$wpdb->esc_like($order_no).'%';}
  if($customer){$where[]='r.customer_id=%d';$args[]=$customer;}if($item){$where[]='l.item_id=%d';$args[]=$item;}if($category){$where[]="CAST(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(i.meta,'$.category_id')),'0') AS UNSIGNED)=%d";$args[]=$category;}
  $base=" FROM {$this->t('line_items')} l JOIN {$this->t('records')} r ON r.id=l.record_id LEFT JOIN {$this->t('records')} c ON c.id=r.customer_id LEFT JOIN {$this->t('records')} i ON i.id=l.item_id LEFT JOIN {$this->t('records')} cat ON cat.id=CAST(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(i.meta,'$.category_id')),'0') AS UNSIGNED) AND cat.module='master' AND cat.record_type IN ('item-category','item-categories') WHERE ".implode(' AND ',$where);
  $sql="SELECT l.*,r.reference_no,r.record_date,r.customer_id,r.status parent_status,c.title customer_name,i.title item_title,cat.title category_name,(SELECT COALESCE(SUM(wl.qty),0) FROM {$this->t('line_items')} wl JOIN {$this->t('records')} wr ON wr.id=wl.record_id WHERE wl.source_line_id=l.id AND wr.module='production' AND wr.status<>'Canceled') processed_qty $base HAVING (l.qty-processed_qty)>0.0001 ORDER BY r.id DESC,l.sort_order,l.id";
  $rows=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql);
  echo'<div class="panel listing-panel"><div class="panel-head"><div><h2>Pending Order Items</h2></div></div><form class="toolbar master-toolbar" method="get"><label><span>Search</span><input type="search" name="s" value="'.esc_attr($s).'" placeholder="Search"></label><label><span>Order No.</span><input type="search" name="order_no" value="'.esc_attr($order_no).'"></label><label><span>Customer</span><select class="erp-searchable" name="customer"><option value="0">All Customers</option>';foreach($this->master_options('customers')as$o)echo'<option value="'.$o->id.'" '.selected($customer,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select></label><label><span>Item</span><select class="erp-searchable" name="item"><option value="0">All Items</option>';foreach($this->master_options('items')as$o)echo'<option value="'.$o->id.'" '.selected($item,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select></label><label><span>Category</span><select class="erp-searchable" name="category"><option value="0">All Categories</option>';foreach($this->master_options('item-categories')as$o)echo'<option value="'.$o->id.'" '.selected($category,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select></label><button class="btn" type="submit">Filter</button><a class="btn filter-clear" href="'.esc_url($this->url('pending-order-items')).'">Clear</a></form>';
  if(!$rows){echo'<div class="empty"><strong>No pending order items</strong><span>All Order items have been fully processed into Work Orders.</span></div></div>';return;}
  echo'<div class="table-wrap"><table class="data"><thead><tr><th>Sl.</th><th>Order No.</th><th>Order Date</th><th>Customer</th><th>Items</th><th>Category</th><th>Description</th><th>Ordered Qty</th><th>Processed Qty</th><th>Pending Qty</th><th>UOM</th><th>Status</th></tr></thead><tbody>';
  foreach($rows as$i=>$r){$pending=max(0,(float)$r->qty-(float)$r->processed_qty);echo'<tr><td>'.($i+1).'</td><td><strong>'.esc_html($r->reference_no?:'—').'</strong></td><td>'.esc_html($r->record_date?date_i18n('d/m/Y',strtotime($r->record_date)):'—').'</td><td>'.esc_html($r->customer_name?:'—').'</td><td>'.esc_html($r->item_title?:'—').'</td><td>'.esc_html($r->category_name?:'—').'</td><td>'.esc_html($r->description?:'—').'</td><td>'.esc_html(number_format_i18n((float)$r->qty,2)).'</td><td>'.esc_html(number_format_i18n((float)$r->processed_qty,2)).'</td><td><strong>'.esc_html(number_format_i18n($pending,2)).'</strong></td><td>'.esc_html($r->uom?:'—').'</td><td><span class="status">Pending</span></td></tr>';}
  echo'</tbody></table></div></div>';
 }
 function line_items_listing($v){
  global$wpdb;$map=['quotation-items-master'=>'quotations','order-items-master'=>'orders','work-order-items-master'=>'production','purchase-order-items'=>'purchase-orders','grn-master'=>'grn','grn-items'=>'grn'];$module=$map[$v]??'';
  if(in_array($v,['grn-master','grn-items'],true)){
   $s=sanitize_text_field(wp_unslash($_GET['s']??''));$grn_date_from=sanitize_text_field(wp_unslash($_GET['date_from']??''));$grn_date_to=sanitize_text_field(wp_unslash($_GET['date_to']??''));$po_id=absint($_GET['purchase_order']??0);$grn_supplier=absint($_GET['supplier']??0);$receive_by=absint($_GET['receive_by']??0);$invoice_from=sanitize_text_field(wp_unslash($_GET['invoice_from']??''));$invoice_to=sanitize_text_field(wp_unslash($_GET['invoice_to']??''));$where=["r.module='grn'","r.record_type='grn'"];$args=[];$like=$s?'%'.$wpdb->esc_like($s).'%':'';
   $common_search="r.reference_no LIKE %s OR DATE_FORMAT(r.record_date,'%%d/%%m/%%Y') LIKE %s OR po.reference_no LIKE %s OR sup.title LIKE %s OR r.meta LIKE %s OR r.notes LIKE %s OR EXISTS (SELECT 1 FROM {$wpdb->users} ru WHERE ru.ID=CAST(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(r.meta,'$.received_by')),'0') AS UNSIGNED) AND ru.display_name LIKE %s)";
