  }

  if($r->record_type==='grn'){
   $tmp_files=[];$logo_file=$this->quotation_attachment_jpeg(absint($settings['logo_id']??0),$tmp_files,'logo');$pdf=$this->grn_pdf_content($r,$lines,$settings,$party,$logo_file);foreach(array_unique($tmp_files)as$tf)if($tf&&is_file($tf))@unlink($tf);$filename='grn-'.sanitize_file_name($r->reference_no?:$r->id).'.pdf';
   nocache_headers();header('Content-Type: application/pdf');header('Content-Disposition: '.$pdf_disposition.'; filename="'.$filename.'"');header('Content-Length: '.strlen($pdf));echo$pdf;exit;
  }

  echo'<!doctype html><html><head><meta charset="utf-8"><title>'.esc_html($label.' '.$r->reference_no).'</title><style>body{font-family:Arial;margin:35px;color:#111}.top{display:flex;justify-content:space-between;border-bottom:2px solid #111;padding-bottom:15px}.muted{color:#666}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{border:1px solid #333;padding:8px;text-align:left}th{background:#eee}.tot{text-align:right;font-weight:bold}.sign{display:flex;justify-content:space-between;margin-top:70px}.no-print{margin-bottom:15px}@media print{.no-print{display:none}}</style></head><body><button class="no-print" onclick="window.print()">Print / Save PDF</button><div class="top"><div><h1>'.esc_html($settings['company']).'</h1><div class="muted">'.esc_html($label).'</div></div><div><b>'.esc_html($r->reference_no).'</b><br>Date: '.esc_html($r->record_date?date_i18n('d/m/Y',strtotime($r->record_date)):'—').'<br>Status: '.esc_html($r->status).'</div></div><h3>'.esc_html($r->title).'</h3><p><b>Customer / Vendor:</b> '.esc_html($party?:'—').'</p><table><thead><tr><th>Sl.</th><th>Item</th><th>Description</th><th>Qty</th><th>UOM</th><th>Rate</th><th>Amount</th></tr></thead><tbody>';
  $total=0;foreach($lines as$i=>$l){$total+=$l->amount;echo'<tr><td>'.($i+1).'</td><td>'.esc_html($l->item_title?:'—').'</td><td>'.esc_html($l->description).'</td><td>'.esc_html($l->qty).'</td><td>'.esc_html($l->uom).'</td><td>'.esc_html(number_format_i18n($l->rate,2)).'</td><td>'.esc_html(number_format_i18n($l->amount,2)).'</td></tr>';}
  echo'<tr><td colspan="6" class="tot">Total</td><td><b>'.esc_html(number_format_i18n($total,2)).'</b></td></tr></tbody></table><p><b>Terms / Remarks:</b><br>'.nl2br(esc_html($r->notes)).'</p><div class="sign"><span>Prepared By</span><span>Authorized Signatory</span></div></body></html>';exit;
 }

 function cancel_quotation(){if(!current_user_can('bsoerp_manage'))wp_die('You do not have permission to manage Quotations.');$id=absint($_GET['id']??0);if(!$id||!wp_verify_nonce($_GET['_wpnonce']??'','bsoerp_cancel_quotation_'.$id))wp_die('Invalid request');global$wpdb;$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='quotations' AND record_type='quotation'",$id));if(!$r)wp_die('Quotation not found.');if($r->status!=='Canceled'){$wpdb->update($this->t('records'),['status'=>'Canceled','updated_at'=>current_time('mysql')],['id'=>$id]);$wpdb->update($this->t('line_items'),['status'=>'Canceled'],['record_id'=>$id]);$this->activity($id,$r->module,'Canceled',$r->reference_no?:$r->title);}wp_safe_redirect(add_query_arg('notice','quotation_canceled',$this->url('quotation-master')));exit;}

 function cancel_purchase_order(){if(!current_user_can('bsoerp_manage'))wp_die('You do not have permission to manage Purchase Orders.');$id=absint($_GET['id']??0);if(!$id||!wp_verify_nonce($_GET['_wpnonce']??'','bsoerp_cancel_po_'.$id))wp_die('Invalid request');global$wpdb;$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='purchase-orders' AND record_type='purchase-order'",$id));if(!$r)wp_die('Purchase Order not found.');$grn_qty=(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(gl.received_qty),0) FROM {$this->t('line_items')} gl JOIN {$this->t('records')} gr ON gr.id=gl.record_id WHERE gr.module='grn' AND gr.record_type='grn' AND gr.parent_id=%d AND gr.status<>'Canceled'",$id));if($grn_qty>0)wp_die('This Purchase Order cannot be canceled because GRN quantity already exists.');if($r->status!=='Canceled'){$wpdb->update($this->t('records'),['status'=>'Canceled','updated_at'=>current_time('mysql')],['id'=>$id]);$wpdb->update($this->t('line_items'),['status'=>'Canceled'],['record_id'=>$id]);$this->activity($id,$r->module,'Canceled',$r->reference_no?:$r->title);}wp_safe_redirect(add_query_arg('notice','po_canceled',$this->url('canceled-po')));exit;}

 function delete(){if(!current_user_can('bsoerp_manage'))wp_die('You do not have permission to manage ERP records.');$id=absint($_GET['id']??0);if(!$id||!wp_verify_nonce($_GET['_wpnonce']??'','bsoerp_del_'.$id))wp_die('Invalid request');global$wpdb;$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d",$id));if($r&&$r->module==='leads'){$wpdb->query('START TRANSACTION');try{$wpdb->delete($this->t('lead_updates'),['lead_id'=>$id]);$wpdb->delete($this->t('line_items'),['record_id'=>$id]);$wpdb->delete($this->t('activity'),['record_id'=>$id,'module'=>'leads']);$ok=$wpdb->delete($this->t('records'),['id'=>$id]);if($ok===false)throw new Exception($wpdb->last_error?:'Unable to delete Enquiry.');$wpdb->query('COMMIT');}catch(Throwable$e){$wpdb->query('ROLLBACK');wp_die('Delete failed: '.esc_html($e->getMessage()));}wp_safe_redirect(add_query_arg('notice','deleted',$this->url('leads-master')));exit;}if($r&&$r->module==='orders'&&$r->record_type==='order'){$dispatch_qty=(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(delivered_qty),0) FROM {$this->t('line_items')} WHERE record_id=%d",$id));if($r->status==='Canceled'){wp_safe_redirect(add_query_arg('notice','canceled',$this->url('canceled-orders')));exit;}if($dispatch_qty>0)wp_die('This Order cannot be canceled because dispatch quantity already exists.');$wpdb->update($this->t('records'),['status'=>'Canceled','updated_at'=>current_time('mysql')],['id'=>$id]);$this->activity($id,$r->module,'Canceled',$r->title);wp_safe_redirect(add_query_arg('notice','canceled',$this->url('canceled-orders')));exit;}if($r&&$r->module==='production'&&$r->record_type==='job'){$completed=(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(jui.completed_qty),0) FROM {$this->t('job_update_items')} jui INNER JOIN {$this->t('line_items')} li ON li.id=jui.line_item_id WHERE li.record_id=%d",$id));if($r->status==='Canceled'){wp_safe_redirect(add_query_arg('notice','work_order_canceled',$this->url('work-orders-master')));exit;}if($completed>0)wp_die('This Work Order cannot be canceled because Completed Nos already exists.');$wpdb->update($this->t('records'),['status'=>'Canceled','updated_at'=>current_time('mysql')],['id'=>$id]);$wpdb->update($this->t('line_items'),['status'=>'Canceled'],['record_id'=>$id]);$this->activity($id,$r->module,'Canceled',$r->reference_no?:$r->title);wp_safe_redirect(add_query_arg('notice','work_order_canceled',$this->url('work-orders-master')));exit;}if($r){$wpdb->delete($this->t('line_items'),['record_id'=>$id]);if($r->record_type==='task')$wpdb->delete($this->t('task_updates'),['task_id'=>$id]);if($r->module==='recce')$wpdb->delete($this->t('recce_updates'),['recce_id'=>$id]);if($r->module==='designs')$wpdb->delete($this->t('design_updates'),['design_id'=>$id]);$wpdb->delete($this->t('records'),['id'=>$id]);$this->activity($id,$r->module,'Deleted',$r->title);}wp_safe_redirect(add_query_arg('notice','deleted',wp_get_referer()?:$this->url('dashboard')));exit;}

 function lead_export_rows($v){
  global$wpdb;$this->ensure_lead_schema();$headers=[];$rows=[];
  if($v==='lead-update-log'){
   $s=sanitize_text_field(wp_unslash($_GET['s']??''));$customer=absint($_GET['customer']??0);$source=absint($_GET['lead_source']??0);$owner=absint($_GET['lead_owner']??0);$assigned=absint($_GET['assigned_to']??0);$status=sanitize_text_field(wp_unslash($_GET['status']??''));$updated_by=absint($_GET['updated_by']??0);$from=sanitize_text_field($_GET['date_from']??'');$to=sanitize_text_field($_GET['date_to']??'');$lead_id=absint($_GET['lead_id']??0);
   $where=['1=1'];$args=[];if($lead_id){$where[]='u.lead_id=%d';$args[]=$lead_id;}if($s){$like='%'.$wpdb->esc_like($s).'%';$where[]='(r.title LIKE %s OR u.update_text LIKE %s)';array_push($args,$like,$like);}if($customer){$where[]='r.customer_id=%d';$args[]=$customer;}if($source){$where[]='r.lead_source_id=%d';$args[]=$source;}if($owner){$where[]='u.lead_owner=%d';$args[]=$owner;}if($assigned){$where[]='u.assigned_to=%d';$args[]=$assigned;}if(in_array($status,['In Progress','Completed','Canceled'],true)){$where[]='u.status=%s';$args[]=$status;}if($updated_by){$where[]='u.updated_by_user=%d';$args[]=$updated_by;}if($from){$where[]='DATE(u.created_at)>=%s';$args[]=$from;}if($to){$where[]='DATE(u.created_at)<=%s';$args[]=$to;}
   $sql="SELECT u.*,r.title,r.customer_id,r.lead_source_id FROM {$this->t('lead_updates')} u JOIN {$this->t('records')} r ON r.id=u.lead_id WHERE ".implode(' AND ',$where).' ORDER BY u.created_at DESC,u.id DESC';$data=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql);
   $headers=['Description','Customer','Source','Assigned By','Assigned To','Update','Status','Next Follow-up','Updated By','Date & Time'];
   foreach($data as$r)$rows[]=[$r->title,$this->master_name_by_id($r->customer_id),$this->master_name_by_id($r->lead_source_id),$this->task_user_display_name($r->lead_owner),$this->task_user_display_name($r->assigned_to),$r->update_text,$this->lead_status_display($r->status),$r->next_follow_up,($r->updated_by_user?$this->task_user_display_name($r->updated_by_user):$this->user_display_name($r->created_by)),$this->format_utc_to_ist($r->created_at,'d/m/Y h:i A')];
  }else{
   $f=$this->lead_filter_state($v);[$where,$args]=$this->lead_query_parts($v,$f);$sql="SELECT * FROM {$this->t('records')} WHERE ".implode(' AND ',$where).' ORDER BY updated_at DESC';$data=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql);
   $headers=['Enquiry No.','Date','Description','Customer','Contact Person','Mobile','Source','Assigned By','Assigned To','Status','Remarks'];
   foreach($data as$r){$last_update_text=$wpdb->get_var($wpdb->prepare("SELECT update_text FROM {$this->t('lead_updates')} WHERE lead_id=%d ORDER BY id DESC LIMIT 1",$r->id));$lm=json_decode((string)$r->meta,true);if(!is_array($lm))$lm=[];$remarks=trim((string)$last_update_text)!==''?$last_update_text:$r->notes;$rows[]=[$r->reference_no,$r->record_date,$r->title,$this->master_name_by_id($r->customer_id),$lm['contact_person']??'',$lm['mobile']??'',$this->master_name_by_id($r->lead_source_id),$this->task_user_display_name($r->lead_owner),$this->task_user_display_name($r->assigned_to),$this->lead_status_display($r->status),$remarks?:'—'];}
  }
  return[$headers,$rows];
 }

 function export(){if(!current_user_can('bsoerp_access'))wp_die('Access denied');if(!wp_verify_nonce($_GET['_wpnonce']??'','bsoerp_export'))wp_die('Invalid request');$v=sanitize_key($_GET['view']??'');global$wpdb;if(in_array($v,['leads-in-progress','leads-master','lead-update-log'],true)){[$headers,$rows]=$this->lead_export_rows($v);}elseif($v==='task-update-log'){$task_rows=$wpdb->get_results("SELECT u.*,r.title task_title,r.customer_id,r.task_owner,r.assigned_to,COALESCE(w.display_name,'Unknown user') user_name FROM {$this->t('task_updates')} u JOIN {$this->t('records')} r ON r.id=u.task_id LEFT JOIN {$wpdb->users} w ON w.ID=u.created_by ORDER BY u.created_at DESC,u.id DESC");$headers=['Task','Customer','Assigned By','Assigned To','Update','Status','Updated By','Date & Time'];$rows=[];foreach($task_rows as$r)$rows[]=[$r->task_title,$this->master_name_by_id($r->customer_id),$this->task_user_display_name($r->task_owner),$this->task_user_display_name($r->assigned_to),$r->update_text,$r->status,$r->user_name,$this->format_utc_to_ist($r->created_at,'d/m/Y h:i A')];}elseif($v==='designs-pending-approval'){$this->ensure_design_schema();$data=$wpdb->get_results("SELECT u.*,r.customer_id,r.assigned_to,r.title,r.reference_no FROM {$this->t('design_updates')} u JOIN {$this->t('records')} r ON r.id=u.design_id WHERE r.module='designs' AND r.status<>'Canceled' AND r.meta LIKE '%\"approval_required\":\"1\"%' AND u.completed_qty>0 AND COALESCE(u.approved_qty,0)<u.completed_qty ORDER BY u.created_at ASC,u.id ASC");$headers=['Date & Time','Design No.','Customer Name','Designer','No of Design','Design Completed','Design Pending','Approved Design','Pending Approval','Cancel'];$rows=[];foreach($data as$r)$rows[]=[$this->format_utc_to_ist($r->created_at,'d/m/Y h:i A'),$r->reference_no,$this->master_name_by_id($r->customer_id),$this->task_user_display_name($r->assigned_to),(int)$r->assigned_qty,(int)$r->completed_qty,(int)$r->pending_qty,(int)$r->approved_qty,max(0,(int)$r->completed_q