 }
 function recce_details_modal(){echo'<div class="lead-update-modal recce-details-modal" id="recce-details-modal" aria-hidden="true"><div class="lead-update-modal-backdrop" data-recce-details-close></div><div class="lead-update-modal-card recce-details-modal-card" role="dialog" aria-modal="true" aria-labelledby="recce-details-modal-heading"><button type="button" class="lead-update-modal-close" data-recce-details-close aria-label="Close">×</button><div class="panel-head recce-details-head"><div><h2 id="recce-details-modal-heading">Recce Action Details</h2><small class="recce-details-modal-title"></small></div><div class="head-actions"><a class="btn recce-details-pdf-link" href="#" target="_blank" rel="noopener">⇩ PDF</a></div></div><div class="recce-details-modal-body"></div></div></div>'; }
 function recce_details_pdf(){if(!current_user_can('bsoerp_access'))wp_die('Access denied');$id=absint($_GET['recce_id']??0);if(!$id||!wp_verify_nonce($_GET['_wpnonce']??'','bsoerp_recce_details_pdf_'.$id))wp_die('Invalid request');global$wpdb;$this->ensure_recce_schema();$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='recce'",$id));if(!$r)wp_die('Recce not found.');$updates=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$this->t('recce_updates')} WHERE recce_id=%d ORDER BY created_at ASC,id ASC",$id));$name=$this->master_name_by_id($r->customer_id)?:$r->title;$total=(int)$this->recce_meta_value($r,'no_of_recce',0);nocache_headers();header('Content-Type:text/html; charset=utf-8');echo'<!doctype html><html><head><meta charset="utf-8"><title>Recce Action Details</title><style>@page{size:A5 landscape;margin:8mm}body{font-family:Arial,sans-serif;color:#111;font-size:11px}h1{font-size:18px;margin:0 0 5px}.meta{margin:0 0 14px;color:#444}.actions{display:flex;justify-content:flex-end;margin-bottom:12px}button{padding:8px 12px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #777;padding:6px;vertical-align:top;text-align:left}th{background:#eee}@media print{.actions{display:none}}</style></head><body><div class="actions"><button onclick="window.print()">Download / Save PDF</button></div><h1>Recce Action Details</h1><div class="meta"><strong>'.esc_html($name).'</strong> | No of Recce: '.esc_html((string)$total).'</div><table><thead><tr><th>Sl.</th><th>Completed</th><th>Denied</th><th>Cancel</th><th>Pending Recce</th><th>Remarks</th><th>Update By</th><th>Date & Time</th></tr></thead><tbody>';if($updates){foreach($updates as$i=>$u){echo'<tr><td>'.($i+1).'</td><td>'.(int)$u->completed_recce.'</td><td>'.(int)$u->denied_recce.'</td><td>'.(int)$u->canceled_recce.'</td><td>'.(int)$u->pending_recce.'</td><td>'.nl2br(esc_html($u->remarks?:'—')).'</td><td>'.esc_html($this->task_user_display_name($u->updated_by_user)?:'—').'</td><td>'.esc_html($this->format_utc_to_ist($u->created_at,'d/m/Y h:i A')).'</td></tr>';}}else echo'<tr><td colspan="8">No Recce Worked data</td></tr>';echo'</tbody></table></body></html>';exit;}
 function recce_document_link($id){$id=absint($id);if(!$id)return'—';$url=wp_get_attachment_url($id);if(!$url)return'—';return'<a class="btn mobile-excel" target="_blank" rel="noopener" href="'.esc_url($url).'">Document</a>';} function recce_update_modal(){echo'<div class="lead-update-modal recce-update-modal" id="recce-update-modal" aria-hidden="true"><div class="lead-update-modal-backdrop" data-recce-update-close></div><div class="lead-update-modal-card" role="dialog" aria-modal="true" aria-labelledby="recce-update-modal-title"><button type="button" class="lead-update-modal-close" data-recce-update-close aria-label="Close">×</button><div class="panel-head"><div><h2 id="recce-update-modal-title">Update Recce</h2><small class="recce-update-modal-title"></small></div></div><form class="erp-form recce-update-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field(self::NONCE,'nonce');echo'<input type="hidden" name="action" value="bsoerp_save_recce_update"><input type="hidden" name="recce_id" value=""><input type="hidden" name="opening_pending_recce" value=""><div class="form-grid"><label><span>No of Recce *</span><input type="number" name="no_of_recce" min="1" step="1" required readonly aria-readonly="true" class="recce-readonly-field"></label><label><span>Pending Recce *</span><input type="number" name="pending_recce" min="0" step="1" required readonly aria-readonly="true" class="recce-readonly-field"></label><label><span>Completed</span><input type="number" name="completed_recce" min="0" step="1" value=""></label><label><span>Denied</span><input type="number" name="denied_recce" min="0" step="1" value=""></label><label><span>Cancel</span><input type="number" name="canceled_recce" min="0" step="1" value=""></label><label><span>Update By *</span><select name="updated_by_user" class="no-search-select" required><option value="0">Select User</option>';foreach($this->master_options('users')as$u)echo'<option value="'.$u->id.'">'.esc_html($u->title).'</option>';echo'</select></label><label class="wide"><span>Update Document</span><input type="file" name="update_document" accept="image/*,.pdf,.xls,.xlsx,.csv,.doc,.docx,.ppt,.pptx,.txt,.zip"></label><label class="wide"><span>Remarks</span><textarea name="remarks" rows="4" placeholder="Enter Recce update remarks"></textarea></label></div><div class="form-actions"><button class="btn primary" type="submit">Save Update</button><button class="btn" type="button" data-recce-update-close>Cancel</button></div></form></div></div>';}
 function save_recce_update(){if(!is_user_logged_in()||!current_user_can('bsoerp_access')||!wp_verify_nonce($_POST['nonce']??'',self::NONCE))wp_die('Invalid request');global$wpdb;$this->ensure_recce_schema();$recce_id=absint($_POST['recce_id']??0);$recce=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='recce'",$recce_id));if(!$recce)wp_die('Recce record not found.');$total=(int)$this->recce_meta_value($recce,'no_of_recce',0);$completed=absint($_POST['completed_recce']??0);$denied=absint($_POST['denied_recce']??0);$cancel=absint($_POST['canceled_recce']??0);$updated_by=absint($_POST['updated_by_user']??0);$remarks=sanitize_textarea_field(wp_unslash($_POST['remarks']??''));if($total<=0)wp_die('No of Recce must be greater than 0.');if(!$updated_by)wp_die('Update By is required.');$current=$this->recce_totals($recce_id,$total);$current_pending=(int)$current['pending'];$worked=$completed+$denied+$cancel;if($worked>$current_pending)wp_die('Completed + Denied + Cancel cannot be greater than Pending Recce.');$pending=$current_pending-$worked;$document_id=0;if(!empty($_FILES['update_document'])&&!empty($_FILES['update_document']['name'])){require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';$document_id=media_handle_upload('update_document',0);if(is_wp_error($document_id))wp_die('Unable to upload Update Document: '.esc_html($document_id->get_error_message()));}$ok=$wpdb->insert($this->t('recce_updates'),['recce_id'=>$recce_id,'no_of_recce'=>$total,'pending_recce'=>$pending,'completed_recce'=>$completed,'denied_recce'=>$denied,'canceled_recce'=>$cancel,'remarks'=>$remarks,'document_id'=>(int)$document_id,'updated_by_user'=>$updated_by,'created_by'=>get_current_user_id(),'created_at'=>current_time('mysql'),'entry_mode'=>'delta']);if(!$ok)wp_die('Unable to save Recce update.');$meta=json_decode((string)$recce->meta,true);if(!is_array($meta))$meta=[];$meta['no_of_recce']=$total;$new_status=$pending>0?'In Progress':'Completed';$wpdb->update($this->t('records'),['meta'=>wp_json_encode($meta),'status'=>$new_status,'updated_at'=>current_time('mysql')],['id'=>$recce_id]);$this->activity($recce_id,'recce','Recce Updated',$recce->title);wp_safe_redirect(add_query_arg('notice','saved',$this->url($new_status==='Completed'?'completed-recce':'recce-in-progress')));exit;}
 function recce_worked_listing(){global$wpdb;$this->ensure_recce_schema();$s=sanitize_text_field(wp_unslash($_GET['s']??''));$customer=absint($_GET['customer']??0);$updated_by=absint($_GET['updated_by']??0);$from=sanitize_text_field($_GET['date_from']??'');$to=sanitize_text_field($_GET['date_to']??'');$where=['1=1'];$args=[];if($s){$like='%'.$wpdb->esc_like($s).'%';$where[]='(r.title LIKE %s OR u.remarks LIKE %s)';$args[]=$like;$args[]=$like;}if($customer){$where[]='r.customer_id=%d';$args[]=$customer;}if($updated_by){$where[]='u.updated_by_user=%d';$args[]=$updated_by;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where[]='DATE(u.created_at)>=%s';$args[]=$from;}if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where[]='DATE(u.created_at)<=%s';$args[]=$to;}$sql="SELECT u.*,r.title,r.customer_id,r.assigned_to FROM {$this->t('recce_updates')} u JOIN {$this->t('records')} r ON r.id=u.recce_id WHERE ".implode(' AND ',$where).' ORDER BY u.created_at DESC,u.id DESC';$rows=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql);echo'<div class="panel listing-panel"><div class="panel-head"><div><h2>Recce Activity</h2></div></div><form class="toolbar task-filter-toolbar" method="get"><label><span>Search</span><input type="search" name="s" value="'.esc_attr($s).'" placeholder="Search updates" data-auto-search="1"></label><label><span>Customer</span><select name="customer" onchange="this.form.submit()"><option value="0">All Customers</option>';foreach($this->master_options('customers')as$o)echo'<option value="'.$o->id.'" '.selected($customer,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select></label><label><span>Update By</span><select name="updated_by" onchange="this.form.submit()"><option value="0">All Users</option>';foreach($this->master_options('users')as$o)echo'<option value="'.$o->id.'" '.selected($updated_by,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select></label><label><span>Date From</span><input type="date" name="date_from" value="'.esc_attr($from).'" onchange="this.form.submit()"></label><label><span>Date To</span><input type="date" name="date_to" value="'.esc_attr($to).'" onchange="this.form.submit()"></label><a class="btn filter-clear" href="'.esc_url($this->url('recce-worked')).'">Clear</a></form>';if(!$rows){echo'<div class="empty"><strong>No Recce updates found</strong><span>Saved Recce updates will appear here.</span></div></div>';return;}echo'<div class="table-wrap"><table class="data"><thead><tr><th>Sl.</th><th>Date & Time</th><th>Customer</th><th>No of Recce</th><th>Pending Recce</th><th>Completed</th><th>Denied</th><th>Cancel</th><th>Remarks</th><th>Update Document</th><th>Update By</th></tr></thead><tbody>';foreach($rows as$i=>$r)echo'<tr><td>'.($i+1).'</td><td>'.esc_html($this->format_utc_to_ist($r->created_at,'d/m/Y h:i A')).'</td><td>'.esc_html($this->master_name_by_id($r->customer_id)?:'—').'</td><td>'.(int)$r->no_of_recce.'</td><td>'.(int)$r->pending_recce.'</td><td>'.(int)$r->completed_recce.'</td><td>'.(int)$r->denied_recce.'</td><td>'.(int)$r->canceled_recce.'</td><td>'.nl2br(esc_html($r->remarks?:'—')).'</td><td>'.$this->recce_document_link($r->document_id).'</td><td>'.esc_html($this->task_user_display_name($r->updated_by_user)?:'—').'</td></tr>';echo'</tbody></table></div></div>';}
 function dashboard_pagination_controls($total,$page,$per,$page_key){
  $total=max(0,(int)$total);$page=max(1,(int)$page);$per=max(1,(int)$per);$pages=max(1,(int)ceil($total/$per));$from=$total?(($page-1)*$per+1):0;$to=min($total,$page*$per);
  echo'<div class="pagination-bar dashboard-pagination-bar"><div class="pagination-info">Showing <strong>'.$from.'–'.$to.'</strong> of <strong>'.$total.'</strong></div>';
  if($pages>1){echo'<nav class="pagination" aria-label="'.esc_attr($page_key).' pagination">';if($page>1)echo'<a class="btn" href="'.esc_url(add_query_arg($page_key,$page-1)).'">‹</a>';for($p=max(1,$page-2);$p<=min($pages,$page+2);$p++)echo'<a class="btn '.($p===$page?'primary':'').'" href="'.esc_url(add_query_arg($page_key,$p)).'">'.$p.'</a>';if($page<$pages)echo'<a class="btn" href="'.esc_url(add_query_arg($page_key,$page+1)).'">›</a>';echo'</nav>';}
  echo'</div>';
 }
 function dashboard_queue_panel($title,$slug,$where,$args=[],$join=''){
  global$wpdb;if(!$this->can_view_slug($slug))return;$per=10;$page_key='dashboard_'.str_replace('-','_',$slug).'_page';$page=max(1,absint($_GET[$page_key]??1));$offset=($page-1)*$per;
  $count_sql="SELECT COUNT(DISTINCT r.id) FROM {$this->t('records')} r $join WHERE $where";$total=(int)$wpdb->get_var($args?$wpdb->prepare($count_sql,$args):$count_sql);$pages=max(1,(int)ceil($total/$per));if($page>$pages){$page=$pages;$offset=($page-1)*$per;}
  $sql="SELECT DISTINCT r.* FROM {$this->t('records')} r $join WHERE $where ORDER BY r.updated_at DESC,r.id DESC LIMIT $per OFFSET $offset";
  $rows=$wpdb->get_results($args?$wpdb->prepare($sql,$args):$sql);
  echo'<div class="panel dashboard-queue-panel"><div class="panel-head"><div><h2>'.esc_html($title).'</h2></div><div class="head-actions"><a class="btn" href="'.esc_url($this->url($slug)).'">View All</a></div></div>';
  if($rows){$this->table($rows,false,'',$slug);$this->dashboard_pagination_controls($total,$page,$per,$page_key);}else echo'<div class="empty"><strong>No records found</strong><span>This queue is currently clear.</span></div>';
  echo'</div>';
 }

 function is_timesheet_admin(){
