  $page_id=url_to_postid($this->url('daily-activity'));if($page_id)echo'<input type="hidden" name="page_id" value="'.(int)$page_id.'">';
  echo'<label><span>Search</span><input type="search" name="s" value="'.esc_attr($s).'"></label><label><span>Date From</span><input type="date" name="date_from" value="'.esc_attr($date_from).'"></label><label><span>Date To</span><input type="date" name="date_to" value="'.esc_attr($date_to).'"></label>';
  if($is_admin){echo'<label><span>Employee</span><select class="erp-searchable" name="user"><option value="0">All Employees</option>';foreach($this->master_options('users')as$o)echo'<option value="'.(int)$o->id.'" '.selected($filter_user,$o->id,false).'>'.esc_html($o->title).'</option>';echo'</select></label>';}
  echo'<div class="timesheet-filter-actions"><button class="btn" type="submit">Filter</button><a class="btn filter-clear" href="'.esc_url($this->url('daily-activity')).'">Clear</a></div></form>';
  if(!$rows){echo'<div class="empty"><strong>No Daily Activity found</strong><span>Saved activities will appear here.</span></div>';}
  else{echo'<div class="table-wrap"><table class="data"><thead><tr><th>Sl.</th><th>Date &amp; Time</th><th>Name</th><th>Activity</th>'.($is_admin?'<th>Action</th>':'').'</tr></thead><tbody>';foreach($rows as$i=>$r){$time=$this->format_utc_to_ist($r->created_at,'H:i');$dt=date_i18n('d/m/Y',strtotime($r->activity_date)).($time!==''?' '.$time:'');echo'<tr><td>'.($i+1).'</td><td>'.esc_html($dt).'</td><td>'.esc_html($r->user_name?:$this->task_user_display_name($r->user_id)?:'—').'</td><td>'.nl2br(esc_html($r->activity)).'</td>';if($is_admin){$edit_url=add_query_arg('edit_activity',(int)$r->id,$this->url('daily-activity'));$del=wp_nonce_url(add_query_arg(['action'=>'bsoerp_delete_timesheet_activity','id'=>(int)$r->id],admin_url('admin-post.php')),'bsoerp_timesheet_delete_'.(int)$r->id);echo'<td class="actions"><a title="Edit" href="'.esc_url($edit_url).'">✎</a><a title="Delete" class="delete" href="'.esc_url($del).'" onclick="return confirm(\'Delete this activity?\')">⌫</a></td>';}echo'</tr>';}echo'</tbody></table></div>';}
  echo'</div><style>.timesheet-top-actions{display:flex;justify-content:flex-end;gap:8px;margin-bottom:14px}.timesheet-filter-toolbar{display:grid;grid-template-columns:minmax(220px,1.4fr) minmax(150px,.8fr) minmax(150px,.8fr) minmax(180px,1fr) auto;gap:10px;align-items:end;margin-bottom:14px}.timesheet-filter-toolbar label{display:flex;flex-direction:column;gap:6px;font-size:12px}.timesheet-filter-toolbar input,.timesheet-filter-toolbar select,.timesheet-filter-toolbar .erp-search-select-input{height:38px;width:100%;border:1px solid #d0d5dd;border-radius:7px;background:#fff;padding:8px 10px;font:12px Montserrat,Arial,sans-serif}.timesheet-filter-actions{display:flex;gap:8px;align-items:end}.timesheet-filter-actions .btn{height:38px;display:inline-flex;align-items:center}.timesheet-filter-toolbar .erp-search-select{width:100%}@media(max-width:900px){.timesheet-filter-toolbar{grid-template-columns:1fr 1fr}.timesheet-filter-actions{grid-column:1/-1}}@media(max-width:560px){.timesheet-filter-toolbar{grid-template-columns:1fr}.timesheet-filter-actions{grid-column:auto}}</style>';
 }
 function daily_activity_report_rows($date_from='',$date_to='',$user_id=0){
  global$wpdb;$tz=new DateTimeZone('Asia/Kolkata');$today=(new DateTime('now',$tz))->format('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date_from))$date_from=$today;if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date_to))$date_to=$date_from;$where=['t.activity_date>=%s','t.activity_date<=%s'];$args=[$date_from,$date_to];if($user_id){$where[]='t.user_id=%d';$args[]=absint($user_id);}$sql="SELECT t.*,r.title AS user_name FROM {$this->t('timesheet_entries')} t LEFT JOIN {$this->t('records')} r ON r.id=t.user_id WHERE ".implode(' AND ',$where)." ORDER BY COALESCE(r.title,''),t.created_at ASC,t.id ASC";return$wpdb->get_results($wpdb->prepare($sql,$args));
 }
 function daily_activity_report_pdf_bytes($date_from='',$date_to='',$user_id=0){
  $rows=$this->daily_activity_report_rows($date_from,$date_to,$user_id);$W=595.28;$H=841.89;$m=42;$pages=[];$esc=function($x){return$this->pdf_text_escape($x);};$txt=function($font,$size,$x,$y,$text)use($esc){return"BT /$font $size Tf 1 0 0 1 $x $y Tm (".$esc($text).") Tj ET\n";};$rect=function($x,$y,$w,$h,$fill=false){return$fill?"0.93 g $x $y $w $h re f 0 g\n":"$x $y $w $h re S\n";};$wrap=function($text,$max=75){$text=trim(preg_replace('/\s+/',' ',(string)$text));if($text==='')return['-'];$words=explode(' ',$text);$out=[];$line='';foreach($words as$w){$try=$line===''?$w:$line.' '.$w;if(strlen($try)>$max&&$line!==''){$out[]=$line;$line=$w;}else$line=$try;}if($line!=='')$out[]=$line;return$out?:['-'];};$settings=get_option('bsoerp_settings',[]);$tmp=[];$logo='';if(!empty($settings['logo_id']))$logo=$this->quotation_attachment_jpeg((int)$settings['logo_id'],$tmp,'daily-activity-logo');
  $range=$date_from===$date_to?date('d/m/Y',strtotime($date_from)):date('d/m/Y',strtotime($date_from)).' - '.date('d/m/Y',strtotime($date_to));
  if(!$rows){$c="0 G 0 g 0.7 w\n";$c.=$txt('F2',18,$m,790,'Daily Activity Report');$c.=$txt('F1',10,$m,770,'No Daily Activity found for the selected date.');$pages[]=$c;}
  else{
   $idx=0;$page_no=1;
   while($idx<count($rows)){
    $c="0 G 0 g 0.7 w\n";if($logo)$c.=$this->pdf_logo_command($logo,$m,760,74,50);$c.=$txt('F2',18,$m+95,795,'Daily Activity Report');$c.=$txt('F1',10,$m+95,775,'Date: '.$range.($page_no>1?' (Continued)':''));
    $y=735;$dateW=115;$empW=125;$actW=$W-2*$m-$dateW-$empW;$headH=24;
    $c.=$rect($m,$y-$headH,$dateW,$headH,true).$rect($m,$y-$headH,$dateW,$headH,false).$txt('F2',9,$m+5,$y-16,'Date');
    $c.=$rect($m+$dateW,$y-$headH,$empW,$headH,true).$rect($m+$dateW,$y-$headH,$empW,$headH,false).$txt('F2',9,$m+$dateW+5,$y-16,'Employee');
    $c.=$rect($m+$dateW+$empW,$y-$headH,$actW,$headH,true).$rect($m+$dateW+$empW,$y-$headH,$actW,$headH,false).$txt('F2',9,$m+$dateW+$empW+5,$y-16,'Activity');
    $y-=$headH;$last_user=null;
    for(;$idx<count($rows);$idx++){
     $r=$rows[$idx];$name=$r->user_name?:($this->task_user_display_name((int)$r->user_id)?:'Employee');$dt=date('d/m/Y',strtotime($r->activity_date)).' '.($this->format_utc_to_ist($r->created_at,'H:i')?:'');
     $act_lines=$wrap($r->activity,46);$name_lines=$wrap($name,22);$rh=max(24,10+max(count($act_lines),count($name_lines))*10);
     if($y-$rh<55)break;
     if($last_user!==null&&$last_user!==(int)$r->user_id){$c.="0.82 G 0.5 w ".$m." ".$y." m ".($W-$m)." ".$y." l S\n0 G\n";}
     $c.=$rect($m,$y-$rh,$dateW,$rh,false).$txt('F1',8.5,$m+5,$y-16,$dt);
     $c.=$rect($m+$dateW,$y-$rh,$empW,$rh,false);$yy=$y-15;foreach($name_lines as$li=>$line)$c.=$txt('F1',8.5,$m+$dateW+5,$yy-$li*10,$line);
     $c.=$rect($m+$dateW+$empW,$y-$rh,$actW,$rh,false);$yy=$y-15;foreach($act_lines as$li=>$line)$c.=$txt('F1',8.5,$m+$dateW+$empW+5,$yy-$li*10,$line);
     $y-=$rh;$last_user=(int)$r->user_id;
    }
    $pages[]=$c;$page_no++;
   }
  }
  $pdf=$this->simple_pdf_from_pages($pages,$W,$H,$logo);foreach($tmp as$f)if($f&&is_file($f))@unlink($f);return$pdf;
 }
 function daily_activity_pdf(){if(!is_user_logged_in()||!current_user_can('bsoerp_access'))wp_die('Access denied');if(!wp_verify_nonce($_GET['_wpnonce']??'','bsoerp_daily_activity_pdf'))wp_die('Invalid request');$from=sanitize_text_field($_GET['date_from']??'');$to=sanitize_text_field($_GET['date_to']??'');$uid=$this->is_timesheet_admin()?absint($_GET['user']??0):$this->current_master_user_id();$pdf=$this->daily_activity_report_pdf_bytes($from,$to,$uid);$name='Daily-Activity-Report-'.date('d-m-Y').'.pdf';nocache_headers();header('Content-Type: application/pdf');header('Content-Disposition: inline; filename="'.$name.'"');header('Content-Length: '.strlen($pdf));echo$pdf;exit;}
 function daily_activity_save_public_pdf($date){$up=wp_upload_dir();if(!empty($up['error']))return new WP_Error('upload_dir',$up['error']);$dir=trailingslashit($up['basedir']).'bizskill-daily-activity';$url=trailingslashit($up['baseurl']).'bizskill-daily-activity';if(!wp_mkdir_p($dir))return new WP_Error('mkdir','Unable to create Daily Activity report folder.');$pdf=$this->daily_activity_report_pdf_bytes($date,$date,0);$filename='Daily-Activity-Report-'.date('d-m-Y',strtotime($date)).'.pdf';$path=trailingslashit($dir).$filename;if(file_put_contents($path,$pdf)===false)return new WP_Error('write','Unable to save Daily Activity PDF.');$cache_buster=time();return['path'=>$path,'url'=>trailingslashit($url).rawurlencode($filename).'?v='.$cache_buster,'filename'=>$filename];}
 function whatsapp_send_document_template($event_key,$mobile,$document_url,$filename,$vars=[]){$o=get_option('bsoerp_whatsapp_meta',[]);if(!is_array($o)||empty($o['enabled'])){$this->whatsapp_log_result($event_key,$mobile,false,'Meta / WhatsApp Business is disabled.');return false;}$phone_id=trim((string)($o['phone_number_id']??''));$token=trim((string)($o['access_token']??''));if($phone_id===''||$token===''){$this->whatsapp_log_result($event_key,$mobile,false,'Phone Number ID or Access Token is missing.');return false;}$t=$this->whatsapp_template_config($event_key);if(!$t||empty($t['active'])){$this->whatsapp_log_result($event_key,$mobile,false,'Daily Activity Report template is inactive or unavailable.');return false;}$to=$this->whatsapp_normalize_mobile($mobile);if(strlen($to)<11){$this->whatsapp_log_result($event_key,$to,false,'Recipient mobile number is missing or invalid.');return false;}$body=(string)($t['body']??'');$names=[];if(preg_match_all('/\{\{\s*([A-Za-z0-9_]+)\s*\}\}/',$body,$mm))foreach($mm[1]as$n)if(!in_array($n,$names,true))$names[]=$n;$parameters=[];foreach($names as$n)$parameters[]=['type'=>'text','parameter_name'=>$n,'text'=>$this->whatsapp_value($vars[$n]??'')];$components=[['type'=>'header','parameters'=>[['type'=>'document','document'=>['link'=>$document_url,'filename'=>$filename]]]],['type'=>'body','parameters'=>$parameters]];$payload=['messaging_product'=>'whatsapp','to'=>$to,'type'=>'template','template'=>['name'=>$t['code'],'language'=>['code'=>'en'],'components'=>$components]];$api_version=trim((string)($o['api_version']??'v23.0'));if(!preg_match('/^v\d+\.\d+$/',$api_version))$api_version='v23.0';$endpoint='https://graph.facebook.com/'.$api_version.'/'.rawurlencode($phone_id).'/messages';$res=wp_remote_post($endpoint,['timeout'=>30,'headers'=>['Authorization'=>'Bearer '.$token,'Content-Type'=>'application/json','Accept'=>'application/json'],'body'=>wp_json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'data_format'=>'body']);if(is_wp_error($res)){$this->whatsapp_log_result($event_key,$to,false,$res->get_error_message());return false;}$code=(int)wp_remote_retrieve_response_code($res);$raw=(string)wp_remote_retrieve_body($res);$json=json_decode($raw,true);$mid=(string)($json['messages'][0]['id']??'');if($code>=200&&$code<300&&$mid!==''){$this->whatsapp_log_result($event_key,$to,true,'Daily Activity PDF accepted by Meta.',$code,$mid,'','','',$raw);return true;}$error=$json['error']??[];$err=(string)($error['message']??($raw?:'Meta rejected the Daily Activity PDF.'));$this->whatsapp_log_result($event_key,$to,false,$err,$code,$mid,(string)($error['code']??''),(string)($error['error_subcode']??''),(string)($error['fbtrace_id']??''),$raw);return false;}
 function test_daily_activity_pdf(){
  if(!current_user_can('bsoerp_manage'))wp_die('Access denied');
  if(!wp_verify_nonce($_GET['_wpnonce']??'','bsoerp_test_daily_activity_pdf'))wp_die('Invalid request');
  $s=get_option('bsoerp_settings',[]);if(!is_array($s))$s=[];
  $number=trim((string)($s['daily_activity_report_number']??''));
  $back=add_query_arg(['daily_activity_test'=>'failed'],$this->url('settings'));
  if($number===''){wp_safe_redirect(add_query_arg('daily_activity_test_msg',rawurlencode('Number to Send Daily Activity PDF is blank.'),$back));exit;}
  $recipients=array_values(array_filter(array_map('trim',preg_split('/[,;]+/',$number))));
  if(!$recipients){wp_safe_redirect(add_query_arg('daily_activity_test_msg',rawurlencode('No valid recipient number found.'),$back));exit;}
  $tz=new DateTimeZone('Asia/Kolkata');$now=new DateTime('now',$tz);$today=$now->format('Y-m-d');
  $file=$this->daily_activity_save_public_pdf($today);
  if(is_wp_error($file)){wp_safe_redirect(add_query_arg('daily_activity_test_msg',rawurlencode($file->get_error_message()),$back));exit;}
  $ok_count=0;$fail_count=0;$last_msg='';
  foreach($recipients as$mobile){$ok=$this->whatsapp_send_document_template('daily_activity_pdf',$mobile,$file['url'],$file['filename'],['report_date'=>$now->format('d/m/Y')]);if($ok)$ok_count++;else{$fail_count++;$lr=get_option('bsoerp_whatsapp_last_result',[]);if(is_array($lr)&&!empty($lr['message']))$last_msg=(string)$lr['message'];}}
  $status=$ok_count>0?'success':'failed';$msg=$ok_count.' test message(s) accepted by Meta.';if($fail_count)$msg.=' '.$fail_count.' failed.'.($last_msg!==''?' '.$last_msg:'');
  wp_safe_redirect(add_query_arg(['daily_activity_test'=>$status,'daily_activity_test_msg'=>rawurlencode($msg)],$this->url('settings')));exit;
 }
 function daily_activity_cron(){
  $tz=new DateTimeZone('Asia/Kolkata');$now=new DateTime('now',$tz);$now_label=$now->format('d/m/Y H:i:s');
  $log=function($status,$message='')use($now_label){update_option('bsoerp_daily_activity_cron_status',['time'=>$now_label,'status'=>$status,'message'=>$message],false);};
  $s=get_option('bsoerp_settings',[]);if(!is_array($s)||empty($s['daily_activity_report_active'])){$log('Inactive','Daily Activity Report is not active.');return;}
  $number=trim((string)($s['daily_activity_report_number']??''));$send_time=trim((string)($s['daily_activity_report_time']??''));
  if($number===''){$log('Waiting','Recipient number is blank.');return;}if(!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$send_time)){$log('Waiting','Send time is invalid.');return;}
  $today=$now->format('Y-m-d');if($now->format('H:i')<$send_time){$log('Waiting','Scheduled for '.$send_time.' IST.');return;}
  $sent=get_option('bsoerp_daily_activity_report_sent',[]);if(!is_array($sent))$sent=[];
  $recipients=array_values(array_filter(array_map('trim',preg_split('/[,;]+/',$number))));if(!$recipients){$log('Waiting','No valid recipient number found.');return;}
  $pending=[];foreach($recipients as$mobile){$key=$today.'|'.$this->whatsapp_normalize_mobile($mobile);if(empty($sent[$key]))$pending[]=$mobile;}
  if(!$pending){$log('Already Sent','Today\'s report has already been sent to all configured recipients.');return;}
  $file=$this->daily_activity_save_public_pdf($today);if(is_wp_error($file)){$log('PDF Error',$file->get_error_message());return;}
  $ok_count=0;$fail_count=0;$last_error='';foreach($pending as$mobile){$key=$today.'|'.$this->whatsapp_normalize_mobile($mobile);$ok=$this->whatsapp_send_document_template('daily_activity_pdf',$mobile,$file['url'],$file['filename'],['report_date'=>$now->format('d/m/Y')]);if($ok){$sent[$key]=gmdate('Y-m-d H:i:s');$ok_count++;}else{$fail_count++;$lr=get_option('bsoerp_whatsapp_last_result',[]);if(is_array($lr)&&!empty($lr['message']))$last_error=(string)$lr['message'];}}
  update_option('bsoerp_daily_activity_report_sent',$sent,false);if(count($sent)>100){$sent=array_slice($sent,-100,null,true);update_option('bsoerp_daily_activity_report_sent',$sent,false);}
  if($ok_count)$log('Sent',$ok_count.' report(s) accepted by Meta.'.($fail_count?' '.$fail_count.' failed.':''));else $log('Failed',$last_error?:'WhatsApp send failed.');
 }
 function dashboard_daily_activity_panel(){
  $today=current_time('Y-m-d');$start=$today.' 00:00:00';$end=$today.' 23:59:59';
  $this->dashboard_daily_activity_summary_panel($start,$end);
 }
 function dashboard_daily_activity_summary_panel($start,$end){
  global$wpdb;
  $record_count=function($module,$type)use($wpdb,$start,$end){return(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$this->t('records')} WHERE module=%s AND record_type=%s AND created_at BETWEEN %s AND %s",$module,$type,$start,$end));};
  $activity_count=function($module,$action)use($wpdb,$start,$end){return(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$this->t('activity')} WHERE module=%s AND action=%s AND created_at BETWEEN %s AND %s",$module,$action,$start,$end));};
  $today=current_time('Y-m-d');
  $cards=[
   ['Tasks Add',$record_count('tasks','task'),add_query_arg('daily_created',1,$this->url('tasks-master'))],
   ['Enquiry Added',$record_count('leads','lead'),add_query_arg('daily_created',1,$this->url('leads-master'))],
   ['Recce Update',$activity_count('recce','Recce Updated'),add_query_arg(['date_from'=>$today,'date_to'=>$today],$this->url('recce-worked'))],
   ['Designs Update',$activity_count('designs','Design Updated'),$this->url('design-master')],
   ['Quotation Create',$record_count('quotations','quotation'),add_query_arg('daily_created',1,$this->url('quotation-master'))],
   ['Quotation Client Approval',$activity_count('quotations','Quotation Approved'),add_query_arg('status','Approved',$this->url('quotation-master'))],
   ['Order Create',$record_count('orders','order'),add_query_arg('daily_created',1,$this->url('order-master'))],
   ['Create PO',$record_count('purchase-orders','purchase-order'),add_query_arg('daily_created',1,$this->url('purchase-orders'))],
   ['Order Delivered',$activity_count('orders','Delivery Updated'),add_query_arg(['date_from'=>$today,'date_to'=>$today],$this->url('delivered-orders'))],
  ];
  echo'<div class="panel dashboard-daily-summary-panel"><div class="panel-head"><div><h2>Daily Activity</h2></div></div><div class="table-wrap"><table class="data daily-activity-summary-table"><thead><tr><th>Sl.</th><th>Activity</th><th>Count</th></tr></thead><tbody>';
  foreach($cards as$i=>$c){$link=esc_url($c[2]);echo'<tr class="daily-activity-clickable" onclick="window.location.href=\''.$link.'\'" style="cursor:pointer" title="View today records"><td>'.($i+1).'</td><td><a href="'.$link.'">'.esc_html($c[0]).'</a></td><td><a href="'.$link.'"><strong>'.(int)$c[1].'</strong></a></td></tr>';}
  echo'</tbody></table></div></div>';
 }
 function dashboard(){
  global $wpdb;
  $today=current_time('Y-m-d');
  $from=$today;$to=$today;
  $fmt=function($v){$v=(float)$v;return floor($v)==$v?number_format_i18n($v):number_format_i18n($v,2);};
  $count=function($module,$extra='1=1') use($wpdb){return(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$this->t('records')} r WHERE r.module=%s AND $extra",$module));};

  // Pending summary is intentionally all-current pending data (not date filtered).
  $pending_tasks=$count('tasks',"r.status IN ('Pending','In Progress')");
  $pending_leads=$count('leads',"r.status='In Progress'");
  $pending_po=$count('purchase-orders',"r.status NOT IN ('Completed','Canceled','Rejected')");
  $pending_wo=$count('production',"r.record_type='job' AND r.status IN ('Pending','In Progress','Partly Completed')");

  $recce_rows=$wpdb->get_results("SELECT * FROM {$this->t('records')} WHERE module='recce' AND status<>'Canceled'");
  $pending_recce=0;$pending_recce_emp=[];
  foreach($recce_rows as$r){$total=(int)$this->recce_meta_value($r,'no_of_recce',0);$rt=$this->recce_totals($r->id,$total);$qty=max(0,(int)$rt['pending']);if($qty>0){$pending_recce++;$id=(int)$r->assigned_to;$name=$this->task_user_display_name($id)?:'Unassigned';$key=(string)$id;if(!isset($pending_recce_emp[$key]))$pending_recce_emp[$key]=['label'=>$name,'value'=>0,'url'=>add_query_arg('assigned_to',$id,$this->url('recce-in-progress'))];$pending_recce_emp[$key]['value']+=1;}}

  $design_rows=$wpdb->get_results("SELECT * FROM {$this->t('records')} WHERE module='designs' AND status<>'Canceled'");
  $pending_design=0;$pending_design_emp=[];
  foreach($design_rows as$r){$assigned=max(0,(int)$this->design_meta_value($r,'design_assigned',0));$dt=$this->design_totals($r->id,$assigned);$approval=(string)$this->design_meta_value($r,'approval_required','')==='1';$qty=max(0,(int)$dt['pending'])+($approval?max(0,(int)$dt['completed']-(int)$dt['approved']):0);if($qty>0){$pending_design++;$id=(int)$r->assigned_to;$name=$this->task_user_display_name($id)?:'Unassigned';$key=(string)$id;if(!isset($pending_design_emp[$key]))$pending_design_emp[$key]=['label'=>$name,'value'=>0,'url'=>add_query_arg('designer',$id,$this->url('designs-in-progress'))];$pending_design_emp[$key]['value']+=1;}}

  $pending_tasks_emp=[];$rows=$wpdb->get_results("SELECT assigned_to,COUNT(*) total FROM {$this->t('records')} WHERE module='tasks' AND status IN ('Pending','In Progress') GROUP BY assigned_to ORDER BY total DESC");foreach($rows as$row){$id=(int)$row->assigned_to;$name=$this->task_user_display_name($id)?:'Unassigned';$pending_tasks_emp[]=['label'=>$name,'value'=>(float)$row->total,'url'=>add_query_arg('assigned_to',$id,$this->url('tasks-in-progress'))];}
  $pending_leads_emp=[];$rows=$wpdb->get_results("SELECT assigned_to,COUNT(*) total FROM {$this->t('records')} WHERE module='leads' AND status='In Progress' GROUP BY assigned_to ORDER BY total DESC");foreach($rows as$row){$id=(int)$row->assigned_to;$name=$this->task_user_display_name($id)?:'Unassigned';$pending_leads_emp[]=['label'=>$name,'value'=>(float)$row->total,'url'=>add_query_arg('assigned_to',$id,$this->url('leads-in-progress'))];}
  $pending_po_vendor=[];$rows=$wpdb->get_results("SELECT party_id,COUNT(*) total FROM {$this->t('records')} WHERE module='purchase-orders' AND status NOT IN ('Completed','Canceled','Rejected') GROUP BY party_id ORDER BY total DESC");foreach($rows as$row){$id=(int)$row->party_id;$name=$this->master_name_by_id($id)?:'No Vendor';$pending_po_vendor[]=['label'=>$name,'value'=>(float)$row->total,'url'=>add_query_arg('supplier',$id,$this->url('po-in-progress'))];}
  $pending_wo_vendor=[];$rows=$wpdb->get_results("SELECT CAST(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(meta,'$.vendor_id')),'0') AS UNSIGNED) vendor_id,COUNT(*) total FROM {$this->t('records')} WHERE module='production' AND record_type='job' AND status IN ('Pending','In Progress','Partly Completed') GROUP BY vendor_id ORDER BY total DESC");foreach($rows as$row){$id=(int)$row->vendor_id;$name=$this->master_name_by_id($id)?:'No Vendor';$pending_wo_vendor[]=['label'=>$name,'value'=>(float)$row->total,'url'=>add_query_arg('vendor',$id,$this->url('work-orders-in-progress'))];}

  // Pending GRN = PO quantity still awaiting receipt, vendor-wise.
  $pending_grn=0;$pending_grn_vendor=[];
  $po_lines=$wpdb->get_results("SELECT l.id,l.qty,r.party_id FROM {$this->t('line_items')} l JOIN {$this->t('records')} r ON r.id=l.record_id WHERE r.module='purchase-orders' AND r.record_type='purchase-order' AND r.status NOT IN ('Canceled','Rejected')");
  foreach($po_lines as$pl){$received=(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(gl.received_qty),0) FROM {$this->t('line_items')} gl JOIN {$this->t('records')} gr ON gr.id=gl.record_id WHERE gl.source_line_id=%d AND gr.module='grn' AND gr.status<>'Canceled'",(int)$pl->id));$left=max(0,(float)$pl->qty-$received);if($left<=0)continue;$pending_grn++;$name=$this->master_name_by_id((int)$pl->party_id)?:'No Vendor';$pending_grn_vendor[$name]=($pending_grn_vendor[$name]??0)+1;}

  $bar=function($data) use($fmt){$clean=[];foreach((array)$data as$k=>$row){if(is_array($row)){$label=(string)($row['label']??$k);$value=(float)($row['value']??0);$url=(string)($row['url']??'');}else{$label=(string)$k;$value=(float)$row;$url='';}if($value>0)$clean[]=['label'=>$label,'value'=>$value,'url'=>$url];}if(!$clean)return'<div class="pending-empty">No pending data</div>';usort($clean,function($a,$b){return$b['value']<=>$a['value'];});$max=max(array_column($clean,'value'));$html='<div class="pending-bars">';foreach($clean as$row){$pct=max(4,round(($row['value']/$max)*100,1));$name=esc_html($row['label']);if($row['url'])$name='<a class="pending-name-link" href="'.esc_url($row['url']).'">'.$name.'</a>';$html.='<div class="pending-bar-row"><div class="pending-bar-label"><span>'.$name.'</span><b>'.$fmt($row['value']).'</b></div><div class="pending-bar-track"><i style="--pending-height:'.$pct.'%"></i></div></div>';}$html.='</div>';return$html;};

  $cards=[
   ['Pending Tasks',$pending_tasks,'tasks-in-progress','✓'],
   ['Pending Enquiries',$pending_leads,'leads-in-progress','◎'],
   ['Pending Designs',$pending_design,'designs-in-progress','✦'],
   ['Pending Recce',$pending_recce,'recce-in-progress','⌖'],
   ['Pending PO',$pending_po,'po-in-progress','🛒'],
   ['Pending Work Orders',$pending_wo,'work-orders-in-progress','⚙'],
   ['Pending GRN',$pending_grn,'add-grn','▣']
  ];

  // Today worked counts.
  $start=$today.' 00:00:00';$end=$today.' 23:59:59';
  $records_today=function($module,$type='')use($wpdb,$start,$end){$where='module=%s AND created_at BETWEEN %s AND %s';$args=[$module,$start,$end];if($type!==''){$where.=' AND record_type=%s';$args[]=$type;}return(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$this->t('records')} WHERE $where",$args));};
  $table_today=function($table,$date_col='created_at')use($wpdb,$start,$end){return(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$this->t($table)} WHERE $date_col BETWEEN %s AND %s",$start,$end));};
  $lead_added=$records_today('leads','lead');
  $lead_updated=$table_today('lead_updates');
  $task_worked=$records_today('tasks','task')+$table_today('task_updates');
  $design_worked=$records_today('designs','design')+$table_today('design_updates');
  $recce_worked=$records_today('recce','recce')+$table_today('recce_updates');
  $po_worked=$records_today('purchase-orders','purchase-order');
  $wo_worked=$records_today('production','job')+(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$this->t('activity')} WHERE module='production' AND action='Job Updated' AND created_at BETWEEN %s AND %s",$start,$end));
  $grn_worked=$records_today('grn','grn');
  $today_cards=[
   ['Enquiry Added',$lead_added,'leads-master','＋'],['Enquiry Updated',$lead_updated,'lead-update-log','↻'],['Task',$task_worked,'tasks-master','✓'],['Design',$design_worked,'design-master','✦'],['Recce',$recce_worked,'recce-master','⌖'],['PO',$po_worked,'purchase-orders','🛒'],['Work Order',$wo_worked,'work-orders-master','⚙'],['GRN',$grn_worked,'grn-master','▣']
  ];
  $today_max=1;foreach($today_cards as$c)$today_max=max($today_max,(int)$c[1]);
  $today_chart='<div class="today-worked-chart"><div class="today-chart-bars">';
  foreach($today_cards as$c){$val=(int)$c[1];$height=$val>0?max(8,round(($val/$today_max)*150)):3;$today_chart.='<a class="today-chart-col" href="'.esc_url($this->url($c[2])).'" title="'.esc_attr($c[0].': '.$val).'"><div class="today-chart-value">'.$val.'</div><div class="today-chart-bar-wrap"><i style="height:'.$height.'px"></i></div><span>'.esc_html($c[0]).'</span></a>';}
  $today_chart.='</div></div>';

  // Today worked employee-wise: who performed or owned today's activity.
  $today_employee=[];
  $add_employee=function($id,$qty=1) use (&$today_employee){$id=absint($id);$name=$id?$this->task_user_display_name($id):'';if(!$name)$name='Unassigned';$today_employee[$name]=($today_employee[$name]??0)+(float)$qty;};
  $rows=$wpdb->get_results($wpdb->prepare("SELECT created_by,COUNT(*) total FROM {$this->t('records')} WHERE module='leads' AND record_type='lead' AND created_at BETWEEN %s AND %s GROUP BY created_by",$start,$end));foreach($rows as$row)$add_employee($row->created_by,$row->total);
  $rows=$wpdb->get_results($wpdb->prepare("SELECT COALESCE(NULLIF(updated_by_user,0),created_by) user_id,COUNT(*) total FROM {$this->t('lead_updates')} WHERE created_at BETWEEN %s AND %s GROUP BY user_id",$start,$end));foreach($rows as$row)$add_employee($row->user_id,$row->total);
  $rows=$wpdb->get_results($wpdb->prepare("SELECT created_by,COUNT(*) total FROM {$this->t('records')} WHERE module='tasks' AND record_type='task' AND created_at BETWEEN %s AND %s GROUP BY created_by",$start,$end));foreach($rows as$row)$add_employee($row->created_by,$row->total);
  $rows=$wpdb->get_results($wpdb->prepare("SELECT created_by,COUNT(*) total FROM {$this->t('task_updates')} WHERE created_at BETWEEN %s AND %s GROUP BY created_by",$start,$end));foreach($rows as$row)$add_employee($row->created_by,$row->total);
  $rows=$wpdb->get_results($wpdb->prepare("SELECT created_by,COUNT(*) total FROM {$this->t('records')} WHERE module='designs' AND record_type='design' AND created_at BETWEEN %s AND %s GROUP BY created_by",$start,$end));foreach($rows as$row)$add_employee($row->created_by,$row->total);
  $rows=$wpdb->get_results($wpdb->prepare("SELECT COALESCE(NULLIF(updated_by_user,0),created_by) user_id,COUNT(*) total FROM {$this->t('design_updates')} WHERE created_at BETWEEN %s AND %s GROUP BY user_id",$start,$end));foreach($rows as$row)$add_employee($row->user_id,$row->total);
  $rows=$wpdb->get_results($wpdb->prepare("SELECT created_by,COUNT(*) total FROM {$this->t('records')} WHERE module='recce' AND record_type='recce' AND created_at BETWEEN %s AND %s GROUP BY created_by",$start,$end));foreach($rows as$row)$add_employee($row->created_by,$row->total);
  $rows=$wpdb->get_results($wpdb->prepare("SELECT COALESCE(NULLIF(updated_by_user,0),created_by) user_id,COUNT(*) total FROM {$this->t('recce_updates')} WHERE created_at BETWEEN %s AND %s GROUP BY user_id",$start,$end));foreach($rows as$row)$add_employee($row->user_id,$row->total);
  $rows=$wpdb->get_results($wpdb->prepare("SELECT created_by,COUNT(*) total FROM {$this->t('records')} WHERE module='purchase-orders' AND record_type='purchase-order' AND created_at BETWEEN %s AND %s GROUP BY created_by",$start,$end));foreach($rows as$row)$add_employee($row->created_by,$row->total);
