  echo'<style>
  .pending-dashboard{display:flex;flex-direction:column;gap:18px}.pending-kpis{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:12px}.pending-kpi{display:grid;grid-template-columns:auto 1fr;gap:11px;align-items:center;padding:16px;border:1px solid #e4e8ef;border-radius:14px;background:#fff;box-shadow:0 5px 16px rgba(18,33,56,.05);text-decoration:none;color:inherit;position:relative;overflow:hidden}.pending-kpi:before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--bsoerp-theme)}.pending-kpi-icon{width:40px;height:40px;border-radius:11px;display:grid;place-items:center;background:var(--bsoerp-theme-soft);color:var(--bsoerp-theme);font-size:20px;font-weight:700}.pending-kpi-copy span{display:block;font-size:11px;color:#6f7b8a;margin-bottom:4px}.pending-kpi-copy strong{display:block;font-size:25px;line-height:1;font-weight:800}.pending-chart-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.pending-chart{background:#fff;border:1px solid #e4e8ef;border-radius:15px;padding:17px;box-shadow:0 5px 18px rgba(18,33,56,.045);min-width:0;--chart-accent:var(--bsoerp-theme);--chart-accent-soft:var(--bsoerp-theme-soft)}.pending-chart-head{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:14px}.pending-chart-head h3{margin:0;font-size:16px;color:var(--chart-accent)}.pending-chart-head span{font-size:11px;color:#8a95a3}.pending-bars{display:flex;align-items:flex-end;gap:12px;height:220px;overflow-x:auto;overflow-y:hidden;padding:8px 2px 2px}.pending-bar-row{display:grid;grid-template-rows:22px 160px auto;gap:7px;align-items:end;min-width:72px;flex:1}.pending-bar-label{display:contents;font-size:11px}.pending-bar-label span{grid-row:3;text-align:center;line-height:1.15;overflow-wrap:anywhere}.pending-bar-label b{grid-row:1;text-align:center;font-size:12px;color:var(--chart-accent)}.pending-bar-track{grid-row:2;width:min(50px,72%);height:160px;margin:0 auto;background:repeating-linear-gradient(to top,#edf1f5 0,#edf1f5 1px,transparent 1px,transparent 40px);border-bottom:1px solid color-mix(in srgb,var(--chart-accent) 35%,#cbd4df);border-radius:8px 8px 2px 2px;display:flex;align-items:flex-end;overflow:hidden}.pending-bar-track i{width:100%!important;height:var(--pending-height,4%)!important;min-height:4px;display:block;border-radius:8px 8px 2px 2px;background:linear-gradient(180deg,color-mix(in srgb,var(--chart-accent) 62%,#ffffff),var(--chart-accent))}.pending-empty{display:grid;place-items:center;height:120px;color:#8b95a4;font-size:13px;background:#f8fafb;border-radius:10px}.today-worked{margin-top:4px}.today-worked-head{display:flex;justify-content:space-between;align-items:center;margin:0 0 10px}.today-worked-head h3{margin:0;font-size:17px}.today-worked-head span{font-size:11px;color:#8994a2}.today-worked-grid{display:grid;grid-template-columns:repeat(8,minmax(0,1fr));gap:10px}.today-worked-card{background:#fff;border:1px solid #e4e8ef;border-radius:13px;padding:13px;text-decoration:none;color:inherit;display:flex;align-items:center;gap:10px;box-shadow:0 4px 14px rgba(18,33,56,.04)}.today-worked-card i{width:34px;height:34px;border-radius:10px;background:var(--bsoerp-theme-soft);color:var(--bsoerp-theme);display:grid;place-items:center;font-style:normal;font-weight:700}.today-worked-card span{font-size:11px;color:#6f7b8a}.today-worked-card strong{display:block;font-size:20px;margin-top:2px}.today-worked-analytics{display:grid;grid-template-columns:1.4fr 1fr 1fr;gap:14px;margin-top:14px}.today-worked-analytics .pending-chart{height:100%}.today-worked-chart{margin-top:0;background:#fff;border:1px solid #e4e8ef;border-radius:15px;padding:18px 18px 14px;box-shadow:0 5px 18px rgba(18,33,56,.045)}.today-chart-bars{display:grid;grid-template-columns:repeat(8,minmax(70px,1fr));gap:12px;align-items:end;min-height:215px}.today-chart-col{display:grid;grid-template-rows:auto 155px auto;gap:6px;align-items:end;text-decoration:none;color:inherit;min-width:0;--chart-accent:var(--bsoerp-theme)}.today-chart-value{text-align:center;font-size:12px;font-weight:700;color:var(--chart-accent)}.today-chart-bar-wrap{height:155px;display:flex;align-items:flex-end;justify-content:center;border-bottom:1px solid #e6ebf1;background:repeating-linear-gradient(to top,transparent 0,transparent 38px,#f2f5f8 39px)}.today-chart-bar-wrap i{display:block;width:min(48px,58%);min-height:3px;border-radius:8px 8px 2px 2px;background:linear-gradient(180deg,color-mix(in srgb,var(--chart-accent) 82%,#ffffff),var(--chart-accent));transition:.2s}.today-chart-col:hover .today-chart-bar-wrap i{filter:brightness(.94)}.today-chart-col span{text-align:center;font-size:10px;color:var(--chart-accent);line-height:1.15;min-height:24px;font-weight:600}.bsoerp-app.bsoerp-theme-bw .today-chart-bar-wrap i{background:#111!important}.bsoerp-app.bsoerp-theme-bw .pending-kpi:before,.bsoerp-app.bsoerp-theme-bw .pending-bar-track i{background:#111!important}.bsoerp-app.bsoerp-theme-bw .pending-kpi-icon,.bsoerp-app.bsoerp-theme-bw .today-worked-card i{background:#f0f0f0!important;color:#111!important}@media(max-width:1300px){.today-worked-analytics{grid-template-columns:1fr 1fr}.today-worked-analytics .today-module-chart{grid-column:1/-1}.pending-kpis{grid-template-columns:repeat(4,minmax(0,1fr))}.today-worked-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.pending-chart-grid{grid-template-columns:repeat(4,minmax(0,1fr))}.today-chart-bars{grid-template-columns:repeat(8,minmax(60px,1fr));overflow-x:auto}}@media(max-width:1150px){.pending-chart-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:850px){.today-worked-analytics{grid-template-columns:1fr}.today-worked-analytics .today-module-chart{grid-column:auto}.pending-chart-grid{grid-template-columns:1fr}.pending-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.today-worked-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.today-chart-bars{grid-template-columns:repeat(8,82px);overflow-x:auto;padding-bottom:5px}}@media(max-width:520px){.pending-kpis,.today-worked-grid{grid-template-columns:1fr}}
