 function installation_item_name($line){if(!$line)return'—';$lm=json_decode((string)($line->meta??''),true);if(!is_array($lm))$lm=[];$name=trim((string)($lm['item_name']??''));if($name!=='')return$name;if(!empty($line->item_id)){$_n=$this->master_name_by_id((int)$line->item_id);if($_n&&$_n!=='—')return$_n;}return'—';}
 function installation_item_completed($line_item_id){global$wpdb;return(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(completed_qty),0) FROM {$this->t('installation_update_items')} WHERE line_item_id=%d",absint($line_item_id)));}
 function installation_update_form($installation_id){
  global$wpdb;$installation_id=absint($installation_id);$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='installation' AND record_type='installation'",$installation_id));if(!$r)return;
  $meta=json_decode((string)$r->meta,true);if(!is_array($meta))$meta=[];$certificate_required=(string)($meta['certificate_applicable']??'')==='1';$lines=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$this->t('line_items')} WHERE record_id=%d ORDER BY sort_order,id",$installation_id));$pending=[];foreach($lines as$l){$done=$this->installation_item_completed($l->id);$left=max(0,(float)$l->qty-$done);if($left>0.0001)$pending[]=['row'=>$l,'done'=>$done,'left'=>$left];}
  echo'<div class="installation-update-modal"><div class="installation-update-card"><div class="panel-head"><div><h2>Update Installation</h2><p>'.esc_html($r->reference_no).'</p></div><a class="btn" href="'.esc_url($this->url('pending-installation')).'">×</a></div><form class="erp-form" method="post" enctype="multipart/form-data" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field(self::NONCE,'nonce');echo'<input type="hidden" name="action" value="bsoerp_save_installation_update"><input type="hidden" name="installation_id" value="'.$installation_id.'"><div class="form-grid"><label><span>Update Date *</span><input type="date" name="update_date" value="'.esc_attr(current_time('Y-m-d')).'" required></label>';
  if($certificate_required)echo'<label><span>Installation Certificate *</span><input type="file" name="installation_certificate" accept="image/*,.pdf" required></label>';else echo'<label><span>Installation Certificate</span><input type="file" name="installation_certificate" accept="image/*,.pdf"></label>';
  echo'</div><div class="table-wrap"><table class="data"><thead><tr><th>Sl.</th><th>Item</th><th>Description</th><th>Qty</th><th>Already Installed</th><th>Pending</th><th>Update Qty</th></tr></thead><tbody>';
  if(!$pending)echo'<tr><td colspan="7">No pending items.</td></tr>';else foreach($pending as$i=>$x){$l=$x['row'];echo'<tr><td>'.($i+1).'</td><td>'.esc_html($this->installation_item_name($l)).'</td><td>'.esc_html($l->description?:'—').'</td><td>'.esc_html(number_format_i18n((float)$l->qty,3)).'</td><td>'.esc_html(number_format_i18n($x['done'],3)).'</td><td>'.esc_html(number_format_i18n($x['left'],3)).'</td><td><input type="hidden" name="items['.(int)$l->id.'][line_item_id]" value="'.(int)$l->id.'"><input type="number" min="0" max="'.esc_attr($x['left']).'" step="0.001" name="items['.(int)$l->id.'][completed_qty]" value="0"></td></tr>';}
  echo'</tbody></table></div><div class="form-actions"><button class="btn primary" type="submit">Save Installation Update</button><a class="btn" href="'.esc_url($this->url('pending-installation')).'">Cancel</a></div></form></div></div>';
 }
 function save_installation_update(){
  if(!is_user_logged_in()||!current_user_can('bsoerp_access')||!wp_verify_nonce($_POST['nonce']??'',self::NONCE))wp_die('Invalid request');global$wpdb;$id=absint($_POST['installation_id']??0);$r=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('records')} WHERE id=%d AND module='installation'",$id));if(!$r)wp_die('Installation not found.');$date=sanitize_text_field(wp_unslash($_POST['update_date']??''));if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))wp_die('Update Date is required.');$meta=json_decode((string)$r->meta,true);if(!is_array($meta))$meta=[];$cert_required=(string)($meta['certificate_applicable']??'')==='1';$certificate_id=0;
  if(!empty($_FILES['installation_certificate'])&&!empty($_FILES['installation_certificate']['name'])){require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';$certificate_id=media_handle_upload('installation_certificate',0);if(is_wp_error($certificate_id))wp_die('Unable to upload Installation Certificate: '.esc_html($certificate_id->get_error_message()));}elseif($cert_required)wp_die('Installation Certificate is required.');
  $items=(array)($_POST['items']??[]);$valid=[];$total_update=0;foreach($items as$x){$line_id=absint($x['line_item_id']??0);$qty=max(0,(float)($x['completed_qty']??0));if(!$line_id||$qty<=0)continue;$line=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('line_items')} WHERE id=%d AND record_id=%d",$line_id,$id));if(!$line)wp_die('Invalid Installation item.');$done=$this->installation_item_completed($line_id);$left=max(0,(float)$line->qty-$done);if($qty>$left+0.0001)wp_die('Update Qty cannot exceed Pending Qty.');$valid[]=[$line_id,$qty];$total_update+=$qty;}if(!$valid)wp_die('Enter Update Qty for at least one item.');
  $now=current_time('mysql');$wpdb->query('START TRANSACTION');try{$ok=$wpdb->insert($this->t('installation_updates'),['installation_id'=>$id,'update_date'=>$date,'certificate_id'=>(int)$certificate_id,'updated_by_user'=>$this->current_master_user_id()?:get_current_user_id(),'created_by'=>get_current_user_id(),'created_at'=>$now]);if(!$ok)throw new Exception($wpdb->last_error?:'Unable to save Installation update.');$uid=(int)$wpdb->insert_id;foreach($valid as[$line_id,$qty]){$ok=$wpdb->insert($this->t('installation_update_items'),['installation_update_id'=>$uid,'installation_id'=>$id,'line_item_id'=>$line_id,'completed_qty'=>$qty,'created_at'=>$now]);if(!$ok)throw new Exception($wpdb->last_error?:'Unable to save Installation item update.');}
   $lines=$wpdb->get_results($wpdb->prepare("SELECT id,qty FROM {$this->t('line_items')} WHERE record_id=%d",$id));$pending=0;$any_done=false;foreach($lines as$l){$done=$this->installation_item_completed($l->id);if($done>0)$any_done=true;if($done+0.0001<(float)$l->qty)$pending++;}$status=$pending===0?'Completed':($any_done?'Partly Completed':'Pending');$wpdb->update($this->t('records'),['status'=>$status,'updated_at'=>$now],['id'=>$id]);$this->activity($id,'installation','Installation Updated',$r->reference_no?:$r->title);$wpdb->query('COMMIT');}catch(Throwable$e){$wpdb->query('ROLLBACK');wp_die('Save failed: '.esc_html($e->getMessage()));}
  wp_safe_redirect(add_query_arg('notice','saved',$this->url($status==='Completed'?'installation-master':'pending-installation')));exit;
 }
 function installation_listing($v){
  global$wpdb;if(!empty($_GET['update_installation'])){return $this->installation_update_form(absint($_GET['update_installation']));}$where=["module='installation'","record_type='installation'"];$args=[];if($v==='pending-installation')$where[]="status IN ('Pending','In Progress','Partly Completed')";$s=sanitize_text_field(wp_unslash($_GET['s']??''));if($s){$like='%'.$wpdb->esc_like($s).'%';$where[]='(reference_no LIKE %s OR title LIKE %s)';$args=[$like,$like];}$page=max(1,absint($_GET['pg']??1));$per=$this->pagination_size();$off=($page-1)*$per;$base="FROM {$this->t('records')} WHERE ".implode(' AND ',$where);$total=(int)$wpdb->get_var($args?$wpdb->prepare("SELECT COUNT(*) $base",$args):"SELECT COUNT(*) $base");$rows=$wpdb->get_results($args?$wpdb->prepare("SELECT * $base ORDER BY id DESC LIMIT $per OFFSET $off",$args):"SELECT * $base ORDER BY id DESC LIMIT $per OFFSET $off");
  echo'<div class="panel listing-panel installation-listing"><div class="panel-head"><div><h2>'.esc_html($this->flat()[$v]).'</h2></div><div class="head-actions"><a class="btn primary" href="'.esc_url($this->url('add-installation')).'">＋ Add Installation</a></div></div><form class="toolbar" method="get"><input type="search" name="s" value="'.esc_attr($s).'" placeholder="Search"><button class="btn">Search</button></form>';
  if(!$rows)echo'<div class="empty"><strong>No Installation records found</strong></div>';else{echo'<div class="table-wrap"><table class="data installation-table"><thead><tr><th>Sl.</th><th>Installation No.</th><th>Date</th><th>Assigned To</th><th>Vendor</th><th>Customer</th><th>Installation Date</th><th>Certificate Applicable</th><th>Status</th><th>Action</th></tr></thead><tbody>';foreach($rows as$i=>$r){$m=json_decode((string)$r->meta,true);if(!is_array($m))$m=[];$detail_id='installation-detail-'.(int)$r->id;echo'<tr class="installation-main-row" data-detail="'.$detail_id.'"><td>'.(($page-1)*$per+$i+1).'</td><td><strong>'.esc_html($r->reference_no).'</strong></td><td>'.esc_html($r->record_date?date_i18n('d/m/Y',strtotime($r->record_date)):'—').'</td><td>'.esc_html($this->task_user_display_name((int)$r->assigned_to)?:'—').'</td><td>'.esc_html($this->master_name_by_id((int)$r->party_id)?:'—').'</td><td>'.esc_html($this->master_name_by_id((int)$r->customer_id)?:'—').'</td><td>'.esc_html(!empty($m['installation_date'])?date_i18n('d/m/Y',strtotime($m['installation_date'])):'—').'</td><td>'.(((string)($m['certificate_applicable']??''))==='1'?'Yes':'No').'</td><td><span class="status '.sanitize_html_class(strtolower(str_replace(' ','-',$r->status))).'">'.esc_html($r->status).'</span></td><td class="actions">';if($v==='pending-installation')echo'<a title="Update Installation" href="'.esc_url(add_query_arg('update_installation',(int)$r->id,$this->url('pending-installation'))).'">✓</a>';echo'<a title="Edit" href="'.esc_url(add_query_arg('edit',(int)$r->id,$this->url($v))).'">✎</a>';if(current_user_can('bsoerp_print')){$pdf_url=wp_nonce_url(admin_url('admin-post.php?action=bsoerp_print&id='.(int)$r->id),'bsoerp_print_'.$r->id);echo'<a class="pdf-download-action" title="Download Installation PDF" aria-label="Download Installation PDF" href="'.esc_url($pdf_url).'"><img src="'.esc_url(plugin_dir_url(__FILE__).'assets/pdf-icon.png?v='.self::VERSION).'" alt="PDF" width="18" height="18" style="display:block;width:18px;height:18px;object-fit:contain"></a>';}echo'</td></tr>';
    echo'<tr id="'.$detail_id.'" class="installation-detail-row" style="display:none"><td colspan="10">';$lines=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$this->t('line_items')} WHERE record_id=%d ORDER BY sort_order,id",$r->id));echo'<div class="table-wrap"><table class="data"><thead><tr><th>Sl.</th><th>Item</th><th>Description</th><th>Qty</th><th>Installed Qty</th><th>Pending Qty</th></tr></thead><tbody>';foreach($lines as$li=>$l){$done=$this->installation_item_completed($l->id);echo'<tr><td>'.($li+1).'</td><td>'.esc_html($this->installation_item_name($l)).'</td><td>'.esc_html($l->description?:'—').'</td><td>'.esc_html(number_format_i18n((float)$l->qty,3)).'</td><td>'.esc_html(number_format_i18n($done,3)).'</td><td>'.esc_html(number_format_i18n(max(0,(float)$l->qty-$done),3)).'</td></tr>';}echo'</tbody></table></div>';
    if($v==='installation-master'){$hist=$wpdb->get_results($wpdb->prepare("SELECT u.*,ui.line_item_id,ui.completed_qty FROM {$this->t('installation_updates')} u LEFT JOIN {$this->t('installation_update_items')} ui ON ui.installation_update_id=u.id WHERE u.installation_id=%d ORDER BY u.update_date DESC,u.id DESC,ui.id",$r->id));echo'<h3 style="margin-top:16px">Update History</h3>';if(!$hist)echo'<div class="empty"><strong>No update history</strong></div>';else{echo'<div class="table-wrap"><table class="data"><thead><tr><th>Update Date</th><th>Item</th><th>Updated Qty</th><th>Certificate</th><th>Updated By</th></tr></thead><tbody>';foreach($hist as$h){$line=$h->line_item_id?$wpdb->get_row($wpdb->prepare("SELECT * FROM {$this->t('line_items')} WHERE id=%d",$h->line_item_id)):null;$cert=$h->certificate_id?wp_get_attachment_url((int)$h->certificate_id):'';echo'<tr><td>'.esc_html(date_i18n('d/m/Y',strtotime($h->update_date))).'</td><td>'.esc_html($line?$this->installation_item_name($line):'—').'</td><td>'.esc_html(number_format_i18n((float)$h->completed_qty,3)).'</td><td>'.($cert?'<a target="_blank" href="'.esc_url($cert).'">View</a>':'—').'</td><td>'.esc_html($this->task_user_display_name((int)$h->updated_by_user)?:$this->user_display_name((int)$h->created_by)).'</td></tr>';}echo'</tbody></table></div>';}}
    echo'</td></tr>';}
   echo'</tbody></table></div><script>(function(){document.querySelectorAll(".installation-main-row").forEach(function(r){r.addEventListener("click",function(e){if(e.target.closest("a,button,input,select"))return;var d=document.getElementById(r.dataset.detail);if(d)d.style.display=d.style.display==="none"?"table-row":"none";});});})();</script>';}
  $this->pagination_controls($total,$page,$per,$this->url($v));echo'</div>';
 }
 function reports(){global$wpdb;$from=sanitize_text_field($_GET['from']??'');$to=sanitize_text_field($_GET['to']??'');$where="module<>'master'";$args=[];if($from){$where.=' AND record_date>=%s';$args[]=$from;}if($to){$where.=' AND record_date<=%s';$args[]=$to;}$sql="SELECT module,status,COUNT(*) total,SUM(amount) amount FROM {$this->t('records')} WHERE $where GROUP BY module,status ORDER BY module,status";$rows=$args?$wpdb->get_results($wpdb->prepare($sql,$args)):$wpdb->get_results($sql);echo'<div class="panel"><div class="panel-head"><div><h2>Management Reports</h2><p>Status, value, approvals and quantity balances</p></div></div><form class="toolbar"><label>From <input type="date" name="from" value="'.esc_attr($from).'"></label><label>To <input type="date" name="to" value="'.esc_attr($to).'"></label><button class="btn">Apply</button></form><div class="table-wrap"><table class="data"><thead><tr><th>Module</th><th>Status</th><th>Records</th><th>Value</th></tr></thead><tbody>';foreach($rows as$r)echo'<tr><td>'.esc_html(ucwords(str_replace('-',' ',$r->module))).'</td><td>'.esc_html($r->status).'</td><td>'.$r->total.'</td><td>'.esc_html(number_format_i18n($r->amount,2)).'</td></tr>';echo'</tbody></table></div></div>';$q=$wpdb->get_results("SELECT r.module,COUNT(*) docs,SUM(l.qty) qty,SUM(l.produced_qty) produced,SUM(l.delivered_qty) delivered,SUM(l.received_qty) received,SUM(l.rejected_qty) rejected FROM {$this->t('records')} r JOIN {$this->t('line_items')} l ON l.record_id=r.id WHERE r.module IN ('orders','production','deliveries','purchase-orders','grn') AND r.status<>'Canceled' GROUP BY r.module");echo'<div class="panel"><div class="panel-head"><div><h2>Quantity Summary</h2><p>Ordered, produced, delivered, received and rejected quantities</p></div></div><div class="table-wrap"><table class="data"><thead><tr><th>Module</th><th>Documents</th><th>Document Qty</th><th>Produced</th><th>Delivered</th><th>Received</th><th>Rejected</th></tr></thead><tbody>';foreach($q as$r)echo'<tr><td>'.esc_html(ucwords(str_replace('-',' ',$r->module))).'</td><td>'.$r->docs.'</td><td>'.esc_html($r->qty).'</td><td>'.esc_html($r->produced).'</td><td>'.esc_html($r->delivered).'</td><td>'.esc_html($r->received).'</td><td>'.esc_html($r->rejected).'</td></tr>';echo'</tbody></table></div></div>';}
 function notifications(){global$wpdb;$page=max(1,absint($_GET['pg']??1));$per=$this->pagination_size();$off=($page-1)*$per;$where="((due_date<CURDATE() AND status NOT IN ('Completed','Delivered','Canceled')) OR status='Pending Approval')";$total=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$this->t('records')} WHERE $where");$rows=$wpdb->get_results("SELECT * FROM {$this->t('records')} WHERE $where ORDER BY due_date,updated_at DESC LIMIT $per OFFSET $off");echo'<div class="panel"><div class="panel-head"><div><h2>Notifications</h2></div></div>';if(!$rows)echo'<div class="empty"><strong>No notifications</strong><span>Nothing currently requires attention.</span></div>';else$this->table($rows);$this->pagination_controls($total,$page,$per,$this->url('notifications'));echo'</div>';}

 function admin_backup_settings(){
  if(!current_user_can('manage_options'))wp_die('Access denied');
  $s=get_option('bsoerp_settings',[]);if(!is_array($s))$s=[];
  $backup_active=(string)($s['backup_active']??'0');
  $backup_time=(string)($s['backup_time']??'19:00');
  $backup_email=(string)($s['backup_email']??get_option('admin_email'));
  $download=wp_nonce_url(admin_url('admin-post.php?action=bsoerp_download_backup'),'bsoerp_download_backup');
