  $opt_like=$wpdb->esc_like('bsoerp_').'%';$options=$wpdb->get_results($wpdb->prepare("SELECT option_name,option_value,autoload FROM {$wpdb->options} WHERE option_name LIKE %s",$opt_like),ARRAY_A);$zip->addFromString('options.json',wp_json_encode($options,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
