  $attachment_ids=$this->backup_attachment_ids($tables,$options);$attachment_rows=[];$attachment_meta=[];$up=wp_upload_dir();foreach($attachment_ids as$aid){$post=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$wpdb->posts} WHERE ID=%d AND post_type='attachment'",$aid),ARRAY_A);if(!$post)continue;$attachment_rows[]=$post;$meta=$wpdb->get_results($wpdb->prepare("SELECT * FROM {$wpdb->postmeta} WHERE post_id=%d",$aid),ARRAY_A);foreach((array)$meta as$m)$attachment_meta[]=$m;$rel=get_post_meta($aid,'_wp_attached_file',true);if($rel){$file=trailingslashit($up['basedir']).ltrim($rel,'/');if(is_file($file))$zip->addFile($file,'uploads/'.ltrim($rel,'/'));$md=wp_get_attachment_metadata($aid);if(is_array($md)&&!empty($md['sizes'])&&is_array($md['sizes'])){foreach($md['sizes'] as$sz){if(empty($sz['file']))continue;$thumb=trailingslashit(dirname($file)).$sz['file'];$thumbrel=trailingslashit(dirname($rel)).$sz['file'];if(is_file($thumb))$zip->addFile($thumb,'uploads/'.ltrim($thumbrel,'/'));}}}}
  $zip->addFromString('attachments.json',wp_json_encode(['posts'=>$attachment_rows,'postmeta'=>$attachment_meta],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));
