 function backup_restore_zip($zip_path){
  global $wpdb;if(!class_exists('ZipArchive'))return new WP_Error('zip','ZIP support is not available on this server.');$zip=new ZipArchive();if($zip->open($zip_path)!==true)return new WP_Error('invalid_zip','Unable to open backup ZIP.');$manifest_raw=$zip->getFromName('manifest.json');$manifest=json_decode((string)$manifest_raw,true);if(!is_array($manifest)||($manifest['type']??'')!=='BizSkill ERP Full Backup'){$zip->close();return new WP_Error('invalid_backup','This is not a valid BizSkill ERP backup file.');}
  $current=$this->backup_create_zip('pre-restore');if(is_wp_error($current)){$zip->close();return$current;} // safety copy retained only during restore
  $wpdb->query('START TRANSACTION');try{
   $tables=$this->backup_table_names();foreach($tables as$table){$entry='tables/'.sanitize_file_name($table).'.json';$raw=$zip->getFromName($entry);if($raw===false)continue;$rows=json_decode($raw,true);if(!is_array($rows))throw new Exception('Invalid table data for '.$table);$wpdb->query("DELETE FROM `$table`");foreach($rows as$row){if(!is_array($row))continue;$ok=$wpdb->replace($table,$row);if($ok===false)throw new Exception($wpdb->last_error?:'Unable to restore '.$table);}}
   $oraw=$zip->getFromName('options.json');$opts=json_decode((string)$oraw,true);if(is_array($opts))foreach($opts as$o){if(empty($o['option_name']))continue;$wpdb->replace($wpdb->options,['option_name'=>$o['option_name'],'option_value'=>$o['option_value']??'','autoload'=>$o['autoload']??'no']);}
   $uraw=$zip->getFromName('erp-users.json');$ud=json_decode((string)$uraw,true);if(is_array($ud)){foreach((array)($ud['users']??[]) as$u){if(!is_array($u)||empty($u['ID']))continue;$wpdb->replace($wpdb->users,$u);}foreach((array)($ud['usermeta']??[]) as$um){if(!is_array($um)||empty($um['umeta_id']))continue;$wpdb->replace($wpdb->usermeta,$um);}}
   $araw=$zip->getFromName('attachments.json');$ad=json_decode((string)$araw,true);if(is_array($ad)){foreach((array)($ad['posts']??[]) as$p){if(is_array($p)&&!empty($p['ID']))$wpdb->replace($wpdb->posts,$p);}foreach((array)($ad['postmeta']??[]) as$pm){if(is_array($pm)&&!empty($pm['meta_id']))$wpdb->replace($wpdb->postmeta,$pm);}}
   $up=wp_upload_dir();for($i=0;$i<$zip->numFiles;$i++){$name=$zip->getNameIndex($i);if(strpos($name,'uploads/')!==0||substr($name,-1)==='/')continue;$rel=substr($name,8);if(strpos($rel,'..')!==false)continue;$dest=trailingslashit($up['basedir']).ltrim($rel,'/');wp_mkdir_p(dirname($dest));$stream=$zip->getStream($name);if(!$stream)continue;$out=fopen($dest,'wb');if(!$out){fclose($stream);throw new Exception('Unable to restore uploaded file.');}while(!feof($stream))fwrite($out,fread($stream,8192));fclose($out);fclose($stream);}
   $wpdb->query('COMMIT');
  }catch(Exception$e){$wpdb->query('ROLLBACK');$zip->close();@unlink($current['path']);return new WP_Error('restore_failed',$e->getMessage());}
  $zip->close();@unlink($current['path']);wp_cache_flush();$this->activate();return true;
 }
