 function save_settings(){
  if(!current_user_can('bsoerp_manage')||!wp_verify_nonce($_POST['nonce']??'','bsoerp_settings'))wp_die('Invalid');
  $s=get_option('bsoerp_settings',[]);if(!is_array($s))$s=[];
  $s['company']=sanitize_text_field(wp_unslash($_POST['company']??'BizSkill'));
  $s['company_phone']=sanitize_text_field(wp_unslash($_POST['company_phone']??''));
  $s['company_website']=sanitize_text_field(wp_unslash($_POST['company_website']??''));
  $s['company_email']=sanitize_email(wp_unslash($_POST['company_email']??''));
  $s['company_gstin']=sanitize_text_field(wp_unslash($_POST['company_gstin']??''));
  $s['bank_details']=sanitize_textarea_field(wp_unslash($_POST['bank_details']??''));
  $s['company_notes']=sanitize_textarea_field(wp_unslash($_POST['company_notes']??''));
  $s['quotation_terms']=sanitize_textarea_field(wp_unslash($_POST['quotation_terms']??''));
  $s['company_address']=sanitize_textarea_field(wp_unslash($_POST['company_address']??''));
  $company_info=[];if($s['company_phone']!=='')$company_info[]='Phone: '.$s['company_phone'];if($s['company_address']!=='')$company_info[]='Address: '.$s['company_address'];if($s['company_gstin']!=='')$company_info[]='GSTIN: '.$s['company_gstin'];if($s['company_website']!=='')$company_info[]='Website: '.$s['company_website'];if($s['company_email']!=='')$company_info[]='Email: '.$s['company_email'];$s['company_info']=implode("\n",$company_info);
  if(!empty($_FILES['company_logo'])&&!empty($_FILES['company_logo']['name'])){require_once ABSPATH.'wp-admin/includes/file.php';require_once ABSPATH.'wp-admin/includes/media.php';require_once ABSPATH.'wp-admin/includes/image.php';$logo_id=media_handle_upload('company_logo',0);if(is_wp_error($logo_id))wp_die('Unable to upload Company Logo: '.esc_html($logo_id->get_error_message()));$s['logo_id']=(int)$logo_id;}
  $s['daily_activity_report_active']=!empty($_POST['daily_activity_report_active'])?'1':'0';
  $s['daily_activity_report_number']=preg_replace('/[^0-9,;+ ]/','',sanitize_text_field(wp_unslash($_POST['daily_activity_report_number']??'')));
  $dar_time=sanitize_text_field(wp_unslash($_POST['daily_activity_report_time']??'19:00'));$s['daily_activity_report_time']=preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$dar_time)?$dar_time:'19:00';
  
  $theme_style=sanitize_key($_POST['theme_style']??'theme_color');if(!in_array($theme_style,['theme_color','black_white'],true))$theme_style='theme_color';$theme_color=sanitize_hex_color(wp_unslash($_POST['theme_color']??''))?:'#12b8a6';$existing_theme=is_array($s['theme']??null)?$s['theme']:[];$s['theme']=array_merge($existing_theme,['theme_style'=>$theme_style,'theme_color'=>$theme_color]);
  if(isset($_POST['wa_templates'])&&is_array($_POST['wa_templates'])){
   $clean=[];foreach(wp_unslash($_POST['wa_templates']) as$k=>$t){if(!is_array($t))continue;$clean[sanitize_key($k)]=[
    'name'=>sanitize_text_field($t['name']??''),'module'=>sanitize_text_field($t['module']??''),'event'=>sanitize_text_field($t['event']??''),
    'recipient'=>sanitize_text_field($t['recipient']??''),'code'=>sanitize_text_field($t['code']??''),'type'=>sanitize_text_field($t['type']??'Utility'),
    'language'=>sanitize_text_field($t['language']??'English'),'auto'=>!empty($t['auto'])?'1':'0','active'=>!empty($t['active'])?'1':'0',
    'body'=>sanitize_textarea_field($t['body']??'')
   ];}update_option('bsoerp_whatsapp_templates',$clean,false);
  }
  if(isset($_POST['wa_meta'])&&is_array($_POST['wa_meta'])){
   $wm=wp_unslash($_POST['wa_meta']);update_option('bsoerp_whatsapp_meta',[
    'enabled'=>!empty($wm['enabled'])?'1':'0','business_account_id'=>sanitize_text_field($wm['business_account_id']??''),
    'phone_number_id'=>sanitize_text_field($wm['phone_number_id']??''),'access_token'=>trim((string)($wm['access_token']??'')),
    'country_code'=>preg_replace('/\\D+/','',sanitize_text_field($wm['country_code']??'91')),
    'api_version'=>sanitize_text_field($wm['api_version']??'v23.0'),
    'test_mobile'=>preg_replace('/\\D+/','',sanitize_text_field($wm['test_mobile']??''))
   ],false);
  }
  if(!empty($_POST['wa_test_token']))$this->whatsapp_test_token();
  if(!empty($_POST['wa_send_test']))$this->whatsapp_send_test_message();
  update_option('bsoerp_settings',$s,false);$this->ensure_daily_activity_cron();$this->ensure_backup_cron();delete_transient('bsoerp_daily_activity_request_lock');delete_transient('bsoerp_backup_cron_lock');
  wp_safe_redirect(add_query_arg('notice','saved',$this->url('settings')));exit;
 }
 function tool($v){if(!current_user_can('manage_options')){echo'<div class="notice">Administrator access is required.</div>';return;}if(isset($_POST['run'])&&check_admin_referer('bsoerp_tool_'.$v)){$message='';if($v==='rebuild-pages'){$this->create_pages(true);$message='Pages rebuilt successfully.';}elseif($v==='rebuild-database'){$this->activate();$message='Database structure checked and safely upgraded.';}elseif($v==='clear-cache'){wp_cache_flush();$message='WordPress object cache cleared.';}if($message)echo'<div class="notice success">'.esc_html($message).'</div>';}echo'<div class="panel"><div class="panel-head"><div><h2>'.esc_html($this->flat()[$v]).'</h2><p>System administration utility</p></div></div>';if(in_array($v,['rebuild-pages','rebuild-database','clear-cache'])){echo'<form method="post">';wp_nonce_field('bsoerp_tool_'.$v);echo'<button class="btn primary" name="run">'.esc_html($v==='rebuild-pages'?'Rebuild All ERP Pages':($v==='rebuild-database'?'Check and Upgrade Database':'Clear Object Cache')).'</button></form>';}elseif($v==='system-health'){global$wpdb;$tables=0;foreach(['records','line_items','activity','notifications','approvals']as$t)if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$this->t($t)))===$this->t($t))$tables++;echo'<div class="settings-grid"><div><b>Plugin</b><span>'.self::VERSION.'</span></div><div><b>PHP</b><span>'.PHP_VERSION.'</span></div><div><b>WordPress</b><span>'.get_bloginfo('version').'</span></div><div><b>Database Tables</b><span>'.$tables.'/4 available</span></div><div><b>Timezone</b><span>'.esc_html(wp_timezone_string()).'</span></div><div><b>ERP Pages</b><span>'.count(get_option(self::PAGES,[])).' registered</span></div></div>';}else echo'<div class="empty"><strong>Use Excel export from each register</strong><span>CSV import requires a finalized column template and is intentionally disabled to prevent incorrect data mapping.</span></div>';echo'</div>';}
 function notice(){$n=sanitize_key($_GET['notice']??'');if($n==='deleted')echo'<div class="notice success">Record deleted successfully.</div>';elseif($n==='canceled')echo'<div class="notice success">Order canceled successfully.</div>';elseif($n==='work_order_canceled')echo'<div class="notice success">Work Order canceled successfully.</div>';elseif($n==='quotation_canceled')echo'<div class="notice success">Quotation canceled successfully.</div>';}
}
BSOERP_Complete::instance();
